var TC_CH={"A": {"A01": "坐標系與函數圖形", "A02": "直線方程式", "A03": "式的運算", "A04": "三角函數", "A05": "圓與直線", "A06": "數列與級數", "A07": "不等式及其應用", "A08": "指數與對數", "A09": "排列組合", "A10": "機率與統計"}, "B": {"B01": "坐標系與函數圖形", "B02": "直線方程式", "B03": "式的運算", "B04": "三角函數", "B05": "平面向量", "B06": "圓與直線", "B07": "數列與級數", "B08": "方程式", "B09": "二元一次不等式及其應用", "B10": "指數與對數", "B11": "三角函數的應用", "B12": "排列組合", "B13": "機率與統計"}, "C": {"C01": "坐標系與函數圖形", "C02": "三角函數", "C03": "平面向量", "C04": "式的運算", "C05": "直線與圓", "C06": "數列與級數", "C07": "排列組合與機率統計", "C08": "三角函數的應用", "C09": "指數與對數", "C10": "空間向量", "C11": "一次聯立方程式與矩陣", "C12": "二元一次不等式與線性規劃", "C13": "二次曲線", "C14": "微分", "C15": "積分"}};
var TC=[{"id": "111A-1", "y": 111, "p": "A", "no": 1, "ch": "A07", "img": "img/tc/111A_1.webp", "a": 2, "t": "絕對值不等式的整數解", "c": "$|x-a|\\lt r$ 的意思是「$x$ 到 $a$ 的距離小於 $r$」，可以改寫成 $a-r\\lt x\\lt a+r$。", "st": [["拆掉絕對值", "$|x-1|\\lt 4 \\Rightarrow -4\\lt x-1\\lt 4 \\Rightarrow -3\\lt x\\lt 5$。"], ["數整數", "整數有 $-2,-1,0,1,2,3,4$，共 $7$ 個，選 (C)。"]], "tr": "端點 $-3$、$5$ 不能算進去，因為是「小於」不是「小於等於」。"}, {"id": "111A-2", "y": 111, "p": "A", "no": 2, "ch": "A07", "img": "img/tc/111A_2.webp", "a": 3, "t": "聯立不等式的圖解區域", "c": "每個不等式先畫直線，再拿原點 $(0,0)$ 代入判斷要取哪一側，最後取兩側的交集。", "st": [["判斷 x+y≦2", "直線過 $(2,0)$、$(0,2)$；原點代入 $0\\le 2$ 成立，所以取<b>含原點的那一側</b>（直線左下方）。"], ["判斷 3x+y≧3", "直線過 $(1,0)$、$(0,3)$；原點代入 $0\\ge 3$ 不成立，所以取<b>不含原點的那一側</b>（直線右上方）。"], ["取交集", "兩直線交於 $(\\frac{1}{2},\\frac{3}{2})$，交集是從交點往右下方張開、夾在兩線之間的區域，就是 (D) 的陰影，選 (D)。"]], "tr": "直線畫對了，但判斷方向時忘記用原點代入檢查，容易選到反方向的區域。"}, {"id": "111A-3", "y": 111, "p": "A", "no": 3, "ch": "A08", "img": "img/tc/111A_3.webp", "a": 3, "t": "負指數的計算", "c": "$a^{-2}=\\frac{1}{a^2}$，底數是分數時，負指數就是把分數倒過來。", "st": [["分別算出每一項", "$a^2=\\frac{1}{4}$，$a^{-2}=\\left(\\frac{1}{2}\\right)^{-2}=2^2=4$。"], ["相加", "$\\frac{1}{4}+2+4=\\frac{25}{4}$，選 (D)。<br>（也可以看成 $(a+a^{-1})^2=(\\frac{1}{2}+2)^2=\\frac{25}{4}$）"]], "tr": "把 $a^{-2}$ 誤算成 $-\\frac{1}{4}$，負指數不是變負數，是取倒數。"}, {"id": "111A-4", "y": 111, "p": "A", "no": 4, "ch": "A08", "img": "img/tc/111A_4.webp", "a": 2, "t": "對數加法：log5+log2=1", "c": "同底對數相加等於真數相乘：$\\log M+\\log N=\\log(MN)$。", "st": [["逐一檢查", "(A) $\\log5+\\log2=a+b$，不是 $a\\times b$，錯。<br>(B) $\\frac{a}{b}=\\frac{\\log5}{\\log2}$，不是 $\\frac{5}{2}$，錯。<br>(D) $a-b=\\log\\frac{5}{2}$，不是 $\\frac{\\log5}{\\log2}$，錯。"], ["確認 (C)", "$a+b=\\log5+\\log2=\\log10=1$，正確，選 (C)。"]], "tr": "把 $\\log M-\\log N=\\log\\frac{M}{N}$ 和 $\\frac{\\log M}{\\log N}$ 搞混。"}, {"id": "111A-5", "y": 111, "p": "A", "no": 5, "ch": "A03", "img": "img/tc/111A_5.webp", "a": 0, "t": "乘法公式：差的立方", "c": "$a^3-3a^2b+3ab^2-b^3=(a-b)^3$，看到這個長相就直接套公式，不用硬算。", "st": [["認出公式", "令 $a=\\frac{7}{8}$、$b=\\frac{3}{8}$，整個式子就是 $(a-b)^3$。"], ["代入", "$(a-b)^3=\\left(\\frac{7}{8}-\\frac{3}{8}\\right)^3=\\left(\\frac{1}{2}\\right)^3=\\frac{1}{8}$，選 (A)。"]], "tr": "一項一項硬算分數，既慢又容易算錯。"}, {"id": "111A-6", "y": 111, "p": "A", "no": 6, "ch": "A06", "img": "img/tc/111A_6.webp", "a": 1, "t": "等差數列：每週減量求週數", "c": "每週固定減少 $3.5$ 錠，就是公差 $-3.5$ 的等差數列，求第幾項等於最後一週的量。", "st": [["找首項與末項", "第一週：每天 $2$ 錠，共 $14$ 錠。<br>最後一週：每天半錠，共 $0.5\\times7=3.5$ 錠。"], ["用一般項求 n", "$a_n=14+(n-1)(-3.5)=3.5 \\Rightarrow (n-1)\\times3.5=10.5 \\Rightarrow n=4$。<br>列出來也很快：$14,\\ 10.5,\\ 7,\\ 3.5$，共 $4$ 週，選 (B)。"]], "tr": "把「每週減 3.5 錠」當成每天減 3.5 錠，單位要先統一成「每週」。"}, {"id": "111A-7", "y": 111, "p": "A", "no": 7, "ch": "A07", "img": "img/tc/111A_7.webp", "a": 3, "t": "點在直線的同側或異側", "c": "把點代入 $ax+by+c$，正負號相同就在同一側，異號就在兩側。", "st": [["先算 (1,1)", "$3(1)+4(1)+5=12\\gt 0$。"], ["代入各選項", "(A) $-3-4+5=-2\\lt 0$<br>(B) $3-12+5=-4\\lt 0$<br>(C) $-3-8+5=-6\\lt 0$<br>(D) $-6+4+5=3\\gt 0$"], ["找同號", "只有 $(-2,1)$ 也是正的，跟 $(1,1)$ 同側，選 (D)。"]], "tr": "代入時漏掉常數項 $+5$，正負號就會判斷錯。"}, {"id": "111A-8", "y": 111, "p": "A", "no": 8, "ch": "A10", "img": "img/tc/111A_8.webp", "a": 0, "t": "只用最高最低分→全距", "c": "全距＝最大值－最小值，只需要最高分和最低分就能算。", "st": [["看各統計量需要的資料", "四分位距要 $Q_1$、$Q_3$；標準差、變異數要用到每一筆資料。"], ["結論", "只有最高分和最低分，能算的分散程度只有<b>全距</b>，選 (A)。"]], "tr": ""}, {"id": "111A-9", "y": 111, "p": "A", "no": 9, "ch": "A01", "img": "img/tc/111A_9.webp", "a": 0, "t": "二次函數配方求頂點", "c": "把 $f(x)$ 配方成 $(x-h)^2+k$，頂點就是 $(h,k)$。", "st": [["配方", "$f(x)=x^2+6x-3=(x+3)^2-9-3=(x+3)^2-12$。"], ["讀出頂點", "頂點 $(-3,-12)$，所以 $m=-3$、$n=-12$。"], ["代入", "$2m-n=-6+12=6$，選 (A)。"]], "tr": "$(x+3)^2$ 的頂點 $x$ 坐標是 $-3$，不是 $+3$。"}, {"id": "111A-10", "y": 111, "p": "A", "no": 10, "ch": "A01", "img": "img/tc/111A_10.webp", "a": 1, "t": "溫差換算：攝氏差×9/5", "c": "$F=\\frac{9}{5}C+32$，算「溫差」時兩邊的 $+32$ 會互相抵消，所以溫差只要乘 $\\frac{9}{5}$。", "st": [["溫差相減", "$F_1-F_2=\\frac{9}{5}(C_1-C_2)$，常數 $32$ 消掉了。"], ["代入", "$\\frac{9}{5}\\times9=16.2\\approx16$ 度，選 (B)。"]], "tr": "直接套 $\\frac{9}{5}\\times9+32=48.2$，選成 (D)；溫差不用加 32。"}, {"id": "111A-11", "y": 111, "p": "A", "no": 11, "ch": "A04", "img": "img/tc/111A_11.webp", "a": 0, "t": "反射等角：正切比例", "c": "$\\angle CAB=\\angle TAS$，兩個直角三角形的 $\\tan$ 值相同，對邊比鄰邊會成比例。", "st": [["算 tan∠TAS", "在直角 $\\triangle TSA$ 中：$\\tan\\angle TAS=\\frac{TS}{SA}=\\frac{120}{250}$。"], ["列比例", "在直角 $\\triangle CBA$ 中：$\\tan\\angle CAB=\\frac{CB}{450}$。<br>兩角相等：$\\frac{CB}{450}=\\frac{120}{250}$。"], ["求 CB", "$CB=450\\times\\frac{12}{25}=216$ 公尺，選 (A)。"]], "tr": "把比例寫反成 $\\frac{450}{CB}=\\frac{120}{250}$，對邊、鄰邊要對應好。"}, {"id": "111A-12", "y": 111, "p": "A", "no": 12, "ch": "A03", "img": "img/tc/111A_12.webp", "a": 0, "t": "除法原理與餘式定理", "c": "先用除法原理寫出 $f(x)$，再用餘式定理：除以 $(x-1)(x-3)$ 的餘式 $ax+b$ 在 $x=1,3$ 時要和 $f$ 相等。", "st": [["寫出 f(x)", "$f(x)=(x-2)(x-3)(2x-3)(x-1)+2x+3$。"], ["代 x=1、x=3", "前面那串乘積在 $x=1$、$x=3$ 都是 $0$：<br>$f(1)=5$，$f(3)=9$。"], ["解聯立", "$a+b=5$、$3a+b=9$，得 $a=2$、$b=3$，$a-b=-1$，選 (A)。"]], "tr": "想把 $f(x)$ 整個展開再做長除法，計算量太大；直接代值最快。"}, {"id": "111A-13", "y": 111, "p": "A", "no": 13, "ch": "A04", "img": "img/tc/111A_13.webp", "a": 1, "t": "看圖：f(π/6)≈sin(π/6)", "c": "題目說 $f(x)$ 在 $-0.4\\lt x\\lt 1.3$ 和 $\\sin x$ 幾乎一樣，那就不用代那串大式子，直接算 $\\sin x$。", "st": [["確認範圍", "$\\frac{\\pi}{6}\\approx0.52$，在 $-0.4$ 到 $1.3$ 之間，所以 $f(\\frac{\\pi}{6})\\approx\\sin\\frac{\\pi}{6}$。"], ["算出值", "$\\sin\\frac{\\pi}{6}=\\frac{1}{2}$，誤差小於 $0.03$，最接近 $\\frac{1}{2}$，選 (B)。"]], "tr": "被嚇人的多項式唬住、硬代 $\\pi$ 去算，浪費時間又容易錯。"}, {"id": "111A-14", "y": 111, "p": "A", "no": 14, "ch": "A09", "img": "img/tc/111A_14.webp", "a": 2, "t": "乘法原理：各人選項數相乘", "c": "四個人各自選、互不影響，把每個人的選法數相乘。", "st": [["數每人的選法", "甲（莫德納）、乙（BNT）、丙（高端）前兩劑不是 AZ，追加劑可選 4 種。<br>丁前兩劑是 AZ，追加劑只能選 3 種（莫德納、BNT、高端）。"], ["相乘", "$4\\times4\\times4\\times3=192$，選 (C)。"]], "tr": "以為打過的廠牌不能再打而扣掉，其實題目只限制 AZ 那組不能再選 AZ。"}, {"id": "111A-15", "y": 111, "p": "A", "no": 15, "ch": "A10", "img": "img/tc/111A_15.webp", "a": 3, "t": "抽整群→部落抽樣", "c": "先把母體分成很多群，隨機抽出幾「群」，再對抽到的群全部調查，就是部落（群集）抽樣。", "st": [["看抽樣方式", "以「班級」為單位抽 5 個班，抽到的班<b>全部同學都普查</b>。"], ["對照名稱", "這就是部落抽樣，選 (D)。"]], "tr": "和分層抽樣搞混：分層是「每一層都要抽一些人」，部落是「抽幾群、群內全查」。"}, {"id": "111A-16", "y": 111, "p": "A", "no": 16, "ch": "A09", "img": "img/tc/111A_16.webp", "a": 2, "t": "組合：各選兩個再相乘", "c": "不考慮順序用組合 $C^n_k$，咖啡和酥餅分開選，再用乘法原理相乘。", "st": [["分別選", "咖啡 4 選 2：$C^4_2=6$；酥餅 4 選 2：$C^4_2=6$。"], ["相乘", "$6\\times6=36$，選 (C)。"]], "tr": "用排列 $P^4_2=12$ 來算就會重複，題目說不考慮順序。"}, {"id": "111A-17", "y": 111, "p": "A", "no": 17, "ch": "A10", "img": "img/tc/111A_17.webp", "a": 2, "t": "期望值的線性性質", "c": "$E(aX+b)=aE(X)+b$：每個結果都乘 $a$ 再加 $b$，期望值也照樣乘 $a$ 加 $b$。", "st": [["套性質", "獲得金額 $=80X+5$，$E(X)=3.5$。"], ["計算", "$80\\times3.5+5=280+5=285$ 元，選 (C)。"]], "tr": "忘記加 $5$ 而選 (A) 280。"}, {"id": "111A-18", "y": 111, "p": "A", "no": 18, "ch": "A05", "img": "img/tc/111A_18.webp", "a": 1, "t": "面積等差→中圓半徑平方", "c": "圓面積 $=\\pi r^2$，三個面積成等差，中項就是兩端的平均。", "st": [["算大小圓面積", "大圓 $9\\pi$，小圓 $\\pi$。"], ["等差中項", "中圓面積 $=\\frac{9\\pi+\\pi}{2}=5\\pi$，所以 $r^2=5$。"], ["寫方程式", "圓心 $(1,-1)$：$(x-1)^2+(y+1)^2=5$，選 (B)。"]], "tr": "以為是「半徑」成等差而得 $r=2$、$r^2=4$；題目說的是<b>面積</b>。"}, {"id": "111A-19", "y": 111, "p": "A", "no": 19, "ch": "A06", "img": "img/tc/111A_19.webp", "a": 2, "t": "等比數列：每次剩 8/9", "c": "每剪一次，每個正方形 9 等分只剪掉中間 1 塊，面積都剩原來的 $\\frac{8}{9}$，是公比 $\\frac{8}{9}$ 的等比數列。", "st": [["看一次剪裁", "第 1 次後剩 $\\frac{8}{9}$；第 2 次每個小正方形又只剩 $\\frac{8}{9}$，總共剩 $\\left(\\frac{8}{9}\\right)^2$。"], ["推到第 6 次", "剪 6 次後剩 $\\left(\\frac{8}{9}\\right)^6$ 倍，選 (C)。"]], "tr": "只看邊長變 $\\frac{1}{3}$ 而去算 $\\frac{2}{3}$ 的次方，其實要看面積比。"}, {"id": "111A-20", "y": 111, "p": "A", "no": 20, "ch": "A02", "img": "img/tc/111A_20.webp", "a": 3, "t": "內分點＋平行線方程式", "c": "先用內分點公式找 $D$，平行線斜率相同，再用點斜式。", "st": [["求 D 坐標", "$\\overline{AD}:\\overline{DB}=1:2$，$D=\\frac{2A+1B}{3}=\\left(\\frac{16+2}{3},\\frac{14+1}{3}\\right)=(6,5)$。"], ["求 AC 斜率", "$m_{AC}=\\frac{3-7}{12-8}=-1$。"], ["點斜式", "$y-5=-(x-6) \\Rightarrow x+y-11=0$，選 (D)。"]], "tr": "內分點的權重放反，寫成 $\\frac{A+2B}{3}=(4,3)$；靠近 $A$ 的點，$A$ 的權重要比較大。"}, {"id": "111A-21", "y": 111, "p": "A", "no": 21, "ch": "A09", "img": "img/tc/111A_21.webp", "a": 1, "t": "有上限的整數解個數", "c": "設三種案件數 $x,y,z$，先扣掉「至少一件」，再用重複組合算，最後扣掉超過上限的情形。", "st": [["列式", "$x+y+z=5$，$1\\le x\\le4$、$1\\le y\\le3$、$1\\le z\\le2$。<br>令 $x'=x-1$ 等，得 $x'+y'+z'=2$，且 $z'\\le1$。"], ["先不管上限", "非負整數解 $H^3_2=C^4_2=6$ 組。"], ["扣掉超出的", "只有 $z'=2$（即 $z=3$）超過上限，1 組。<br>$6-1=5$ 種，選 (B)。"]], "tr": "忘記三十萬的案子最多只能 2 件，算成 6 種。"}, {"id": "111A-22", "y": 111, "p": "A", "no": 22, "ch": "A05", "img": "img/tc/111A_22.webp", "a": 0, "t": "點到直線距離判斷收訊", "c": "把小路看成直線，算基地台到直線的距離，再看兩端點的距離，就知道哪一段在 9 公里內。", "st": [["建坐標", "以 $A$ 為原點，東為 $x$、北為 $y$：基地台 $(12,5)$，$B(12,16)$。<br>直線 $AB$：$y=\\frac{4}{3}x$，即 $4x-3y=0$。"], ["基地台到直線距離", "$d=\\frac{|48-15|}{5}=\\frac{33}{5}=6.6\\lt 9$，所以路上有點在範圍內。"], ["看兩端點", "基地台到 $A$：$\\sqrt{12^2+5^2}=13\\gt 9$；到 $B$：$11\\gt 9$。<br>兩端都收不到、中間有一段收得到，選 (A)。"]], "tr": "只算了兩端點都超過 9 公里就以為全程沒訊號，忘了中間會更靠近基地台。"}, {"id": "111A-23", "y": 111, "p": "A", "no": 23, "ch": "A10", "img": "img/tc/111A_23.webp", "a": 0, "t": "最小號碼為 9 的機率", "c": "最小是 9 號，代表 9 號一定要抽到，另外兩顆都要比 9 大。", "st": [["樣本空間", "6 顆取 3 顆：$C^6_3=20$ 種。"], ["有利情形", "9 號必選，另外 2 顆從 $10,11,12$ 中選：$C^3_2=3$ 種。"], ["機率", "$\\frac{3}{20}$，選 (A)。"]], "tr": "忘了「最小」的意思，讓 7、8 號也可以被抽到。"}, {"id": "111A-24", "y": 111, "p": "A", "no": 24, "ch": "A03", "img": "img/tc/111A_24.webp", "a": 3, "t": "根與係數：求新方程式", "c": "新方程式 $x^2-(\\text{兩根和})x+(\\text{兩根積})=0$，用 $\\alpha+\\beta$、$\\alpha\\beta$ 把新兩根的和、積算出來。", "st": [["原方程式", "$\\alpha+\\beta=-1$，$\\alpha\\beta=-1$。"], ["化簡新根", "$\\frac{\\beta}{\\alpha}+1=\\frac{\\alpha+\\beta}{\\alpha}$，$\\frac{\\alpha}{\\beta}+1=\\frac{\\alpha+\\beta}{\\beta}$。"], ["新兩根和與積", "積：$\\frac{(\\alpha+\\beta)^2}{\\alpha\\beta}=\\frac{1}{-1}=-1$。<br>和：$(\\alpha+\\beta)\\cdot\\frac{\\alpha+\\beta}{\\alpha\\beta}=\\frac{1}{-1}=-1$。"], ["寫出方程式", "$x^2-(-1)x+(-1)=0$，即 $x^2+x-1=0$，選 (D)。"]], "tr": "新方程式的一次項係數是「負的兩根和」，正負號別弄反。"}, {"id": "111A-25", "y": 111, "p": "A", "no": 25, "ch": "A07", "img": "img/tc/111A_25.webp", "a": 1, "t": "線性規劃：目標函數最大值", "c": "找可行解區域的頂點代入；也可以把目標函數拆成兩個限制式的組合直接估上界。", "st": [["找頂點", "$x+y=1$ 與 $3x+y=3$ 相減：$2x=2$，交點 $(1,0)$。"], ["拆成限制式組合", "$2x+y=\\frac{1}{2}(x+y)+\\frac{1}{2}(3x+y)\\le\\frac{1}{2}+\\frac{3}{2}=2$。"], ["確認可達到", "在 $(1,0)$ 時 $2x+y=2$，所以最大值是 $2$，選 (B)。"]], "tr": "只代 $(0,1)$ 或 $(1,0)$ 以外的截距點（如 $(0,3)$），沒先確認點在可行區域內。"}, {"id": "111B-1", "y": 111, "p": "B", "no": 1, "ch": "B05", "img": "img/tc/111B_1.webp", "a": 0, "t": "單位向量：長度為 1", "c": "單位向量就是長度為 $1$ 的向量，算 $\\sqrt{x^2+y^2}$ 看是不是 $1$。", "st": [["逐一算長度", "(A) $\\sqrt{\\frac{1}{9}+\\frac{4}{9}}=\\frac{\\sqrt5}{3}\\ne1$<br>(B) $\\sqrt{1+0}=1$<br>(C) $\\sqrt{\\frac{9}{25}+\\frac{16}{25}}=1$<br>(D) $\\sqrt{\\cos^2 30^{\\circ}+\\sin^2 30^{\\circ}}=1$"], ["結論", "不是單位向量的是 (A)，選 (A)。"]], "tr": "$(\\cos\\theta,\\sin\\theta)$ 一定是單位向量，不用代數字算。"}, {"id": "111B-2", "y": 111, "p": "B", "no": 2, "ch": "B07", "img": "img/tc/111B_2.webp", "a": 1, "t": "奇數項也成等差數列", "c": "等差數列每隔一項取一項，仍是等差數列，公差變成原來的 2 倍。", "st": [["整理新數列", "$a_1,a_3,\\dots,a_{21}$：首項 $-1$，公差 $6$，共 $\\frac{21-1}{2}+1=11$ 項。"], ["求末項", "$a_{21}=-1+20\\times3=59$。"], ["求和", "$S=\\frac{11\\times(-1+59)}{2}=11\\times29=319$，選 (B)。"]], "tr": "項數算成 21 或 10，奇數項從 1 到 21 共 11 項。"}, {"id": "111B-3", "y": 111, "p": "B", "no": 3, "ch": "B01", "img": "img/tc/111B_3.webp", "a": 1, "t": "絕對值不等式反推係數", "c": "$|7x-a|\\lt 28$ 拆成 $-28\\lt 7x-a\\lt 28$，再和 $b\\lt x\\lt 5$ 對照端點。", "st": [["解不等式", "$a-28\\lt 7x\\lt a+28 \\Rightarrow \\frac{a-28}{7}\\lt x\\lt \\frac{a+28}{7}$。"], ["對照端點", "$\\frac{a+28}{7}=5 \\Rightarrow a=7$；$b=\\frac{7-28}{7}=-3$。"], ["判斷象限", "$(b,a)=(-3,7)$，$x$ 負、$y$ 正，在第二象限，選 (B)。"]], "tr": "題目問的是 $(b,a)$ 不是 $(a,b)$，順序看錯會選成第四象限。"}, {"id": "111B-4", "y": 111, "p": "B", "no": 4, "ch": "B02", "img": "img/tc/111B_4.webp", "a": 2, "t": "平行線斜率相等", "c": "兩直線平行 $\\Leftrightarrow$ 斜率相等。", "st": [["求 AB 斜率", "$m_{AB}=\\frac{10-(-a)}{1-3}=-\\frac{10+a}{2}$。"], ["令斜率相等", "$-\\frac{10+a}{2}=2a \\Rightarrow -10-a=4a \\Rightarrow a=-2$，選 (C)。"]], "tr": "$A$ 的 $y$ 坐標是 $-a$，相減時變成 $10+a$，正負號要小心。"}, {"id": "111B-5", "y": 111, "p": "B", "no": 5, "ch": "B02", "img": "img/tc/111B_5.webp", "a": 3, "t": "垂直求係數＋點到直線距離", "c": "兩直線垂直，斜率相乘 $=-1$；求出直線後再套點到直線距離公式。", "st": [["由垂直求 a", "$L_2$ 斜率 $\\frac{2}{8}=\\frac{1}{4}$，$L_1$ 斜率 $-\\frac{a}{2}$。<br>$-\\frac{a}{2}\\times\\frac{1}{4}=-1 \\Rightarrow a=8$。"], ["化簡 L1", "$8x+2y+12=0 \\Rightarrow 4x+y+6=0$。"], ["算距離", "$d=\\frac{|4(1)+(-9)+6|}{\\sqrt{16+1}}=\\frac{1}{\\sqrt{17}}=\\frac{\\sqrt{17}}{17}$，選 (D)。"]], "tr": ""}, {"id": "111B-6", "y": 111, "p": "B", "no": 6, "ch": "B03", "img": "img/tc/111B_6.webp", "a": 3, "t": "由根寫二次式，再用餘式定理", "c": "$f(1)=f(-2)=0$ 表示 $f(x)=k(x-1)(x+2)$；除以 $x+3$ 的餘式就是 $f(-3)$。", "st": [["設式子", "$f(x)=k(x-1)(x+2)$。"], ["用 f(2)=8 求 k", "$k(1)(4)=8 \\Rightarrow k=2$。"], ["餘式定理", "$f(-3)=2(-4)(-1)=8$，選 (D)。"]], "tr": "除以 $x+3$ 要代 $x=-3$，不是代 $3$。"}, {"id": "111B-7", "y": 111, "p": "B", "no": 7, "ch": "B06", "img": "img/tc/111B_7.webp", "a": 1, "t": "圓心在 x 軸上→求半徑", "c": "$x^2+y^2+Dx+Ey+F=0$ 的圓心是 $(-\\frac{D}{2},-\\frac{E}{2})$；圓心在 $x$ 軸上，$y$ 坐標就是 $0$。", "st": [["找圓心", "圓心 $(3,-a)$，在 $x$ 軸上 $\\Rightarrow a=0$。"], ["配方求半徑", "$x^2-6x+y^2=7 \\Rightarrow (x-3)^2+y^2=16$，$r=4$。"], ["面積", "$\\pi r^2=16\\pi$，選 (B)。"]], "tr": "配方後忘記把 $9$ 加到右邊，算成 $r^2=7$。"}, {"id": "111B-8", "y": 111, "p": "B", "no": 8, "ch": "B02", "img": "img/tc/111B_8.webp", "a": 0, "t": "直角在 A：兩斜率相乘 -1", "c": "$\\overline{BC}$ 是斜邊，直角就在 $A$，所以 $\\overline{AB}\\perp\\overline{AC}$。", "st": [["寫斜率", "$m_{AB}=\\frac{7-2}{4-1}=\\frac{5}{3}$，$m_{AC}=\\frac{5-2}{a-1}=\\frac{3}{a-1}$。"], ["垂直", "$\\frac{5}{3}\\cdot\\frac{3}{a-1}=-1 \\Rightarrow a-1=-5 \\Rightarrow a=-4$，選 (A)。"]], "tr": "把直角放在 $B$ 或 $C$；斜邊對面的頂點才是直角。"}, {"id": "111B-9", "y": 111, "p": "B", "no": 9, "ch": "B04", "img": "img/tc/111B_9.webp", "a": 3, "t": "由終邊判斷三角函數正負", "c": "先看 $P$ 在哪一象限，決定 $\\sin$、$\\cos$、$\\tan$ 的正負，再判斷 $Q$ 兩個坐標的正負。", "st": [["P 的象限", "$P(-99,87)$ 在第二象限：$\\sin\\theta\\gt 0$、$\\cos\\theta\\lt 0$、$\\tan\\theta\\lt 0$。"], ["Q 的 x 坐標", "$5\\sin\\theta-6\\cos\\theta=$ 正 $-$ 負 $\\gt 0$。"], ["Q 的 y 坐標", "$7\\cos\\theta+8\\tan\\theta=$ 負 $+$ 負 $\\lt 0$。<br>$x\\gt 0$、$y\\lt 0$，在第四象限，選 (D)。"]], "tr": "不用真的把 $\\sin\\theta$、$\\cos\\theta$ 算出來，只要正負號就夠了。"}, {"id": "111B-10", "y": 111, "p": "B", "no": 10, "ch": "B10", "img": "img/tc/111B_10.webp", "a": 3, "t": "對數性質化簡", "c": "$\\log_3$ 的乘除可以拆成加減，根號、次方變成係數。", "st": [["拆開", "$f\\left(\\frac{\\sqrt[3]{a}\\,b^2}{c}\\right)=\\frac{1}{3}\\log_3a+2\\log_3b-\\log_3c$。"], ["代入", "$\\frac{1}{3}\\times6+2\\times2-5=2+4-5=1$，選 (D)。"]], "tr": "立方根是 $\\frac{1}{3}$ 次方，別寫成乘 3。"}, {"id": "111B-11", "y": 111, "p": "B", "no": 11, "ch": "B01", "img": "img/tc/111B_11.webp", "a": 1, "t": "二次函數頂點求最小值", "c": "$y=x^2+ax+c$ 的頂點 $x$ 坐標是 $-\\frac{a}{2}$；開口向上，最小值就是頂點的 $y$ 值。", "st": [["由頂點求 a", "$-\\frac{a}{2}=3 \\Rightarrow a=-6$。"], ["求最小值", "$f(3)=9-18+4=-5$，選 (B)。"]], "tr": "頂點公式是 $-\\frac{a}{2}$，漏掉負號會得 $a=6$。"}, {"id": "111B-12", "y": 111, "p": "B", "no": 12, "ch": "B08", "img": "img/tc/111B_12.webp", "a": 2, "t": "一次方程式無解的條件", "c": "整理成 $Ax=B$：$A=0$ 且 $B\\ne0$ 時無解；$A=0$ 且 $B=0$ 是無限多解。", "st": [["移項整理", "$(2k^2+k-1)x=1-k^2$。"], ["令係數為 0", "$2k^2+k-1=(2k-1)(k+1)=0 \\Rightarrow k=\\frac{1}{2}$ 或 $k=-1$。"], ["排除無限多解", "$k=-1$ 時右邊 $1-1=0$，是無限多解，不合。所以 $k=\\frac{1}{2}$。"], ["代入", "$4\\cdot\\frac{1}{8}+\\frac{1}{2}+1=2$，選 (C)。"]], "tr": "忘了檢查右邊，把 $k=-1$ 也算進去，會得到 $-4$（選項 (A)）。"}, {"id": "111B-13", "y": 111, "p": "B", "no": 13, "ch": "B11", "img": "img/tc/111B_13.webp", "a": 0, "t": "面積求夾角，再用餘弦定理", "c": "三角形面積 $=\\frac{1}{2}bc\\sin A$，由面積求出 $\\sin A$，再用餘弦定理求第三邊。", "st": [["求 sinA", "$\\frac{1}{2}\\cdot2\\cdot2\\sqrt3\\sin A=3 \\Rightarrow \\sin A=\\frac{\\sqrt3}{2}$，$A=60^{\\circ}$ 或 $120^{\\circ}$。"], ["餘弦定理", "$\\overline{BC}^2=4+12-2\\cdot2\\cdot2\\sqrt3\\cos A=16-8\\sqrt3\\cos A$。"], ["代兩種角", "$A=60^{\\circ}$：$16-4\\sqrt3$；$A=120^{\\circ}$：$16+4\\sqrt3$。<br>選項中只有 $\\sqrt{16-4\\sqrt3}$，選 (A)。"]], "tr": "$\\sin A=\\frac{\\sqrt3}{2}$ 有兩個角，只想到 $60^{\\circ}$ 就可能漏掉另一個答案。"}, {"id": "111B-14", "y": 111, "p": "B", "no": 14, "ch": "B04", "img": "img/tc/111B_14.webp", "a": 2, "t": "由圖形讀 a、b、c", "c": "$y=a\\sin(bx)+c$：振幅 $a=\\frac{\\text{最大}-\\text{最小}}{2}$，中線 $c=\\frac{\\text{最大}+\\text{最小}}{2}$，週期 $\\frac{2\\pi}{b}$。", "st": [["振幅與中線", "最大 $5$、最小 $1$：$a=2$，$c=3$。"], ["週期", "從 $A(0,3)$ 到 $D(4\\pi,3)$ 剛好一個完整週期，$\\frac{2\\pi}{b}=4\\pi \\Rightarrow b=\\frac{1}{2}$。"], ["計算", "$a+2b+c=2+1+3=6$，選 (C)。"]], "tr": "把週期看成 $B$ 到 $C$ 的距離 $2\\pi$；最高到最低只有半個週期。"}, {"id": "111B-15", "y": 111, "p": "B", "no": 15, "ch": "B03", "img": "img/tc/111B_15.webp", "a": 0, "t": "多項式長除法", "c": "先用除法原理還原 $f(x)$，再除以 $x^2+3$ 找商和餘式。", "st": [["還原 f(x)", "$f(x)=(2x+3)(x^3-x)+6=2x^4+3x^3-2x^2-3x+6$。"], ["長除法", "除以 $x^2+3$：商 $q(x)=2x^2+3x-8$，餘式 $r(x)=-12x+30$。<br>（驗算：$(x^2+3)(2x^2+3x-8)-12x+30$ 展開回到 $f(x)$）"], ["相減", "$q(x)-r(x)=2x^2+3x-8+12x-30=2x^2+15x-38$，選 (A)。"]], "tr": "減掉餘式時忘了變號，$-(-12x+30)=+12x-30$。"}, {"id": "111B-16", "y": 111, "p": "B", "no": 16, "ch": "B09", "img": "img/tc/111B_16.webp", "a": 2, "t": "兩條件同時成立", "c": "「且」代表兩個條件都要成立：同意票 $\\gt $ 不同意票，同意票 $\\ge\\frac{10000}{4}=2500$。", "st": [["門檻", "同意票至少 $2500$ 票，而且要比不同意票多。"], ["逐一檢查", "(A) 1500 不到 2500 ✗<br>(B) 2800 &lt; 3000 ✗<br>(C) 3000 ≥ 2500，且 3000 &gt; 2800 ✓<br>(D) 3000 &lt; 3500 ✗"], ["結論", "選 (C)。"]], "tr": "只看其中一個條件，(A) 同意比不同意多，但票數不到四分之一。"}, {"id": "111B-17", "y": 111, "p": "B", "no": 17, "ch": "B13", "img": "img/tc/111B_17.webp", "a": 3, "t": "平均數、全距、標準差", "c": "母體標準差 $\\sigma=\\sqrt{\\frac{\\sum(x_i-\\mu)^2}{n}}$，先求平均再算離差平方和。", "st": [["期中考", "總和 $560$，平均 $80$，(A) 錯。<br>離差 $4,2,1,0,-2,-6,1$，平方和 $62$，$\\sigma=\\sqrt{\\frac{62}{7}}\\approx2.98\\lt 5$，(C) 錯。"], ["期末考", "最高 $88$、最低 $77$，全距 $11$，(B) 錯。<br>總和 $581$，平均 $83$，離差 $5,1,2,-1,-1,-6,0$，平方和 $68$，$\\sigma=\\sqrt{\\frac{68}{7}}\\approx3.12\\lt 6$。"], ["結論", "(D) 正確，選 (D)。"]], "tr": "其實只要看 $\\sigma^2$ 有沒有小於 $36$，不用開根號：$\\frac{68}{7}\\lt 36$ 一看就知道。"}, {"id": "111B-18", "y": 111, "p": "B", "no": 18, "ch": "B10", "img": "img/tc/111B_18.webp", "a": 0, "t": "指數成長與衰退的式子", "c": "每天增加 $1\\%$ 是乘 $1.01$，一年乘 $365$ 次；減少 $1\\%$ 是乘 $0.99$。", "st": [["增加三十六倍", "「增加 36 倍」表示變成原來的 $37$ 倍以上：$1.01^{365}\\ge37$（實際約 $37.8$）。"], ["流失九成七", "流失 $97\\%$ 表示只剩 $3\\%$ 以下：$0.99^{365}\\le0.03$（實際約 $0.026$）。"], ["結論", "選 (A)。"]], "tr": "底數和指數放反寫成 $365^{1.01}$；成長是「底數是倍率、指數是次數」。"}, {"id": "111B-19", "y": 111, "p": "B", "no": 19, "ch": "B09", "img": "img/tc/111B_19.webp", "a": 3, "t": "代入檢查兩個限制", "c": "熱量和糖量兩個限制都要滿足，把每個組合代進去算。", "st": [["列限制式", "熱量 $100x+150y\\le400$，糖 $8x+6y\\le20$。"], ["逐一檢查", "(A) 熱量 300、糖 24 ✗<br>(B) 熱量 350、糖 22 ✗<br>(C) 熱量 450 ✗<br>(D) 熱量 400、糖 20 ✓"], ["結論", "選 (D)。"]], "tr": "「不能超過」包含等於，(D) 剛好等於上限是可以的。"}, {"id": "111B-20", "y": 111, "p": "B", "no": 20, "ch": "B11", "img": "img/tc/111B_20.webp", "a": 2, "t": "兩針夾角 60° 用餘弦定理", "c": "知道兩邊和夾角，求第三邊就用餘弦定理。", "st": [["求夾角", "2 點整，時針指 2、分針指 12，相差 2 格，每格 $30^{\\circ}$，夾角 $60^{\\circ}$。"], ["餘弦定理", "$\\overline{HM}^2=8^2+5^2-2\\cdot8\\cdot5\\cos60^{\\circ}=64+25-40=49$。"], ["開根號", "$\\overline{HM}=7$ 公分，選 (C)。"]], "tr": ""}, {"id": "111B-21", "y": 111, "p": "B", "no": 21, "ch": "B09", "img": "img/tc/111B_21.webp", "a": 0, "t": "BMI 不等式求體重範圍", "c": "BMI 上限 24 換成體重上限：體重 $\\le24\\times1.7^2$；減 5 公斤剛好進入範圍，代表現在超過、減完不超過。", "st": [["健康體重上限", "$24\\times1.7^2=24\\times2.89=69.36$ 公斤。"], ["列不等式", "現在太重：$w\\gt 69.36$；減 5 公斤後符合：$w-5\\le69.36 \\Rightarrow w\\le74.36$。"], ["對選項", "$69.36\\lt w\\le74.36$，只有 $74$ 符合，選 (A)。"]], "tr": "身高要換成公尺 $1.7$，用 $170$ 代會差一萬倍。"}, {"id": "111B-22", "y": 111, "p": "B", "no": 22, "ch": "B12", "img": "img/tc/111B_22.webp", "a": 1, "t": "乘法原理：底色另選", "c": "先決定限制最多的底色，商標、文字只要避開底色即可，兩者可以同色。", "st": [["底色", "5 種選 1：5 種。"], ["商標與文字", "各自不能和底色同色：各 4 種。"], ["相乘", "$5\\times4\\times4=80$，選 (B)。"]], "tr": "以為三者都要不同色而算 $5\\times4\\times3=60$；題目沒限制商標和文字不同。"}, {"id": "111B-23", "y": 111, "p": "B", "no": 23, "ch": "B12", "img": "img/tc/111B_23.webp", "a": 2, "t": "列舉：乘積除以 8 餘 1", "c": "$p,q$ 只能是 $2\\sim7$，範圍小，直接列舉最安全。", "st": [["先排除偶數", "乘積除以 8 餘 1 一定是奇數，所以 $p,q$ 都要從 $3,5,7$ 選。"], ["列舉", "$3\\times3=9$ ✓、$5\\times5=25$ ✓、$7\\times7=49$ ✓<br>$3\\times5=15$（餘 7）、$3\\times7=21$（餘 5）、$5\\times7=35$（餘 3）都不行。"], ["結論", "共 $(3,3),(5,5),(7,7)$ 三組，選 (C)。"]], "tr": "漏掉 $p=q$ 的情形；題目沒說兩數要不同。"}, {"id": "111B-24", "y": 111, "p": "B", "no": 24, "ch": "B09", "img": "img/tc/111B_24.webp", "a": 1, "t": "線性規劃：運費最小", "c": "設一個變數表示一地的分配，其他量全部用它表示，列出限制式後找頂點。", "st": [["設變數", "桃園送台北 $x$ 個、台南 $y$ 個；雲林送台北 $30-x$、台南 $20-y$。<br>限制：$x+y\\le20$、$(30-x)+(20-y)\\le40 \\Rightarrow x+y\\ge10$，$0\\le x\\le20$、$0\\le y\\le20$。"], ["運費式", "$200x+400y+600(30-x)+300(20-y)=24000-400x+100y$。"], ["找最小", "$x$ 越大、$y$ 越小越便宜：取 $x=20$、$y=0$，運費 $24000-8000=16000$ 元，選 (B)。"]], "tr": "雲林只有 40 個，所以桃園至少要出 10 個（$x+y\\ge10$），這個限制容易漏。"}, {"id": "111B-25", "y": 111, "p": "B", "no": 25, "ch": "B13", "img": "img/tc/111B_25.webp", "a": 1, "t": "相對次數：失敗比例 0.8～0.9", "c": "把「不成功次數 ÷ 總次數」算出來，看哪個落在 $0.8$ 到 $0.9$ 之間。", "st": [["算失敗比例", "(A) $\\frac{10}{10}=1$<br>(B) $\\frac{17}{20}=0.85$<br>(C) $\\frac{47}{60}\\approx0.78$<br>(D) $\\frac{20}{100}=0.2$"], ["結論", "只有 (B) 介於 $0.8$ 到 $0.9$，選 (B)。"]], "tr": "(D) 抽中 80 張是「成功」80%，不成功只有 20%。"}, {"id": "111C-1", "y": 111, "p": "C", "no": 1, "ch": "C09", "img": "img/tc/111C_1.webp", "a": 1, "t": "對數與指數互換", "c": "$\\log_a b=x \\Leftrightarrow a^x=b$：底數當底，對數值當指數。", "st": [["改寫", "$x=\\log_3 7 \\Leftrightarrow 3^x=7$。"], ["結論", "選 (B)。"]], "tr": "把底數和真數位置放反寫成 $7^x=3$。"}, {"id": "111C-2", "y": 111, "p": "C", "no": 2, "ch": "C06", "img": "img/tc/111C_2.webp", "a": 1, "t": "等比級數和大於 2022", "c": "等比級數和 $S_n=\\frac{a_1(r^n-1)}{r-1}$，代入後找最小的 $n$。", "st": [["寫出 Sn", "$S_n=\\frac{2(3^n-1)}{3-1}=3^n-1$。"], ["解不等式", "$3^n-1\\gt 2022 \\Rightarrow 3^n\\gt 2023$。<br>$3^6=729$、$3^7=2187$，最小 $n=7$，選 (B)。"]], "tr": "把級數和和第 $n$ 項 $a_n=2\\cdot3^{n-1}$ 搞混。"}, {"id": "111C-3", "y": 111, "p": "C", "no": 3, "ch": "C01", "img": "img/tc/111C_3.webp", "a": 1, "t": "區間寫成絕對值不等式", "c": "$|x-a|\\le b$ 表示 $a-b\\le x\\le a+b$：$a$ 是區間中點，$b$ 是半徑（半長）。", "st": [["找中點與半長", "$a=\\frac{3.1+4.9}{2}=4$，$b=\\frac{4.9-3.1}{2}=0.9$。"], ["相乘", "$ab=4\\times0.9=3.6$，選 (B)。"]], "tr": "$b$ 是區間長度的一半，不是整段長 $1.8$。"}, {"id": "111C-4", "y": 111, "p": "C", "no": 4, "ch": "C02", "img": "img/tc/111C_4.webp", "a": 2, "t": "三角函數的週期", "c": "$y=a\\sin bx$、$a\\cos bx$ 週期是 $\\frac{2\\pi}{|b|}$；加絕對值後負的部分翻上來，週期減半。", "st": [["逐一檢查", "(A) $\\sin2x$ 週期 $\\pi$，加絕對值後變 $\\frac{\\pi}{2}$，對。<br>(B)(D) 振幅不影響週期，都是 $2\\pi$，對。<br>(C) $\\cos2x$ 週期 $\\frac{2\\pi}{2}=\\pi$，不是 $\\frac{\\pi}{2}$，錯。"], ["結論", "錯誤的是 (C)，選 (C)。"]], "tr": "前面的係數 3、4 是振幅，不會改變週期。"}, {"id": "111C-5", "y": 111, "p": "C", "no": 5, "ch": "C04", "img": "img/tc/111C_5.webp", "a": 0, "t": "部分分式：代根求係數", "c": "兩邊同乘分母後，分別代 $x=2,-2,-3$，其他項會變 0，一次求出一個係數。", "st": [["同乘分母", "$x^2+2x+7=A(x+2)(x+3)+B(x-2)(x+3)+C(x-2)(x+2)$。"], ["代根", "$x=2$：$15=20A \\Rightarrow A=\\frac{3}{4}$<br>$x=-2$：$7=-4B \\Rightarrow B=-\\frac{7}{4}$<br>$x=-3$：$10=5C \\Rightarrow C=2$"], ["相加", "$A+B+C=\\frac{3}{4}-\\frac{7}{4}+2=1$，選 (A)。<br>（快速檢查：比較 $x^2$ 係數也得 $A+B+C=1$）"]], "tr": "其實比較兩邊 $x^2$ 的係數就直接得 $A+B+C=1$，不用三個都解。"}, {"id": "111C-6", "y": 111, "p": "C", "no": 6, "ch": "C12", "img": "img/tc/111C_6.webp", "a": 3, "t": "點在直線右側的判別", "c": "$ax+by+c\\gt 0$ 且 $a\\gt 0$ 時，是直線的右側；把 $A$ 代入看正負。", "st": [["判斷右側", "$L:2x-y+12$，$x$ 係數 $2\\gt 0$，所以右半平面是 $2x-y+12\\gt 0$。"], ["代入 A", "$2a-(-6)+12\\gt 0 \\Rightarrow 2a+18\\gt 0 \\Rightarrow a\\gt -9$。"], ["對選項", "只有 $-7\\gt -9$，選 (D)。"]], "tr": "$-(-6)$ 要變 $+6$，正負號別出錯。"}, {"id": "111C-7", "y": 111, "p": "C", "no": 7, "ch": "C05", "img": "img/tc/111C_7.webp", "a": 0, "t": "代值比求分點比例", "c": "直線兩側的點代入 $ax+by+c$，值的絕對值比 $=$ 兩點到直線的距離比 $=$ 分線段的比。", "st": [["代入直線", "$A$：$1-4+1=-2$；$B$：$6-2+1=5$。<br>一正一負，代表 $A$、$B$ 在兩側，線段確實和 $L$ 相交。"], ["求比例", "$\\overline{AP}:\\overline{BP}=|-2|:|5|=2:5$，$\\frac{\\overline{AP}}{\\overline{BP}}=\\frac{2}{5}$，選 (A)。"]], "tr": "比例方向弄反，寫成 $\\frac{5}{2}$。"}, {"id": "111C-8", "y": 111, "p": "C", "no": 8, "ch": "C04", "img": "img/tc/111C_8.webp", "a": 0, "t": "連鎖不等式拆兩個解交集", "c": "$5x-4\\lt x^2\\lt x+2$ 要拆成 $5x-4\\lt x^2$ 和 $x^2\\lt x+2$，兩個都要成立，取交集。", "st": [["左半", "$x^2-5x+4\\gt 0 \\Rightarrow (x-1)(x-4)\\gt 0 \\Rightarrow x\\lt 1$ 或 $x\\gt 4$。"], ["右半", "$x^2-x-2\\lt 0 \\Rightarrow (x-2)(x+1)\\lt 0 \\Rightarrow -1\\lt x\\lt 2$。"], ["交集", "$-1\\lt x\\lt 1$，選 (A)。"]], "tr": "二次不等式「$\\gt 0$ 取兩邊、$\\lt 0$ 取中間」，方向別記反。"}, {"id": "111C-9", "y": 111, "p": "C", "no": 9, "ch": "C05", "img": "img/tc/111C_9.webp", "a": 1, "t": "平行線到圓心等距", "c": "平行線可寫成 $x+y+k=0$，利用圓心到兩線距離相等找出 $k$。", "st": [["找圓心", "$x^2+y^2+2x+4y-3=0$，圓心 $(-1,-2)$。"], ["設 L2", "$L_2\\parallel L_1$，設 $L_2:x+y+k=0$。<br>距離相等：$\\frac{|-1-2+1|}{\\sqrt2}=\\frac{|-3+k|}{\\sqrt2} \\Rightarrow |k-3|=2$。"], ["取另一條", "$k=1$ 是 $L_1$ 本身，所以 $k=5$：$x+y+5=0$，乘 2 得 $2x+2y+10=0$。<br>$a+b=4$，選 (B)。"]], "tr": "常數項題目定成 $10$，要把 $x+y+5=0$ 乘 2 才能對上 $a,b$。"}, {"id": "111C-10", "y": 111, "p": "C", "no": 10, "ch": "C04", "img": "img/tc/111C_10.webp", "a": 1, "t": "除以重因式 (x+1)²的餘式", "c": "除以 $(x+1)^2$ 時，$f(-1)$ 等於餘式在 $-1$ 的值，而且導數也要相等：$f'(-1)$ 等於餘式的斜率。", "st": [["f(-1)", "$f(-1)=a-b+6-5+2=a-b+3$，餘式在 $-1$：$-3+4=1$。<br>$\\Rightarrow a-b=-2$。"], ["f'(-1)", "$f'(x)=4ax^3+3bx^2+12x+5$，$f'(-1)=-4a+3b-7=3$。<br>$\\Rightarrow -4a+3b=10$。"], ["解聯立", "$a=b-2$ 代入：$-4b+8+3b=10 \\Rightarrow b=-2$、$a=-4$。<br>$a+b=-6$，選 (B)。"]], "tr": "只用 $f(-1)$ 一個條件解不出兩個未知數，重因式要多用一個條件（導數或綜合除法兩次）。"}, {"id": "111C-11", "y": 111, "p": "C", "no": 11, "ch": "C11", "img": "img/tc/111C_11.webp", "a": 0, "t": "三元一次聯立方程式", "c": "把三個人的結果列成三條方程式，解出紅、黃、黑各值多少點。", "st": [["列式", "$3x+3y-4z=10$<br>$4x+3y-3z=21$<br>$2x+6y-2z=26 \\Rightarrow x+3y-z=13$"], ["消去 y", "第二式減第一式：$x+z=11$。<br>第二式減第三式（化簡後）：$3x-2z=8$。<br>解得 $x=6$、$z=5$，再代回得 $y=4$。"], ["算小蘭", "$3(6)+5(4)-2(5)=18+20-10=28$，選 (A)。"]], "tr": "黑球是扣分，要用減的。"}, {"id": "111C-12", "y": 111, "p": "C", "no": 12, "ch": "C08", "img": "img/tc/111C_12.webp", "a": 0, "t": "仰角：用塔高表示距離", "c": "設塔高 $h$，各點到塔底的距離都能寫成 $h$ 的倍數，相減就得 $a$、$b$。", "st": [["三個距離", "到塔底距離：$A$ 為 $\\sqrt3h$，$B$ 為 $h$，$C$ 為 $\\frac{h}{\\sqrt3}$。"], ["求 a、b", "$a=\\sqrt3h-h=(\\sqrt3-1)h$<br>$b=h-\\frac{h}{\\sqrt3}=\\frac{(\\sqrt3-1)h}{\\sqrt3}$"], ["相除", "$\\frac{a}{b}=\\sqrt3$，選 (A)。"]], "tr": "仰角 $30^{\\circ}$ 時距離是 $\\frac{h}{\\tan30^{\\circ}}=\\sqrt3h$，別寫成 $\\frac{h}{\\sqrt3}$。"}, {"id": "111C-13", "y": 111, "p": "C", "no": 13, "ch": "C10", "img": "img/tc/111C_13.webp", "a": 2, "t": "正四面體的高", "c": "邊長 $a$ 的正四面體，頂點正好在底面重心正上方，高 $=\\frac{\\sqrt6}{3}a$。", "st": [["底面重心", "底面正三角形 $ABC$ 邊長 $2$，重心 $G=\\left(1,\\frac{\\sqrt3}{3},0\\right)$，$\\overline{AG}=\\frac{2\\sqrt3}{3}$。"], ["畢氏定理", "$z^2=\\overline{AD}^2-\\overline{AG}^2=4-\\frac{4}{3}=\\frac{8}{3}$，$z=\\frac{2\\sqrt6}{3}$，選 (C)。"]], "tr": "把正三角形的高 $\\sqrt3$ 當成四面體的高。"}, {"id": "111C-14", "y": 111, "p": "C", "no": 14, "ch": "C10", "img": "img/tc/111C_14.webp", "a": 2, "t": "空間中兩點距離", "c": "空間兩點距離 $=\\sqrt{(\\Delta x)^2+(\\Delta y)^2+(\\Delta z)^2}$，深度就是 $z$ 方向的差。", "st": [["設坐標", "船在原點；黑盒子在直升機正下方：東 $140$、北 $80$、深 $x$。<br>直升機高 $100$ 只是干擾資訊，用不到。"], ["距離公式", "$140^2+80^2+x^2=180^2 \\Rightarrow 26000+x^2=32400 \\Rightarrow x^2=6400$。"], ["結論", "$x=80$ 公尺，選 (C)。"]], "tr": "把直升機高度 100 公尺也加進去計算。"}, {"id": "111C-15", "y": 111, "p": "C", "no": 15, "ch": "C07", "img": "img/tc/111C_15.webp", "a": 0, "t": "排列：扣掉三首慢歌相鄰", "c": "「最多 2 首慢歌連在一起」＝全部排法扣掉「3 首慢歌全連在一起」。", "st": [["全部排法", "6 首歌全排列：$6!=720$。"], ["三首慢歌相鄰", "把 3 首慢歌綁成一包，和 3 首快歌共 4 個單位排：$4!$；包內 3 首慢歌排：$3!$。<br>$4!\\times3!=144$。"], ["相減", "$720-144=576$，選 (A)。"]], "tr": "綁成一包後，包內自己的排法 $3!$ 別忘了乘。"}, {"id": "111C-16", "y": 111, "p": "C", "no": 16, "ch": "C03", "img": "img/tc/111C_16.webp", "a": 3, "t": "畢氏關係→兩向量垂直", "c": "$|\\vec a-\\vec b|^2=|\\vec a|^2+|\\vec b|^2-2\\vec a\\cdot\\vec b$，條件成立就代表 $\\vec a\\cdot\\vec b=0$。", "st": [["化成內積", "由題意 $\\vec a\\cdot\\vec b=0$。"], ["計算內積", "$3(2x+1)+(-3)(x-2)=6x+3-3x+6=3x+9=0$。"], ["結論", "$x=-3$，選 (D)。"]], "tr": "$(-3)(x-2)=-3x+6$，括號外的負號要乘進去。"}, {"id": "111C-17", "y": 111, "p": "C", "no": 17, "ch": "C11", "img": "img/tc/111C_17.webp", "a": 2, "t": "矩陣乘法比較元素", "c": "把 $AB$ 乘出來，和 $A+B$ 逐個位置比較，得到方程式。", "st": [["算 AB", "$AB=\\begin{bmatrix}2a-b \\& ac-d\\\\ 4+3b \\& 2c+3d\\end{bmatrix}$，$A+B=\\begin{bmatrix}a+2 \\& c-1\\\\ 2+b \\& 3+d\\end{bmatrix}$。"], ["逐格比較", "左下：$4+3b=2+b \\Rightarrow b=-1$<br>左上：$2a+1=a+2 \\Rightarrow a=1$<br>右上：$c-d=c-1 \\Rightarrow d=1$"], ["求 c", "右下：$2c+3=4 \\Rightarrow c=\\frac{1}{2}$，選 (C)。"]], "tr": "矩陣乘法是「列乘行」，不能對應位置直接相乘。"}, {"id": "111C-18", "y": 111, "p": "C", "no": 18, "ch": "C14", "img": "img/tc/111C_18.webp", "a": 3, "t": "導數＝切線斜率", "c": "切點 $(a,b)$ 的切線斜率就是 $f'(a)$。", "st": [["求導數", "$f'(x)=3x^2-\\frac{12}{x^2}$。"], ["令斜率為 9", "$3a^2-\\frac{12}{a^2}=9 \\Rightarrow a^4-3a^2-4=0 \\Rightarrow (a^2-4)(a^2+1)=0$，$a^2=4$。<br>$a\\gt 0$，所以 $a=2$。"], ["求 b", "$b=f(2)=8+6=14$，$a+b=16$，選 (D)。"]], "tr": "$\\frac{12}{x}=12x^{-1}$ 的導數是 $-\\frac{12}{x^2}$，負號別漏。"}, {"id": "111C-19", "y": 111, "p": "C", "no": 19, "ch": "C15", "img": "img/tc/111C_19.webp", "a": 3, "t": "拆項後用冪次積分", "c": "先把分式拆成 $x$ 的次方，再用 $\\int x^n\\,dx=\\frac{x^{n+1}}{n+1}+C$。", "st": [["拆項", "$\\frac{x+3}{2\\sqrt x}=\\frac{1}{2}x^{\\frac{1}{2}}+\\frac{3}{2}x^{-\\frac{1}{2}}$。"], ["逐項積分", "$\\frac{1}{2}\\cdot\\frac{2}{3}x^{\\frac{3}{2}}+\\frac{3}{2}\\cdot2x^{\\frac{1}{2}}=\\frac{1}{3}x^{\\frac{3}{2}}+3x^{\\frac{1}{2}}$。"], ["結論", "再加積分常數 $C$，選 (D)。"]], "tr": "分子分母各自積分再相除，像 (B)(C) 那樣，是錯的。"}, {"id": "111C-20", "y": 111, "p": "C", "no": 20, "ch": "C15", "img": "img/tc/111C_20.webp", "a": 2, "t": "速度積分得行駛距離", "c": "距離 $=\\int_0^3 v(t)\\,dt$，從 8:00 到 11:00 是 $t=0$ 到 $t=3$。", "st": [["列積分", "$\\int_0^3(-1.5t^2+6t+90)\\,dt=\\left[-0.5t^3+3t^2+90t\\right]_0^3$。"], ["計算", "$-13.5+27+270=283.5$ 公里。"], ["對照服務區", "最接近新營服務區（284 公里），選 (C)。"]], "tr": "直接用 $v(3)\\times3$ 算距離，速度會變，要用積分。"}, {"id": "111C-21", "y": 111, "p": "C", "no": 21, "ch": "C09", "img": "img/tc/111C_21.webp", "a": 1, "t": "等比衰減：取對數求 r", "c": "每年乘 $r$，六年後變 $r^6$ 倍，令 $r^6=0.5$，兩邊取對數再用參考數值。", "st": [["列式", "$r^6=0.5 \\Rightarrow 6\\log r=\\log0.5\\approx-0.301$。"], ["求 log r", "$\\log r\\approx-0.0502\\approx0.950-1=\\log8.91-1=\\log0.891$。"], ["結論", "$r\\approx0.891$，落在 $0.88\\lt r\\lt 0.91$，選 (B)。"]], "tr": "以為每年減 $\\frac{50\\%}{6}\\approx8.3\\%$ 得 $r\\approx0.917$；等比是乘法，不能平均分。"}, {"id": "111C-22", "y": 111, "p": "C", "no": 22, "ch": "C08", "img": "img/tc/111C_22.webp", "a": 2, "t": "餘弦定理＋正弦定理求外接圓", "c": "$\\frac{a}{\\sin A}=2R$，先用餘弦定理求一個角的 $\\cos$，再換成 $\\sin$。", "st": [["求 cos", "取最長邊 $6$ 對應的角：$\\cos C=\\frac{16+25-36}{2\\cdot4\\cdot5}=\\frac{1}{8}$。"], ["求 sin", "$\\sin C=\\sqrt{1-\\frac{1}{64}}=\\frac{3\\sqrt7}{8}$。"], ["正弦定理", "$2R=\\frac{6}{\\frac{3\\sqrt7}{8}}=\\frac{16}{\\sqrt7}$，選 (C)。"]], "tr": "題目問的是<b>直徑</b> $2R$，不是半徑 $R=\\frac{8}{\\sqrt7}$（選項 (A)）。"}, {"id": "111C-23", "y": 111, "p": "C", "no": 23, "ch": "C08", "img": "img/tc/111C_23.webp", "a": 3, "t": "鈍角三角形餘弦定理", "c": "由面積求 $\\sin A$，鈍角就取 $135^{\\circ}$，再用餘弦定理。", "st": [["求角", "$\\frac{1}{2}\\cdot3\\cdot2\\sin A=\\frac{3\\sqrt2}{2} \\Rightarrow \\sin A=\\frac{\\sqrt2}{2}$，鈍角 $A=135^{\\circ}$。"], ["餘弦定理", "$a^2=9+4-2\\cdot3\\cdot2\\cos135^{\\circ}=13+6\\sqrt2$，選 (D)。"]], "tr": "$\\cos135^{\\circ}=-\\frac{\\sqrt2}{2}$ 是負的，減負變加，所以是 $13+6\\sqrt2$。"}, {"id": "111C-24", "y": 111, "p": "C", "no": 24, "ch": "C13", "img": "img/tc/111C_24.webp", "a": 3, "t": "橢圓參數式求最大值", "c": "配方成標準式後用參數式，把 $x+3y$ 變成 $a\\cos\\theta+b\\sin\\theta$，最大值是 $\\sqrt{a^2+b^2}$。", "st": [["配方", "$4x^2+6(y-1)^2=12 \\Rightarrow \\frac{x^2}{3}+\\frac{(y-1)^2}{2}=1$。"], ["參數式", "$x=\\sqrt3\\cos\\theta$，$y=1+\\sqrt2\\sin\\theta$。<br>$x+3y=3+\\sqrt3\\cos\\theta+3\\sqrt2\\sin\\theta$。"], ["求最大值", "$\\sqrt3\\cos\\theta+3\\sqrt2\\sin\\theta$ 最大 $\\sqrt{3+18}=\\sqrt{21}$，所以最大值 $3+\\sqrt{21}$，選 (D)。"]], "tr": "配方時 $6y^2-12y=6(y-1)^2-6$，右邊要補 $+6$ 變成 $12$。"}, {"id": "111C-25", "y": 111, "p": "C", "no": 25, "ch": "C14", "img": "img/tc/111C_25.webp", "a": 2, "t": "分段函數連續求參數", "c": "$x=3$ 連續要「右極限＝函數值」；右邊分母在 $x=3$ 是 0，分子也必須是 0 極限才存在。", "st": [["分子要為 0", "$x^2-2x-3=(x-3)(x+1)$，分母在 $x=3$ 為 0，所以 $2(3)+a=0 \\Rightarrow a=-6$。"], ["求右極限", "$\\lim_{x\\to3^+}\\frac{2(x-3)}{(x-3)(x+1)}=\\frac{2}{4}=\\frac{1}{2}$。"], ["等於函數值", "$f(3)=\\frac{3-5}{3-b}=\\frac{1}{2} \\Rightarrow 3-b=-4 \\Rightarrow b=7$。<br>$a+b=1$，選 (C)。"]], "tr": "沒想到「分母為 0 時分子也要為 0」，就找不出 $a$。"}, {"id": "112A-1", "y": 112, "p": "A", "no": 1, "ch": "A03", "img": "img/tc/112A_1.webp", "a": 3, "t": "除法原理：直接看出商式", "c": "$f(x)=$ 除式 $\\times$ 商式 $+$ 餘式，而且餘式次數要比除式低。", "st": [["對照除法原理", "$f(x)=(9x^2+1)(2x-3)+6$，剛好是「除式 $\\times$ 商式 $+$ 餘式」的樣子。"], ["檢查餘式", "餘式 $6$ 是常數，次數比 $9x^2+1$ 低，合格。所以商式是 $2x-3$，選 (D)。"]], "tr": "別把 $+6$ 當成商式的一部分；6 是餘式。"}, {"id": "112A-2", "y": 112, "p": "A", "no": 2, "ch": "A07", "img": "img/tc/112A_2.webp", "a": 0, "t": "BMI 不等式換算體重範圍", "c": "把「BMI 在 18.5 和 24 之間」寫成不等式，再乘上身高平方就得到體重範圍。", "st": [["列式", "身高 2 公尺，身高平方 $=4$：$18.5\\lt \\dfrac{x}{4}\\lt 24$。"], ["乘以 4", "$74\\lt x\\lt 96$，選 (A)。"]], "tr": "身高要先平方，是乘 4 不是乘 2。"}, {"id": "112A-3", "y": 112, "p": "A", "no": 3, "ch": "A07", "img": "img/tc/112A_3.webp", "a": 2, "t": "二元一次不等式圖解與象限", "c": "第二象限是 $x\\lt 0$、$y\\gt 0$，檢查哪個不等式在這裡完全找不到點。", "st": [["代第二象限的點", "第二象限任一點 $x\\lt 0$，所以 $2x-3\\lt -3$。"], ["看 (C)", "$y\\le 2x-3\\lt -3$ 代表 $y$ 一定是負的，和 $y\\gt 0$ 矛盾，所以 (C) 的區域完全不碰第二象限。"], ["其他選項", "(A)(B)(D) 都能找到例子，例如 $(-1,10)$ 符合 (A)(B)，$(-1,0.5)$ 符合 (D)。選 (C)。"]], "tr": "「$\\le$」是直線下方，別和「$\\ge$」的上方搞反。"}, {"id": "112A-4", "y": 112, "p": "A", "no": 4, "ch": "A09", "img": "img/tc/112A_4.webp", "a": 0, "t": "乘法原理：衣帽圍裙搭配", "c": "每一類都要選一個，分步驟完成就用乘法。", "st": [["各類選法", "帽子 3 種、衣服 2 種、圍裙 2 種。"], ["相乘", "$3\\times2\\times2=12$ 種，選 (A)。"]], "tr": "分步驟用乘法，不是加法 $3+2+2$。"}, {"id": "112A-5", "y": 112, "p": "A", "no": 5, "ch": "A02", "img": "img/tc/112A_5.webp", "a": 1, "t": "點到直線距離公式", "c": "先把直線化成 $ax+by+c=0$，再套距離公式 $\\dfrac{|ax_0+by_0+c|}{\\sqrt{a^2+b^2}}$。", "st": [["化簡直線", "兩邊乘 $\\sqrt2$：$L: x+y-\\sqrt2=0$。"], ["代公式", "$d=\\dfrac{|-1-1-\\sqrt2|}{\\sqrt{1^2+1^2}}=\\dfrac{2+\\sqrt2}{\\sqrt2}=\\sqrt2+1$。"], ["結論", "選 (B)。"]], "tr": "分子要加絕對值，$-2-\\sqrt2$ 取正變 $2+\\sqrt2$。"}, {"id": "112A-6", "y": 112, "p": "A", "no": 6, "ch": "A01", "img": "img/tc/112A_6.webp", "a": 2, "t": "數線上兩點距離", "c": "數線上兩點距離 $=|a-b|$。", "st": [["與 $-2$ 距離 3", "$|x+2|=3$，$x=1$ 或 $x=-5$。"], ["與 3 距離 2", "$|x-3|=2$，$x=5$ 或 $x=1$。"], ["共同解", "兩個都成立的是 $x=1$，選 (C)。"]], "tr": "只滿足其中一個條件的 $-5$、$5$ 都是陷阱選項。"}, {"id": "112A-7", "y": 112, "p": "A", "no": 7, "ch": "A04", "img": "img/tc/112A_7.webp", "a": 0, "t": "廣義角化銳角：sin 補角", "c": "$\\sin(180^{\\circ}-\\theta)=\\sin\\theta$，第二象限的正弦是正的。", "st": [["化成補角", "$137^{\\circ}=180^{\\circ}-43^{\\circ}$。"], ["套公式", "$\\sin137^{\\circ}=\\sin43^{\\circ}$，選 (A)。"]], "tr": "第二象限 sin 為正，不用加負號。"}, {"id": "112A-8", "y": 112, "p": "A", "no": 8, "ch": "A04", "img": "img/tc/112A_8.webp", "a": 3, "t": "由圖形判斷三角函數", "c": "看三件事：$x=0$ 的值、最大最小值（振幅）、週期。", "st": [["看 $x=0$", "圖形在 $x=0$ 時 $y=2$ 是最高點，是 cos 型（sin 型會過原點）。"], ["看振幅與週期", "最大 2、最小 $-2$，振幅 2；相鄰兩個最高點約在 $0$ 和 $6.28$，週期 $2\\pi$。"], ["結論", "$y=2\\cos x$，選 (D)。"]], "tr": "$\\cos2x$ 的週期只有 $\\pi$，而且最大值是 1。"}, {"id": "112A-9", "y": 112, "p": "A", "no": 9, "ch": "A06", "img": "img/tc/112A_9.webp", "a": 0, "t": "由前 n 項和求第 n 項", "c": "$a_n=S_n-S_{n-1}$（$n\\ge2$）。", "st": [["算 $S_9$、$S_8$", "$S_9=81+9-4=86$，$S_8=64+8-4=68$。"], ["相減", "$a_9=86-68=18$，選 (A)。"]], "tr": "別直接把 $n=9$ 代進 $S_n$，那是前 9 項的總和。"}, {"id": "112A-10", "y": 112, "p": "A", "no": 10, "ch": "A07", "img": "img/tc/112A_10.webp", "a": 3, "t": "定價問題列二次不等式", "c": "收入 $=$ 單價 $\\times$ 張數，不虧損就是收入 $\\ge$ 成本。", "st": [["算成本", "定價 50 元賣 200 張收入 $10000$，還虧 $5400$，成本 $=10000+5400=15400$ 元。"], ["寫出張數", "定價 $x$ 元比 50 元多 $(x-50)$ 元，張數 $=200-(x-50)=250-x$。"], ["不虧損", "$x(250-x)\\ge15400$，選 (D)。"]], "tr": "成本是 15400 不是 5400，虧損要加回去。"}, {"id": "112A-11", "y": 112, "p": "A", "no": 11, "ch": "A09", "img": "img/tc/112A_11.webp", "a": 0, "t": "組合：最多問題用扣掉法", "c": "「最多 2 人」＝全部選法扣掉「3 人都是醫師」。", "st": [["全部選法", "11 人選 3 人：$C^{11}_3=165$。"], ["扣掉 3 個都是醫師", "$C^5_3=10$。"], ["相減", "$165-10=155$，選 (A)。"]], "tr": "也可以分 0、1、2 位醫師相加，但扣掉法比較快。"}, {"id": "112A-12", "y": 112, "p": "A", "no": 12, "ch": "A01", "img": "img/tc/112A_12.webp", "a": 0, "t": "二次函數頂點與開口", "c": "$a\\lt 0$ 開口向下，頂點 $(1,2)$ 是最高點，圖上所有點的 $y\\le2$，且只有 $x=1$ 時 $y=2$。", "st": [["看頂點", "頂點 $(1,2)$，最大值 2，所以 (D) 的 $y=4$ 不可能；$x=1$ 時 $y$ 一定是 2，(B) 不可能。"], ["看 (C)", "$x=3\\neq1$ 時 $y\\lt 2$，不可能等於 2。"], ["驗證 (A)", "$f(0)=a+2=0$，得 $a=-2\\lt 0$，合理，選 (A)。"]], "tr": "開口向下時頂點是最高點，$y$ 值不會超過 2。"}, {"id": "112A-13", "y": 112, "p": "A", "no": 13, "ch": "A05", "img": "img/tc/112A_13.webp", "a": 1, "t": "圓與直線相切：距離等於半徑", "c": "直線與圓相切 $\\Leftrightarrow$ 圓心到直線距離 $=$ 半徑。", "st": [["整理", "$L: mx-y+(3-2m)=0$；圓心 $(2,8)$，半徑 $\\sqrt5$。"], ["距離", "$\\dfrac{|2m-8+3-2m|}{\\sqrt{m^2+1}}=\\dfrac{5}{\\sqrt{m^2+1}}=\\sqrt5$。"], ["解", "$\\sqrt{m^2+1}=\\sqrt5$，$m^2=4$，$|m|=2$，選 (B)。"]], "tr": "半徑是 $\\sqrt5$ 不是 5。"}, {"id": "112A-14", "y": 112, "p": "A", "no": 14, "ch": "A03", "img": "img/tc/112A_14.webp", "a": 3, "t": "聯立求兩個多項式", "c": "把 $f-g$ 和 $f+g$ 相加、相減，就能分別解出 $f$、$g$。", "st": [["解出 $f$", "$2f=2(x-1)+2x(x-1)=2(x-1)(x+1)$，$f(x)=x^2-1$。"], ["解出 $g$", "$g=f-2(x-1)=(x-1)^2$。"], ["代值", "$f(-1)=0$，$g(-1)=4$，$3\\cdot0+2\\cdot4=8$，選 (D)。"]], "tr": "其實也可以直接代 $x=-1$ 進兩式：$f-g=-4$、$f+g=4$，一樣得到 $f=0,g=4$。"}, {"id": "112A-15", "y": 112, "p": "A", "no": 15, "ch": "A03", "img": "img/tc/112A_15.webp", "a": 2, "t": "餘式定理", "c": "$f(x)$ 除以 $x-k$ 的餘式就是 $f(k)$。", "st": [["求 $a$", "$a=f(1)=1+9+26+24=60$。"], ["求 $b$", "$b=f(-1)=-1+9-26+24=6$。"], ["相減", "$a-b=54$，選 (C)。"]], "tr": "除以 $x+1$ 要代 $x=-1$，不是 $x=1$。"}, {"id": "112A-16", "y": 112, "p": "A", "no": 16, "ch": "A08", "img": "img/tc/112A_16.webp", "a": 3, "t": "指數函數的增減與對稱", "c": "$a\\gt 1$ 時 $a^x$ 遞增，$0\\lt a\\lt 1$ 時遞減；$a^{-x}=\\left(\\frac1a\\right)^x$。", "st": [["(A)(B)", "(A) $a\\gt 1$ 是遞增，錯。(B) $0\\lt a\\lt 1$ 時 $a^{-x}=(\\frac1a)^x$ 底數 $\\gt 1$，是遞增，錯。"], ["(C)", "指數函數的值永遠大於 0，錯。"], ["(D)", "把 $x$ 換成 $-x$ 就是對 $y$ 軸鏡射，所以 $a^x$ 與 $a^{-x}$ 對稱於 $y$ 軸，選 (D)。"]], "tr": "$a^{-x}$ 的增減要看 $\\frac1a$，和 $a^x$ 剛好相反。"}, {"id": "112A-17", "y": 112, "p": "A", "no": 17, "ch": "A08", "img": "img/tc/112A_17.webp", "a": 2, "t": "換底公式連乘", "c": "全部換成 $\\log$（同底），分子分母會互相消掉。", "st": [["換底", "$\\dfrac{2\\log7}{2\\log3}\\times\\dfrac{2\\log5}{3\\log2}\\times\\dfrac{2\\log2}{\\log7}\\times\\dfrac{\\log3}{\\log5}$。"], ["約分", "$\\log7,\\log5,\\log3,\\log2$ 全消掉，剩 $\\dfrac{2}{2}\\cdot\\dfrac{2}{3}\\cdot2\\cdot1=\\dfrac43$。"], ["結論", "選 (C)。"]], "tr": "$\\log_9 49=\\dfrac{2\\log7}{2\\log3}$，9 和 49 的次方都要記得拉下來。"}, {"id": "112A-18", "y": 112, "p": "A", "no": 18, "ch": "A10", "img": "img/tc/112A_18.webp", "a": 1, "t": "事件的交集", "c": "把每個事件的元素列出來，找三個都有的。", "st": [["列出事件", "$A=\\{4,5,6\\}$，$B=\\{1,2,4,5\\}$，$C=\\{2,4,6\\}$。"], ["取交集", "$A\\cap B=\\{4,5\\}$，再和 $C$ 交集得 $\\{4\\}$，選 (B)。"]], "tr": "$B$ 是「不是 3 的倍數」，要把 3 和 6 都去掉。"}, {"id": "112A-19", "y": 112, "p": "A", "no": 19, "ch": "A10", "img": "img/tc/112A_19.webp", "a": 2, "t": "期望值＝機率×得分再加總", "c": "期望值 $=\\sum$（機率 $\\times$ 得分）。", "st": [["列每一區", "第 $x$ 區機率 $\\dfrac{x}{10}$、得 $2x$ 分，相乘得 $\\dfrac{2x^2}{10}$。"], ["加總", "$\\dfrac{2(1+4+9+16)}{10}=\\dfrac{60}{10}=6$，選 (C)。"]], "tr": "機率總和 $\\frac{1+2+3+4}{10}=1$，可以順便檢查題目合理。"}, {"id": "112A-20", "y": 112, "p": "A", "no": 20, "ch": "A10", "img": "img/tc/112A_20.webp", "a": 2, "t": "全距看資料變化大小", "c": "「變化最小」看分散程度，這張表能用的是全距 $=$ 最大值 $-$ 最小值。", "st": [["算全距", "臺北 $15.6$、臺中 $12.0$、臺南 $9.9$、高雄 $11.1$。"], ["比較", "臺南最小，選 (C)。"]], "tr": "平均數、中位數是看「集中在哪」，不是看「變化大小」。"}, {"id": "112A-21", "y": 112, "p": "A", "no": 21, "ch": "A10", "img": "img/tc/112A_21.webp", "a": 1, "t": "分層隨機抽樣", "c": "母體分成性質差異大的幾層，每層各自隨機抽，就是分層隨機抽樣。", "st": [["看題目", "依工作屬性分成業務員、作業員兩層，同層意見相近、不同層差異大。"], ["判斷", "各層依比例（$500:1000=100:200$）隨機抽出，屬於分層隨機抽樣，選 (B)。"]], "tr": "部落（群集）抽樣是「層內差異大、層間差異小」，剛好相反。"}, {"id": "112A-22", "y": 112, "p": "A", "no": 22, "ch": "A05", "img": "img/tc/112A_22.webp", "a": 1, "t": "直徑兩端點求圓方程式", "c": "圓心是直徑中點，半徑是直徑長的一半。", "st": [["圓心", "中點 $\\left(\\frac{-2+4}{2},\\frac{-2+6}{2}\\right)=(1,2)$，$a=1,b=2$。"], ["半徑", "直徑 $=\\sqrt{6^2+8^2}=10$，半徑 5，$c^2=25$，$c=\\pm5$。"], ["代入", "$a+b+c=8$ 或 $-2$，選項中有 8，選 (B)。"]], "tr": "$c^2=25$ 時 $c$ 可正可負，所以題目說「可能」。"}, {"id": "112A-23", "y": 112, "p": "A", "no": 23, "ch": "A02", "img": "img/tc/112A_23.webp", "a": 0, "t": "點到平行線距離決定半徑範圍", "c": "圓只影響一個車道，表示圓要碰到 $L_1$（越過邊線）但不能越過中線 $M$。", "st": [["到 $L_1$ 的距離", "$\\dfrac{|6+4-20|}{5}=2$。"], ["到 $M$ 的距離", "$\\dfrac{|6+4-35|}{5}=5$。"], ["範圍", "$2\\lt r\\le5$，$a=2,b=5$，$a+b=7$，選 (A)。"]], "tr": "要算到中線 $M$，不是到另一條邊線 $L_2$。"}, {"id": "112A-24", "y": 112, "p": "A", "no": 24, "ch": "A06", "img": "img/tc/112A_24.webp", "a": 3, "t": "等差級數求項數", "c": "先用已知項找首項，再用等差級數和公式解 $n$。", "st": [["首項", "公差 3，$a_5=a_1+4\\cdot3=27$，$a_1=15$。"], ["列式", "$S_n=\\dfrac{n[2\\cdot15+3(n-1)]}{2}=330$，化簡 $3n^2+27n-660=0$。"], ["解方程", "$n^2+9n-220=0$，$(n+20)(n-11)=0$，$n=11$，選 (D)。"]], "tr": "項數一定是正整數，$n=-20$ 不合。"}, {"id": "112A-25", "y": 112, "p": "A", "no": 25, "ch": "A09", "img": "img/tc/112A_25.webp", "a": 1, "t": "相鄰不同科的排列計數", "c": "把星期日到星期六一天一天排，星期一、五先固定為數學，再看旁邊的限制。", "st": [["星期日、星期六", "都和數學相鄰，只能考英或國：各 2 種。"], ["星期二～四", "二、四不能考數學，三只要和二、四不同。星期二 2 種；若星期三考數學，星期四 2 種；若星期三考另一科，星期四只能和星期二同科 1 種：$2\\times(2+1)=6$ 種。"], ["相乘", "$2\\times6\\times2=24$ 種，選 (B)。"]], "tr": "星期三可以考數學，別漏掉這種情形。"}, {"id": "112B-1", "y": 112, "p": "B", "no": 1, "ch": "B05", "img": "img/tc/112B_1.webp", "a": 0, "t": "向量平行與垂直判斷", "c": "平行：分量成比例；垂直：內積為 0。", "st": [["逐一檢查", "(B) $(1,\\frac12)=\\frac12(2,1)$ 平行；(D) $(-1,-\\frac12)=-\\frac12(2,1)$ 平行；(C) 內積 $-1+1=0$ 垂直。"], ["看 (A)", "$(-1,\\frac12)$ 與 $(2,1)$：比例 $\\frac{-1}{2}\\neq\\frac{1/2}{1}$ 不平行，內積 $-2+\\frac12\\neq0$ 不垂直，選 (A)。"]], "tr": "方向相反（係數為負）也算平行。"}, {"id": "112B-2", "y": 112, "p": "B", "no": 2, "ch": "B03", "img": "img/tc/112B_2.webp", "a": 1, "t": "係數總和代 x=1", "c": "多項式所有係數總和 $=f(1)$。", "st": [["代 $x=1$", "$(2-3)^5+3(1-1)^2=(-1)^5+0=-1$。"], ["結論", "選 (B)。"]], "tr": "不用真的展開，代 1 最快。"}, {"id": "112B-3", "y": 112, "p": "B", "no": 3, "ch": "B08", "img": "img/tc/112B_3.webp", "a": 3, "t": "判別式判斷沒有實根", "c": "$ax^2+bx+c=0$ 沒有實根 $\\Leftrightarrow$ 判別式 $b^2-4ac\\lt 0$。", "st": [["判別式", "$k^2-12h\\lt 0$。"], ["代選項", "(A) $16-12\\gt 0$；(B) $144-144=0$；(C) $25-24\\gt 0$；(D) $100-108\\lt 0$。"], ["結論", "選 (D)。"]], "tr": "判別式 $=0$ 是有兩個相等實根，不是沒有實根。"}, {"id": "112B-4", "y": 112, "p": "B", "no": 4, "ch": "B02", "img": "img/tc/112B_4.webp", "a": 3, "t": "斜率正負與垂直", "c": "過一、三象限（且過原點方向往右上）斜率為正；兩直線垂直時 $m_1m_2=-1$。", "st": [["判斷正負", "$L_1$ 往右上，$m_1\\gt 0$；$m_1m_2=-1$，所以 $m_2\\lt 0$。"], ["象限", "$(m_1,m_2)=(+,-)$ 在第四象限，選 (D)。"]], "tr": "垂直的斜率一正一負，不是同號。"}, {"id": "112B-5", "y": 112, "p": "B", "no": 5, "ch": "B01", "img": "img/tc/112B_5.webp", "a": 0, "t": "中點求截距、寫一次函數", "c": "由中點公式找出 $a,b$，再用兩截距寫出直線。", "st": [["求 $a,b$", "$\\frac{a+0}{2}=-2$，$a=-4$；$\\frac{0+b}{2}=3$，$b=6$。"], ["寫函數", "過 $(-4,0)$、$(0,6)$，斜率 $\\frac{6}{4}=\\frac32$，$f(x)=\\frac32x+6$，$f(2)=9$。"], ["相加", "$a+b+f(2)=-4+6+9=11$，選 (A)。"]], "tr": "中點是兩點坐標「相加除以 2」，$a$ 要乘回 2 倍。"}, {"id": "112B-6", "y": 112, "p": "B", "no": 6, "ch": "B06", "img": "img/tc/112B_6.webp", "a": 3, "t": "x、y 對調的圓", "c": "把 $x$、$y$ 互換，圖形對 $y=x$ 鏡射，圓心坐標也互換，半徑不變。", "st": [["還原圓心", "看錯後圓心 $(1,2)$，原本圓心是 $(2,1)$，半徑 2。"], ["寫方程式", "$(x-2)^2+(y-1)^2=4$，展開 $x^2+y^2-4x-2y+1=0$，選 (D)。"]], "tr": "直徑 4 半徑才是 2；(B) 是把半徑當成 4 的陷阱。"}, {"id": "112B-7", "y": 112, "p": "B", "no": 7, "ch": "B05", "img": "img/tc/112B_7.webp", "a": 2, "t": "等長向量和是角平分線", "c": "$|\\vec u|=|\\vec w|$ 時，$\\vec u+\\vec w$ 是菱形對角線，平分 $\\vec u$、$\\vec w$ 的夾角。", "st": [["$\\vec w$ 與 $\\vec u+\\vec w$", "$\\vec u+\\vec w$ 平分夾角，所以和 $\\vec w$ 的夾角也是 $75^{\\circ}$。"], ["反向", "$-\\vec u-\\vec w$ 和 $\\vec u+\\vec w$ 方向相反，夾角變成 $180^{\\circ}-75^{\\circ}=105^{\\circ}$，選 (C)。"]], "tr": "向量加負號，夾角要用 $180^{\\circ}$ 去減。"}, {"id": "112B-8", "y": 112, "p": "B", "no": 8, "ch": "B07", "img": "img/tc/112B_8.webp", "a": 3, "t": "等比級數整理一次不等式", "c": "常數項、$x$ 的係數各自是等比級數，先加總再解不等式。", "st": [["常數項", "$\\frac12+\\frac1{2^2}+\\cdots+\\frac1{2^5}=1-\\frac1{32}=\\frac{31}{32}$。"], ["$x$ 的係數", "$\\frac1{2^2}+\\cdots+\\frac1{2^6}=\\frac12\\cdot\\frac{31}{32}=\\frac{31}{64}$。"], ["解", "$\\frac{31}{32}+\\frac{31}{64}x\\gt 0$，兩邊乘 $\\frac{64}{31}$：$2+x\\gt 0$，$x\\gt -2$，選 (D)。"]], "tr": "$x$ 的係數剛好是常數項的一半，看出來就很快。"}, {"id": "112B-9", "y": 112, "p": "B", "no": 9, "ch": "B02", "img": "img/tc/112B_9.webp", "a": 1, "t": "斜率與點到直線距離", "c": "$ax+by+c=0$ 的斜率是 $-\\frac ab$。", "st": [["由斜率求 $a$", "$-\\frac a4=\\frac12$，$a=-2$。"], ["由距離求 $k$", "$\\dfrac{|k|}{\\sqrt{4+16}}=\\sqrt5$，$k=\\sqrt{100}=10$（$k\\gt 0$）。"], ["相加", "$a+k=8$，選 (B)。"]], "tr": "斜率是 $-\\frac ab$，負號別漏。"}, {"id": "112B-10", "y": 112, "p": "B", "no": 10, "ch": "B03", "img": "img/tc/112B_10.webp", "a": 0, "t": "因式定理配合除法原理", "c": "$f(x)=(x+2)(x-7)Q(x)+ax+3$，代除式的根就只剩餘式。", "st": [["用因式", "$x-7$ 是因式，$f(7)=0$：$7a+3=0$，$a=-\\frac37$。"], ["求 $f(-2)$", "$f(-2)=-2a+3=\\frac67+3=\\frac{27}{7}$，選 (A)。"]], "tr": "代 $x=-2$ 時，$(x+2)(x-7)Q(x)$ 那一項會變 0，只剩餘式。"}, {"id": "112B-11", "y": 112, "p": "B", "no": 11, "ch": "B08", "img": "img/tc/112B_11.webp", "a": 2, "t": "開口向下：首項係數為負", "c": "拋物線開口向下 $\\Leftrightarrow$ $x^2$ 係數 $\\lt 0$。", "st": [["列不等式", "$n^2-n-12\\lt 0$，$(n-4)(n+3)\\lt 0$，$-3\\lt n\\lt 4$。"], ["數整數", "$n=-2,-1,0,1,2,3$，共 6 個，選 (C)。"]], "tr": "端點 $-3$、$4$ 時係數為 0，不是二次函數，不能算。"}, {"id": "112B-12", "y": 112, "p": "B", "no": 12, "ch": "B08", "img": "img/tc/112B_12.webp", "a": 2, "t": "多項式相等＋分式方程式驗根", "c": "多項式相等就是同次項係數相等；分式方程式解完一定要檢查分母不為 0。", "st": [["求 $a,b$", "比較係數：$a=1$，$2a-b=3$，$b=-1$，所以 $Q(x)=x-1$。"], ["去分母", "兩邊乘 $(x-2)(x-1)$：$x(x-2)+5(x-1)=-1$，$x^2+3x-4=0$，$x=1$ 或 $-4$。"], ["驗根", "$x=1$ 使 $Q(x)=0$ 不合，$c=-4$。$a^2+b^2+c^2=1+1+16=18$，選 (C)。"]], "tr": "$x=1$ 是增根，代回去分母為 0 要捨去。"}, {"id": "112B-13", "y": 112, "p": "B", "no": 13, "ch": "B09", "img": "img/tc/112B_13.webp", "a": 1, "t": "聯立不等式的可行區域", "c": "畫出每條邊界，找出同時滿足的區域、數頂點。", "st": [["找交點", "$x+y=8$ 與 $-x+2y=10$ 交於 $(2,6)$；兩線分別交 $y$ 軸於 $(0,8)$、$(0,5)$。"], ["判斷區域", "要在 $x+y=8$ 下方、$-x+2y=10$ 上方、$x\\ge0$：圍成頂點 $(0,5)$、$(0,8)$、$(2,6)$ 的三角形。"], ["結論", "$y\\ge0$ 自動成立，選 (B)。"]], "tr": "$y\\ge0$ 這條在這題沒有作用，別硬算成四邊形。"}, {"id": "112B-14", "y": 112, "p": "B", "no": 14, "ch": "B04", "img": "img/tc/112B_14.webp", "a": 0, "t": "廣義角化簡與 tan＝sin/cos", "c": "$\\cos\\theta\\tan\\theta=\\sin\\theta$；$129^{\\circ}$、$141^{\\circ}$ 都和 $39^{\\circ}$、$51^{\\circ}$ 有關。", "st": [["第一項", "$\\cos39^{\\circ}\\tan39^{\\circ}=\\sin39^{\\circ}$。"], ["第二項", "$\\frac12\\times1\\times\\frac12=\\frac14$。"], ["第三項", "$\\sin129^{\\circ}=\\sin51^{\\circ}=\\cos39^{\\circ}$，$\\tan141^{\\circ}=-\\tan39^{\\circ}$，乘積 $=-\\sin39^{\\circ}$。"], ["相加", "$\\sin39^{\\circ}+\\frac14-\\sin39^{\\circ}=\\frac14$，選 (A)。"]], "tr": "$141^{\\circ}$ 在第二象限，tan 是負的。"}, {"id": "112B-15", "y": 112, "p": "B", "no": 15, "ch": "B07", "img": "img/tc/112B_15.webp", "a": 1, "t": "等差數列第 n 項超過門檻", "c": "$a_n=a_1+(n-1)d$，解不等式後取最小整數。", "st": [["列式", "$8+3(n-1)\\gt 42.195$，$3(n-1)\\gt 34.195$。"], ["解", "$n-1\\gt 11.4$，$n\\gt 12.4$，最小 $n=13$，選 (B)。"]], "tr": "第 12 週只跑 41 公里，還沒超過。"}, {"id": "112B-16", "y": 112, "p": "B", "no": 16, "ch": "B09", "img": "img/tc/112B_16.webp", "a": 2, "t": "內積限制轉成線性規劃", "c": "把內積寫成一次式，就變成線性規劃：在頂點找最大值。", "st": [["列條件", "$x+3y\\le14$，$2x-y\\le14$，$x,y\\ge0$；目標 $x+y$。"], ["找頂點", "$(0,0)$、$(7,0)$、$(0,\\frac{14}{3})$、兩線交點 $(8,2)$。"], ["比較", "$x+y$ 分別為 $0,7,\\frac{14}{3},10$，最大 10，選 (C)。"]], "tr": "最大值常在兩條限制線的交點，別只看軸上的點。"}, {"id": "112B-17", "y": 112, "p": "B", "no": 17, "ch": "B11", "img": "img/tc/112B_17.webp", "a": 2, "t": "餘弦定理求邊長再算面積", "c": "先在 $\\triangle AED$ 用餘弦定理求 $\\overline{AD}$，長方形面積 $=\\overline{AB}\\times\\overline{AD}$。", "st": [["求 $\\overline{AD}$", "$\\overline{AD}^2=25^2+25^2-2\\cdot25\\cdot25\\cos120^{\\circ}=3\\cdot625$，$\\overline{AD}=25\\sqrt3$。"], ["面積", "$18\\times25\\sqrt3=450\\sqrt3$，選 (C)。"]], "tr": "$\\cos120^{\\circ}=-\\frac12$，減負的變成加。"}, {"id": "112B-18", "y": 112, "p": "B", "no": 18, "ch": "B10", "img": "img/tc/112B_18.webp", "a": 2, "t": "對數不等式應用", "c": "列出不等式，用常用對數表判斷。", "st": [["列式", "$37\\log x+31\\ge70$，$\\log x\\ge\\frac{39}{37}\\approx1.054$。"], ["代選項", "$\\log10=1$ 不夠；$\\log12=2\\log2+\\log3\\approx1.079\\ge1.054$，跨過門檻。"], ["結論", "10 歲沒到、12 歲剛跨過，選 (C)。"]], "tr": "$\\log10=1\\lt 1.054$，10 歲還差一點。"}, {"id": "112B-19", "y": 112, "p": "B", "no": 19, "ch": "B13", "img": "img/tc/112B_19.webp", "a": 0, "t": "合併計算命中率", "c": "命中率 $=$ 總進球數 $\\div$ 總出手數，不能把兩種命中率直接平均。", "st": [["小楓", "$\\dfrac{50+40}{100+200}=\\dfrac{90}{300}=0.3$。"], ["小道", "$\\dfrac{90+15}{200+100}=\\dfrac{105}{300}=0.35$。"], ["比較", "小道比較高，選 (A)。"]], "tr": "小楓兩分、三分的命中率都比較高，但合起來卻輸（辛普森悖論）。"}, {"id": "112B-20", "y": 112, "p": "B", "no": 20, "ch": "B09", "img": "img/tc/112B_20.webp", "a": 1, "t": "不確定單價：最壞情形也要成立", "c": "兩種單價配法都不能超過預算，兩個不等式都要滿足。", "st": [["列條件", "$100x+200y\\le500000$ 且 $200x+100y\\le500000$，即 $x+2y\\le5000$、$2x+y\\le5000$。"], ["代選項", "(A) $1400+3800\\gt 5000$ 超過；(B) $1600+3400=5000$、$3200+1700=4900$ 都可以；(C) $1700+3600\\gt 5000$；(D) $3600+1500\\gt 5000$。"], ["結論", "選 (B)。"]], "tr": "等於 5000 剛好用完預算，沒有超過。"}, {"id": "112B-21", "y": 112, "p": "B", "no": 21, "ch": "B12", "img": "img/tc/112B_21.webp", "a": 2, "t": "扣掉法：不出現 BAD", "c": "全部猜法扣掉「有出現 BAD」的猜法。", "st": [["全部", "每題 4 種，$4^5=1024$。"], ["出現 BAD", "BAD 可在 21-23、22-24、23-25 三個位置，各自其餘 2 題任意：$3\\times4^2=48$；兩個 BAD 不可能同時出現（會重疊衝突）。"], ["相減", "$1024-48=976$，選 (C)。"]], "tr": "要確認兩段 BAD 不會同時出現，才能直接扣 48。"}, {"id": "112B-22", "y": 112, "p": "B", "no": 22, "ch": "B11", "img": "img/tc/112B_22.webp", "a": 0, "t": "正餘弦函數的最大最小值", "c": "$y=A\\sin(\\cdot)+k$ 的最大值 $k+|A|$、最小值 $k-|A|$。", "st": [["港口 A", "$16\\pm4$：滿潮 20、乾潮 12。"], ["港口 B", "$17\\pm5$：滿潮 22、乾潮 12。"], ["比對", "(A) 港口 A 滿潮 20 公尺正確，選 (A)。"]], "tr": "16、17 是平均水位，不是滿潮或乾潮。"}, {"id": "112B-23", "y": 112, "p": "B", "no": 23, "ch": "B10", "img": "img/tc/112B_23.webp", "a": 1, "t": "指數模型代值判斷", "c": "$2.7^{-0.01(t-2022)}$ 隨 $t$ 變大而變小，所以分母變小、人口遞增，但不會超過 60 萬。", "st": [["代 2022", "指數為 0，$2.7^0=1$，$y=\\dfrac{600000}{1+2}=200000$，(B) 正確。"], ["其他選項", "分母永遠大於 1，人口永遠小於 60 萬，(A) 錯；人口遞增，(C)(D) 都錯。"], ["結論", "選 (B)。"]], "tr": "任何數的 0 次方都是 1。"}, {"id": "112B-24", "y": 112, "p": "B", "no": 24, "ch": "B13", "img": "img/tc/112B_24.webp", "a": 3, "t": "條件機率：先找合乎規定的情形", "c": "每間男廁獨立、改或不改機會均等，先找符合規定的改建間數，再算條件機率。", "st": [["找可行間數", "改建 $k$ 間：友善＋女廁 $=k+4$，男廁 $4-k$。$k+4\\ge3(4-k)$ 得 $k\\ge2$；保留至少 1 間得 $k\\le3$。"], ["數方法", "$k=2$：$C^4_2=6$ 種；$k=3$：$C^4_3=4$ 種，共 10 種，每種機會相同。"], ["條件機率", "剩 2 間男廁就是 $k=2$：$\\dfrac{6}{10}=\\dfrac35$，選 (D)。"]], "tr": "每一間是否改建機會均等，所以要用 $C^4_k$ 算種數，不是把 $k=2,3$ 當成各 $\\frac12$。"}, {"id": "112B-25", "y": 112, "p": "B", "no": 25, "ch": "B11", "img": "img/tc/112B_25.webp", "a": 3, "t": "兩次仰角測高", "c": "兩個仰角 $30^{\\circ}$、$60^{\\circ}$ 搭配三角形外角，會出現等腰三角形。", "st": [["找等腰", "仰角 $60^{\\circ}$ 是外角，涼亭頂端的角 $=60^{\\circ}-30^{\\circ}=30^{\\circ}$，所以近端到涼亭的距離 $=870$。"], ["求高", "高出橋面 $870\\sin60^{\\circ}=435\\sqrt3$ 公尺。"], ["加橋高", "海拔 $=3+435\\sqrt3$ 公尺，選 (D)。"]], "tr": "題目問海拔，別忘了加橋本身的 3 公尺。"}, {"id": "112C-1", "y": 112, "p": "C", "no": 1, "ch": "C04", "img": "img/tc/112C_1.webp", "a": 0, "t": "根與係數關係：兩根之積", "c": "$ax^2+bx+c=0$ 兩根之積 $=\\dfrac ca$。", "st": [["套公式", "$\\alpha\\beta=\\dfrac{-5}{4}$。"], ["結論", "選 (A)。"]], "tr": "兩根之和才是 $-\\dfrac ba$，別搞混。"}, {"id": "112C-2", "y": 112, "p": "C", "no": 2, "ch": "C04", "img": "img/tc/112C_2.webp", "a": 0, "t": "根號與實數：奇次根 vs 偶次根", "c": "奇次方根不用加絕對值：$\\sqrt[3]{x^3}=x$；偶次方根要加：$\\sqrt{x^2}=|x|$。", "st": [["(A)", "$\\sqrt[3]{x^3}=x$ 對所有實數都成立，正確。"], ["其他", "(C) 應為 $|x|$；(B) 代 $x=1$ 得 $\\sqrt5\\neq3$；(D) 代 $x=1$ 得 $\\sqrt[3]7\\neq1$。"], ["結論", "選 (A)。"]], "tr": "$\\sqrt{a+b}\\neq\\sqrt a+\\sqrt b$，根號不能拆開。"}, {"id": "112C-3", "y": 112, "p": "C", "no": 3, "ch": "C02", "img": "img/tc/112C_3.webp", "a": 1, "t": "直角三角形求 tan", "c": "$\\tan A=\\dfrac{\\text{對邊}}{\\text{鄰邊}}$。", "st": [["畢氏定理", "$\\overline{AB}=\\sqrt{3^2-2^2}=\\sqrt5$。"], ["求 tan", "$\\tan A=\\dfrac{\\overline{BC}}{\\overline{AB}}=\\dfrac{2}{\\sqrt5}$，選 (B)。"]], "tr": "$\\angle A$ 的對邊是 $\\overline{BC}$，鄰邊是 $\\overline{AB}$，斜邊 3 不用。"}, {"id": "112C-4", "y": 112, "p": "C", "no": 4, "ch": "C03", "img": "img/tc/112C_4.webp", "a": 2, "t": "中點連線定理＋內積垂直", "c": "三角形兩邊中點連線平行第三邊；內積為 0 代表垂直。", "st": [["平行關係", "$D$、$E$ 是 $\\overline{AB}$、$\\overline{BC}$ 中點，$\\overline{DE}\\parallel\\overline{AC}$；$D$、$F$ 是 $\\overline{AB}$、$\\overline{AC}$ 中點，$\\overline{DF}\\parallel\\overline{BC}$。"], ["垂直", "$\\overrightarrow{DE}\\perp\\overrightarrow{DF}$，所以 $\\overline{AC}\\perp\\overline{BC}$，$\\angle BCA=90^{\\circ}$，選 (C)。"]], "tr": "中點連線是平行「沒有經過的那一邊」。"}, {"id": "112C-5", "y": 112, "p": "C", "no": 5, "ch": "C12", "img": "img/tc/112C_5.webp", "a": 1, "t": "聯立不等式區域落在哪個象限", "c": "先找兩直線交點，再看區域往哪邊延伸。", "st": [["交點", "$x+3y=6$ 與 $2x+y=-4$ 交於 $\\left(-\\frac{18}{5},\\frac{16}{5}\\right)$，在第二象限。"], ["推範圍", "由 $x\\ge6-3y$ 與 $y\\le-4-2x$ 得 $x\\ge6+12+6x$，即 $x\\le-\\frac{18}{5}\\lt 0$；再由 $3y\\ge6-x\\gt 6$，得 $y\\gt 2\\gt 0$。"], ["結論", "區域裡的點都是 $x\\lt 0,y\\gt 0$，屬於第二象限，選 (B)。"]], "tr": "只代一個點檢查不夠，要確認整個區域都在同一象限。"}, {"id": "112C-6", "y": 112, "p": "C", "no": 6, "ch": "C08", "img": "img/tc/112C_6.webp", "a": 3, "t": "餘弦定理求角再求高", "c": "先用餘弦定理找出 $\\angle C$，外側的直角三角形就能求高。", "st": [["求 $\\angle ACB$", "$\\cos C=\\dfrac{3^2+5^2-7^2}{2\\cdot3\\cdot5}=-\\dfrac12$，$\\angle ACB=120^{\\circ}$。"], ["外角", "$\\angle ACD=60^{\\circ}$，$\\overline{AD}=5\\sin60^{\\circ}=\\dfrac{5\\sqrt3}{2}$，選 (D)。"]], "tr": "這是鈍角三角形，高落在 $\\overline{BC}$ 的延長線上。"}, {"id": "112C-7", "y": 112, "p": "C", "no": 7, "ch": "C11", "img": "img/tc/112C_7.webp", "a": 0, "t": "矩陣乘法與平方", "c": "矩陣乘法：第 $i$ 列乘第 $j$ 行，得第 $(i,j)$ 元。", "st": [["算 $C=AB$", "$C=\\begin{bmatrix}1\\&-1\\\\0\\&1\\end{bmatrix}$。"], ["算 $C^2$", "$C^2=\\begin{bmatrix}1\\&-2\\\\0\\&1\\end{bmatrix}$，$d_{12}=-2$，選 (A)。"]], "tr": "$2\\times3$ 乘 $3\\times2$ 得 $2\\times2$，維度先確認。"}, {"id": "112C-8", "y": 112, "p": "C", "no": 8, "ch": "C02", "img": "img/tc/112C_8.webp", "a": 0, "t": "複數極式乘除：長度乘、角度加", "c": "極式相乘：長度相乘、角度相加；相除：長度相除、角度相減；$n$ 次方：長度 $n$ 次方、角度乘 $n$。", "st": [["長度", "$\\dfrac{(\\sqrt2)^2\\cdot2^4}{2^3}=\\dfrac{2\\cdot16}{8}=4=2^2$。"], ["角度", "$2\\cdot\\frac{\\pi}{4}+4\\cdot\\frac{\\pi}{6}-3\\cdot\\frac{\\pi}{3}=\\frac{\\pi}{2}+\\frac{2\\pi}{3}-\\pi=\\frac{\\pi}{6}$。"], ["結論", "$2^2(\\cos\\frac{\\pi}{6}+i\\sin\\frac{\\pi}{6})$，選 (A)。"]], "tr": "分母的 $z^3$ 角度要「減」。"}, {"id": "112C-9", "y": 112, "p": "C", "no": 9, "ch": "C10", "img": "img/tc/112C_9.webp", "a": 0, "t": "平面法向量與兩平面垂直", "c": "兩平面垂直 $\\Leftrightarrow$ 法向量互相垂直（內積為 0）。", "st": [["法向量", "$\\overrightarrow{AB}=(1,2,3)$、$\\overrightarrow{AC}=(2,3,1)$，外積 $=(-7,5,-1)$。"], ["內積為 0", "$(-7,5,-1)\\cdot(1,k,-2)=-7+5k+2=0$，$k=1$，選 (A)。"]], "tr": "外積的每個分量容易算錯，算完可以檢查和 $\\overrightarrow{AB}$ 內積是否為 0。"}, {"id": "112C-10", "y": 112, "p": "C", "no": 10, "ch": "C11", "img": "img/tc/112C_10.webp", "a": 2, "t": "已知解代回求係數", "c": "把 $x=1,y=1,z=-1$ 代回三個方程，變成 $a,b,c$ 的聯立方程。", "st": [["代入", "$a+b-c=-2$，$b+c-a=-4$，$c+a-b=6$。"], ["兩兩相加", "(1)+(2)：$2b=-6$，$b=-3$；(1)+(3)：$2a=4$，$a=2$；(2)+(3)：$2c=2$，$c=1$。"], ["檢查", "$ab=-6$、$bc=-3$、$ac=2$、$abc=-6$，選 (C)。"]], "tr": "注意 $z=-1$，代入時符號要變。"}, {"id": "112C-11", "y": 112, "p": "C", "no": 11, "ch": "C04", "img": "img/tc/112C_11.webp", "a": 2, "t": "絕對值不等式反推係數", "c": "$x\\le-2$ 或 $x\\ge6$ 就是「與中點 2 的距離 $\\ge4$」：$|x-2|\\ge4$。", "st": [["轉成標準形", "$|x-2|\\ge4$ 乘 3：$|3x-6|\\ge12$，也就是 $|-3x+6|\\ge12$。"], ["對照", "$A=-3$，$B=12$。"], ["計算", "$2A+B=-6+12=6$，選 (C)。"]], "tr": "$A$ 也可以從 $-\\frac{6}{A}=2$ 求得，符號是負的。"}, {"id": "112C-12", "y": 112, "p": "C", "no": 12, "ch": "C04", "img": "img/tc/112C_12.webp", "a": 3, "t": "實係數方程虛根成對", "c": "實係數多項式的虛根一定共軛成對出現。", "st": [["找共軛", "$a$ 是實根，所以 $b+2i$ 和 $-1+ai$ 互為共軛：$b=-1$，$a=-2$。"], ["三根", "$-2$、$-1+2i$、$-1-2i$。"], ["寫出 $f(x)$", "$(x+2)(x^2+2x+5)=x^3+4x^2+9x+10$，選 (D)。"]], "tr": "共軛是虛部變號：$b+2i$ 的共軛是 $b-2i$，所以 $a=-2$。"}, {"id": "112C-13", "y": 112, "p": "C", "no": 13, "ch": "C06", "img": "img/tc/112C_13.webp", "a": 1, "t": "複利公式", "c": "本金 $P$ 以年利率 $r$ 複利 $n$ 年：本利和 $=P(1+r)^n$。", "st": [["數年數", "2018 年初到 2023 年初共 5 年。"], ["列式", "$50(1+r)^5=60$，選 (B)。"]], "tr": "複利是乘 $(1+r)$，不是乘 $r$。"}, {"id": "112C-14", "y": 112, "p": "C", "no": 14, "ch": "C15", "img": "img/tc/112C_14.webp", "a": 2, "t": "速度積分求距離", "c": "距離 $=$ 速度對時間的定積分。", "st": [["烏龜時間", "烏龜到終點要 $2000\\div250=8$ 小時。"], ["兔子追趕多久", "兔子在 $0.5+6.5=7$ 小時醒來，烏龜 8 小時到，兔子只跑 1 小時。"], ["積分", "$\\int_0^1(27t^2+52t+1262)\\,dt=9+26+1262=1297$，兔子在 $600+1297=1897$ 公尺。"], ["相減", "$2000-1897=103$ 公尺，選 (C)。"]], "tr": "兔子醒來時 $t$ 從 0 重新算起，積分範圍是 0 到 1。"}, {"id": "112C-15", "y": 112, "p": "C", "no": 15, "ch": "C06", "img": "img/tc/112C_15.webp", "a": 3, "t": "無窮數列極限：有理化", "c": "兩個根號相減趨近 $\\infty-\\infty$，先有理化。", "st": [["有理化", "$\\dfrac{(n^2+8n-3)-(n^2+2n+5)}{\\sqrt{n^2+8n-3}+\\sqrt{n^2+2n+5}}=\\dfrac{6n-8}{\\sqrt{n^2+8n-3}+\\sqrt{n^2+2n+5}}$。"], ["同除 $n$", "分子 $\\to6$，分母 $\\to1+1=2$，極限 $=3$，選 (D)。"]], "tr": "不能直接說 $\\infty-\\infty=0$。"}, {"id": "112C-16", "y": 112, "p": "C", "no": 16, "ch": "C05", "img": "img/tc/112C_16.webp", "a": 0, "t": "四點共圓：先由三點求圓", "c": "弦的中垂線一定過圓心，先用三點找出圓。", "st": [["找圓心", "$B(2,-3)$、$C(2,7)$ 的中垂線是 $y=2$，圓心 $(h,2)$；$A(1,2)$ 也在 $y=2$ 上。"], ["求 $h$", "$(h-1)^2=(h-2)^2+25$，$2h-3=25$，$h=14$，半徑 13。"], ["代 $D$", "$(a-14)^2+144=169$，$a-14=\\pm5$，$a=19$ 或 $9$，選 (A)。"]], "tr": "$(a-14)^2=25$ 有兩個解，別只取一個。"}, {"id": "112C-17", "y": 112, "p": "C", "no": 17, "ch": "C09", "img": "img/tc/112C_17.webp", "a": 3, "t": "等差與等比成長比較", "c": "加固定金額是等差，乘固定比例是等比，等比要用對數解。", "st": [["小明", "$30000+3000(x-1)\\ge80000$，$x-1\\ge16.7$，第 18 年到達（$x=18$）。"], ["小亮", "$30000\\cdot1.03^{y-1}\\ge80000$，$(y-1)\\log1.03\\ge\\log\\frac83$，$y-1\\ge\\frac{0.426}{0.0128}\\approx33.3$，第 35 年到達（$y=35$）。"], ["相減", "$x-y=18-35=-17$，選 (D)。"]], "tr": "$3\\%$ 看起來快，但前期金額小，反而慢很多年。"}, {"id": "112C-18", "y": 112, "p": "C", "no": 18, "ch": "C08", "img": "img/tc/112C_18.webp", "a": 1, "t": "連續轉折用坐標或餘弦定理", "c": "把路線放到坐標平面上，用角度寫出每一段的位移。", "st": [["放坐標", "$O=(0,0)$，$A=(-2,0)$；$\\angle OAB=120^{\\circ}$，$B=A+6(\\cos120^{\\circ},\\sin120^{\\circ})=(-5,3\\sqrt3)$。"], ["求 $C$", "$\\angle ABC=120^{\\circ}$，$\\overrightarrow{BC}$ 方向 $60^{\\circ}$：$C=(-5+2,3\\sqrt3+2\\sqrt3)=(-3,5\\sqrt3)$。"], ["距離", "$\\overline{OC}=\\sqrt{9+75}=\\sqrt{84}=2\\sqrt{21}$，選 (B)。"]], "tr": "也可先算 $\\overline{OB}$ 再用餘弦定理，但角度要算對。"}, {"id": "112C-19", "y": 112, "p": "C", "no": 19, "ch": "C09", "img": "img/tc/112C_19.webp", "a": 0, "t": "對數關係轉指數圖形", "c": "$\\log E=11.8+1.5M$ 等於 $E=10^{11.8+1.5M}$，是指數函數。", "st": [["改寫", "$E=10^{11.8}\\cdot(10^{1.5})^M$，底數大於 1。"], ["圖形特徵", "$E$ 恆正、隨 $M$ 增加而遞增，而且越來越陡，選 (A)。"]], "tr": "(C) 是對數圖形，那是把 $M$、$E$ 對調的樣子。"}, {"id": "112C-20", "y": 112, "p": "C", "no": 20, "ch": "C07", "img": "img/tc/112C_20.webp", "a": 1, "t": "分類乘法：主菜與湯搭配", "c": "先處理有限制的主菜和湯，再乘上沒限制的飯和飲料。", "st": [["主菜與湯", "紅肉主菜 2 種配白肉湯 2 種（魚丸、雞湯）：4；白肉主菜 2 種配紅肉湯 2 種：4；共 8 種。"], ["相乘", "$5\\times8\\times4=160$，選 (B)。"]], "tr": "貢丸湯是豬肉，算紅肉湯。"}, {"id": "112C-21", "y": 112, "p": "C", "no": 21, "ch": "C13", "img": "img/tc/112C_21.webp", "a": 1, "t": "橢圓短軸半長", "c": "到兩焦點距離和為定值 $2a$ 的點形成橢圓；離焦點連線最遠的是短軸端點，距離 $b$。", "st": [["找 $a,c$", "$2a=8$，$a=4$；兩焦點距 4，$c=2$。"], ["求 $b$", "$b=\\sqrt{a^2-c^2}=\\sqrt{16-4}=2\\sqrt3$，選 (B)。"]], "tr": "$c$ 是焦距的一半，是 2 不是 4。"}, {"id": "112C-22", "y": 112, "p": "C", "no": 22, "ch": "C08", "img": "img/tc/112C_22.webp", "a": 2, "t": "立體畢氏定理＋圓周角", "c": "直徑所對圓周角是直角；桿子垂直地面，地面上的線都和桿子垂直。", "st": [["桿高", "$\\overline{AC}^2=20^2-10^2=300$。"], ["$\\overline{CD}$", "$\\angle BDC=90^{\\circ}$，$\\overline{CD}=10\\cos30^{\\circ}=5\\sqrt3$，$\\overline{CD}^2=75$。"], ["$\\overline{AD}$", "$\\overline{AD}=\\sqrt{300+75}=\\sqrt{375}=5\\sqrt{15}$，選 (C)。"]], "tr": "$\\overline{CD}$ 是 $\\angle BCD$ 的鄰邊，用 cos 不是 sin。"}, {"id": "112C-23", "y": 112, "p": "C", "no": 23, "ch": "C14", "img": "img/tc/112C_23.webp", "a": 3, "t": "切線斜率與垂直", "c": "切線斜率就是導數值；兩切線垂直時斜率相乘 $=-1$。", "st": [["$L_1$ 斜率", "$f'(x)=\\dfrac{1}{2\\sqrt x}-1$，$f'(1)=-\\dfrac12$，所以 $L_2$ 斜率 $=2$。"], ["列方程", "$g(1)=a+b=0$，$g'(1)=3a+b=2$。"], ["解", "$a=1$，$b=-1$，$ab=-1$，選 (D)。"]], "tr": "別忘了 $g$ 也要過 $(1,0)$ 這個條件。"}, {"id": "112C-24", "y": 112, "p": "C", "no": 24, "ch": "C14", "img": "img/tc/112C_24.webp", "a": 3, "t": "導數求相對極值", "c": "$f'(x)=0$ 找臨界點，$f'$ 由正變負的地方是相對極大。", "st": [["微分", "$f'(x)=3x^2+6x-72=3(x+6)(x-4)$。"], ["看正負", "$x\\lt -6$ 時 $f'\\gt 0$，$-6\\lt x\\lt 4$ 時 $f'\\lt 0$：$x=-6$ 由增轉減，是相對極大；$x=4$ 是相對極小。"], ["結論", "選 (D)。"]], "tr": "三次項係數為正，左邊的臨界點才是極大。"}, {"id": "112C-25", "y": 112, "p": "C", "no": 25, "ch": "C02", "img": "img/tc/112C_25.webp", "a": 1, "t": "正弦函數週期求 a", "c": "$y=\\sin(ax+b)$ 的週期是 $\\dfrac{2\\pi}{a}$。", "st": [["週期", "轉一圈 4 秒，週期 $=4$。"], ["求 $a$", "$\\dfrac{2\\pi}{a}=4$，$a=\\dfrac{\\pi}{2}$。"], ["檢查", "$x=0$ 時 $f=40\\sin\\frac{\\pi}{2}+70=110$，正好是最高點，符合題意，選 (B)。"]], "tr": "週期是 $\\frac{2\\pi}{a}$，不是 $a$ 本身。"}, {"id": "113A-1", "y": 113, "p": "A", "no": 1, "ch": "A07", "img": "img/tc/113A_1.webp", "a": 3, "t": "一次不等式的最大整數解", "c": "一次不等式就像解方程式，移項整理；只有乘除負數時不等號才要變向。", "st": [["移項整理", "$3x-2\\lt x+3 \\Rightarrow 2x\\lt 5 \\Rightarrow x\\lt \\frac{5}{2}=2.5$"], ["找最大整數", "比 $2.5$ 小的最大整數是 $2$（注意是「小於」，$2.5$ 本身不算），選 (D)。"]], "tr": "看到 $2.5$ 就四捨五入成 $3$；$3\\gt 2.5$ 不符合不等式。"}, {"id": "113A-2", "y": 113, "p": "A", "no": 2, "ch": "A04", "img": "img/tc/113A_2.webp", "a": 2, "t": "由 cot 值求 cos", "c": "$\\frac{1}{\\tan B}=\\cot B=\\frac{\\text{鄰邊}}{\\text{對邊}}$，畫一個直角三角形就能讀出 $\\cos B$。", "st": [["判斷角的範圍", "$\\cot B=\\frac{3}{4}\\gt 0$，三角形內角又在 $0^{\\circ}$～$180^{\\circ}$，所以 $B$ 是銳角。"], ["畫直角三角形", "鄰邊 $3$、對邊 $4$，斜邊 $=\\sqrt{3^2+4^2}=5$。"], ["求 cos B", "$\\cos B=\\frac{\\text{鄰邊}}{\\text{斜邊}}=\\frac{3}{5}$，選 (C)。"]], "tr": "把 $\\frac{3}{4}$ 當成 $\\tan B$，算出 $\\cos B=\\frac{4}{5}$ 選 (D)。"}, {"id": "113A-3", "y": 113, "p": "A", "no": 3, "ch": "A06", "img": "img/tc/113A_3.webp", "a": 0, "t": "每年成長 10%：等比數列", "c": "每年都乘上同一個倍數 $1.1$，就是等比數列。", "st": [["列式", "今年 $200$，明年 $200\\times1.1$，後年再乘一次 $1.1$：$200\\times1.1^2$。"], ["計算", "$1.1^2=1.21$，$200\\times1.21=242$ 元，選 (A)。"]], "tr": "以為每年都加 $20$ 元得 $240$；第二年是以 $220$ 為基準再漲 $10\\%$。"}, {"id": "113A-4", "y": 113, "p": "A", "no": 4, "ch": "A03", "img": "img/tc/113A_4.webp", "a": 3, "t": "餘式定理：代 x=1", "c": "$f(x)$ 除以 $(x-a)$ 的餘式就是 $f(a)$，不用真的做長除法。", "st": [["代入 x=1", "$x^3-1$ 和 $x-1$ 在 $x=1$ 時都是 $0$，所以前兩大項直接變 $0$。"], ["算餘式", "$f(1)=0+0-2\\cdot1+7=5$，選 (D)。"]], "tr": "傻傻展開高次多項式去做除法，浪費時間又容易算錯。"}, {"id": "113A-5", "y": 113, "p": "A", "no": 5, "ch": "A09", "img": "img/tc/113A_5.webp", "a": 2, "t": "取前三名有順序：排列", "c": "冠、亞、季軍有先後之分，所以是「排列」不是「組合」。", "st": [["逐名次填入", "冠軍 $6$ 種選法，亞軍剩 $5$ 種，季軍剩 $4$ 種。"], ["相乘", "$P^6_3=6\\times5\\times4=120$，選 (C)。"]], "tr": "用組合 $C^6_3=20$ 算，忘了名次有順序。"}, {"id": "113A-6", "y": 113, "p": "A", "no": 6, "ch": "A08", "img": "img/tc/113A_6.webp", "a": 2, "t": "log 的首數", "c": "$\\log N$ 的整數部分叫首數；先把 $\\log 3^{10}$ 換成 $10\\log3$ 算出數值。", "st": [["化簡", "$\\log3^{10}=10\\log3\\approx10\\times0.4771=4.771$"], ["讀首數", "$4.771=4+0.771$，首數是 $4$（也代表 $3^{10}$ 是 $5$ 位數），選 (C)。"]], "tr": "把首數和「位數」搞混，誤選 $5$。"}, {"id": "113A-7", "y": 113, "p": "A", "no": 7, "ch": "A02", "img": "img/tc/113A_7.webp", "a": 1, "t": "截距正負與象限", "c": "直線通過一、二、三象限 ⇒ 斜率正、往左下延伸會先碰到負的 $x$ 軸、往上碰到正的 $y$ 軸。", "st": [["畫出直線的樣子", "通過一、二、三象限（不經過第四象限）的直線是「左低右高」，而且在原點上方切過 $y$ 軸。"], ["判斷截距正負", "$y$ 截距 $b\\gt 0$；直線往左下穿過 $x$ 軸的地方在負半軸，所以 $x$ 截距 $a\\lt 0$。"], ["判斷象限", "點 $(a,b)$ 是（負, 正），在第二象限，選 (B)。"]], "tr": "把 $x$ 截距、$y$ 截距的正負對調。"}, {"id": "113A-8", "y": 113, "p": "A", "no": 8, "ch": "A01", "img": "img/tc/113A_8.webp", "a": 1, "t": "絕對值＝距離：中點", "c": "$|a+11|$ 是 $a$ 到 $-11$ 的距離，$|a-1|$ 是 $a$ 到 $1$ 的距離，距離相等就是中點。", "st": [["找中點", "$a$ 是 $-11$ 與 $1$ 的中點：$a=\\frac{-11+1}{2}=-5$。"], ["求 k", "$k=|-5-1|=6$，選 (B)。"]], "tr": "把 $|a+11|$ 當成 $a$ 到 $11$ 的距離，正負號看反。"}, {"id": "113A-9", "y": 113, "p": "A", "no": 9, "ch": "A05", "img": "img/tc/113A_9.webp", "a": 1, "t": "直線與圓的交點", "c": "把直線代入圓方程式解聯立；或直接把選項代入兩式驗證。", "st": [["代入消去", "$L$：$y=x+1$，代入 $x^2+y^2=25$：$x^2+(x+1)^2=25 \\Rightarrow x^2+x-12=0$。"], ["解出交點", "$(x+4)(x-3)=0$，$x=-4$ 或 $3$，交點為 $(-4,-3)$、$(3,4)$。"], ["對照選項", "$(-4,-3)$ 在選項中，選 (B)。"]], "tr": "只驗證點在圓上就選，(A) $(-4,3)$ 在圓上但不在直線上。"}, {"id": "113A-10", "y": 113, "p": "A", "no": 10, "ch": "A04", "img": "img/tc/113A_10.webp", "a": 0, "t": "仰角 45° 的高度", "c": "仰角 $45^{\\circ}$ 的直角三角形是等腰直角三角形，高度＝水平距離。", "st": [["列式", "高度 $h=20\\tan45^{\\circ}$。"], ["計算", "$\\tan45^{\\circ}=1$，$h=20$ 公尺，選 (A)。"]], "tr": "誤用斜邊長 $20\\sqrt{2}$ 當高度。"}, {"id": "113A-11", "y": 113, "p": "A", "no": 11, "ch": "A08", "img": "img/tc/113A_11.webp", "a": 0, "t": "指數律：全部化成底數 2", "c": "把每個數都換成 $2$ 的次方，乘法就變成指數相加。", "st": [["統一底數", "$8=2^3$、$4^4=2^8$、$2^3$、$\\left(\\frac12\\right)^a=2^{-a}$、$\\left(\\frac14\\right)^4=2^{-8}$。"], ["指數相加", "$2^{3+8+3-a-8}=2^{6-a}=1=2^0$。"], ["求 a", "$6-a=0 \\Rightarrow a=6$，選 (A)。"]], "tr": "$\\left(\\frac14\\right)^4$ 要化成 $2^{-8}$，不是 $2^{-4}$。"}, {"id": "113A-12", "y": 113, "p": "A", "no": 12, "ch": "A08", "img": "img/tc/113A_12.webp", "a": 3, "t": "對數相加＝真數相乘", "c": "同底的 $\\log$ 相加，真數可以直接相乘：$\\log_a M+\\log_a N=\\log_a MN$。", "st": [["合併真數", "$4\\times2\\times1\\times\\frac12\\times\\frac14=1$"], ["得到結果", "原式 $=\\log_3 1$（$=0$），選 (D)。"]], "tr": "把 $\\log_3\\frac12$ 誤當成 $\\frac12\\log_3$ 之類的錯誤拆法。"}, {"id": "113A-13", "y": 113, "p": "A", "no": 13, "ch": "A05", "img": "img/tc/113A_13.webp", "a": 1, "t": "過圓上一點的切線斜率", "c": "切線垂直於「圓心到切點」的半徑，斜率相乘 $=-1$。", "st": [["先檢查原點在不在圓上", "圓心 $(3,-4)$ 到原點距離 $=\\sqrt{9+16}=5=$ 半徑，原點就在圓上，是切點。"], ["半徑斜率", "圓心到原點的斜率 $=\\frac{-4-0}{3-0}=-\\frac43$。"], ["切線斜率", "垂直 ⇒ 切線斜率 $=\\frac34$，選 (B)。"]], "tr": "直接拿半徑斜率 $-\\frac43$ 或只把正負號變掉選 $\\frac43$。"}, {"id": "113A-14", "y": 113, "p": "A", "no": 14, "ch": "A07", "img": "img/tc/113A_14.webp", "a": 3, "t": "費用比較：列不等式", "c": "把兩家的月費寫成次數 $n$ 的式子，再列「甲 &lt; 乙」的不等式。", "st": [["列費用", "每次 $30$ 分鐘，甲：$900+30n$ 元；乙：固定 $1380$ 元。"], ["解不等式", "$900+30n\\lt 1380 \\Rightarrow 30n\\lt 480 \\Rightarrow n\\lt 16$。"], ["對照選項", "只有 $15$ 次小於 $16$，選 (D)。"]], "tr": "忘了每次健身 $30$ 分鐘，把每次只算 $1$ 元。"}, {"id": "113A-15", "y": 113, "p": "A", "no": 15, "ch": "A06", "img": "img/tc/113A_15.webp", "a": 1, "t": "等差級數求和", "c": "等差級數和 $=\\frac{(\\text{首項}+\\text{末項})\\times\\text{項數}}{2}$。", "st": [["找首末項", "$a_1=3\\cdot1+2=5$，$a_{10}=3\\cdot10+2=32$。"], ["套公式", "$S_{10}=\\frac{(5+32)\\times10}{2}=185$，選 (B)。"]], "tr": "把常數 $2$ 只加一次，算成 $3\\times55+2=167$；常數要加 $10$ 次。"}, {"id": "113A-16", "y": 113, "p": "A", "no": 16, "ch": "A03", "img": "img/tc/113A_16.webp", "a": 2, "t": "零多項式：係數全為 0", "c": "$f(x)-g(x)$ 是零多項式 ⇒ $f(x)$ 和 $g(x)$ 根本是同一個多項式。", "st": [["比較係數", "$a=3$、$-b=2 \\Rightarrow b=-2$、$c=-1$，所以 $f(x)=g(x)=3x^2+2x-1$。"], ["化簡所求", "$2f(-1)-3g(-1)=2f(-1)-3f(-1)=-f(-1)$。"], ["代入", "$f(-1)=3-2-1=0$，所求 $=0$，選 (C)。"]], "tr": "$-bx$ 對應 $2x$，得 $b=-2$，常把負號漏掉。"}, {"id": "113A-17", "y": 113, "p": "A", "no": 17, "ch": "A07", "img": "img/tc/113A_17.webp", "a": 1, "t": "不等式區域面積", "c": "先找出每條邊界線的交點（頂點），再算多邊形面積。", "st": [["找頂點", "$3x+2y=6$ 與 $3x-2y=6$ 交於 $(2,0)$；分別與 $x=0$ 交於 $(0,3)$、$(0,-3)$。"], ["確認區域", "代原點 $(0,0)$ 三式都成立，區域是三點圍成的三角形。"], ["算面積", "底在 $y$ 軸上長 $6$，高 $2$：$\\frac{6\\times2}{2}=6$，選 (B)。"]], "tr": "只算 $x$ 軸上方那一半，得到 $3$ 或誤以為 $12$。"}, {"id": "113A-18", "y": 113, "p": "A", "no": 18, "ch": "A10", "img": "img/tc/113A_18.webp", "a": 0, "t": "系統抽樣的判斷", "c": "編號後「每隔固定間隔抽一個」就是系統抽樣。", "st": [["看抽法", "個位數為 $3$ 的編號：$003,013,023,\\dots$，每隔 $10$ 號抽一個，間隔固定。"], ["判斷", "隨機決定起點、再等間隔抽取，正是系統抽樣，選 (A)。"]], "tr": "看到「隨機亂數」就選簡單隨機抽樣；這裡只有起點是隨機的。"}, {"id": "113A-19", "y": 113, "p": "A", "no": 19, "ch": "A10", "img": "img/tc/113A_19.webp", "a": 0, "t": "以下累積次數→眾數", "c": "相鄰兩個累積次數相減，就是每一組的次數；次數最多的就是眾數。", "st": [["還原各組次數", "1人：$3$；2人：$9-3=6$；3人：$17-9=8$；4人：$19-17=2$；5人：$20-19=1$。"], ["找最多", "每戶 $3$ 人有 $8$ 戶最多，眾數為 $3$，選 (A)。"]], "tr": "直接拿累積次數最大的 $20$ 去找，誤選 $5$。"}, {"id": "113A-20", "y": 113, "p": "A", "no": 20, "ch": "A09", "img": "img/tc/113A_20.webp", "a": 2, "t": "相鄰座位：先數相鄰位置", "c": "先找出「可以相鄰的兩個座位」有幾組，再排兩人與其他人。", "st": [["找相鄰位置", "$A$-$B$、$C$-$D$、$D$-$E$，共 $3$ 組相鄰座位。"], ["排兩人與其他人", "兩人在一組座位內可對調 $2!$ 種，其餘 $3$ 人坐剩下 $3$ 位 $3!$ 種。"], ["相乘", "$3\\times2\\times6=36$，選 (C)。"]], "tr": "把 $B$ 和 $C$ 也當成相鄰（不同排、中間隔走道），多算了組數。"}, {"id": "113A-21", "y": 113, "p": "A", "no": 21, "ch": "A02", "img": "img/tc/113A_21.webp", "a": 3, "t": "垂直斜率乘積為 -1", "c": "直角三角形有兩邊互相垂直，它們的斜率相乘 $=-1$，所以一正一負。", "st": [["兩股斜率一正一負", "互相垂直的兩邊斜率乘積 $=-1$，一定一正一負。"], ["推出最大最小", "有正有負 ⇒ 最大的 $m_1\\gt 0$，最小的 $m_3\\lt 0$。"], ["判斷", "$m_1m_3\\lt 0$ 恆成立；$m_2$ 正負不一定，所以 (A)(B) 不恆正確，選 (D)。"]], "tr": "以為垂直的兩邊一定是 $m_1$ 與 $m_3$；其實不必，但最大最小必定異號。"}, {"id": "113A-22", "y": 113, "p": "A", "no": 22, "ch": "A07", "img": "img/tc/113A_22.webp", "a": 3, "t": "至少＝大於等於", "c": "「至少需要」要寫成 $\\ge$；每種營養成分各列一條。", "st": [["成分 A", "甲 $15x$、乙 $5y$，至少 $35$：$15x+5y\\ge35$。"], ["成分 B", "甲 $5x$、乙 $15y$，至少 $25$：$5x+15y\\ge25$。"], ["加上非負條件", "$x\\ge0$、$y\\ge0$，選 (D)。"]], "tr": "把 $35$、$25$ 放錯成分，誤選 (C)。"}, {"id": "113A-23", "y": 113, "p": "A", "no": 23, "ch": "A10", "img": "img/tc/113A_23.webp", "a": 2, "t": "算術平均數的範圍", "c": "$a$ 被夾在 $100$ 與 $200$ 之間，總和與平均數也跟著被夾住。", "st": [["找 a 的範圍", "由小到大排列 ⇒ $100\\le a\\le200$。"], ["平均數範圍", "平均 $=\\frac{1000+a}{5}$，介於 $\\frac{1100}{5}=220$ 與 $\\frac{1200}{5}=240$。"], ["對照選項", "只有 $230$ 在範圍內，選 (C)。"]], "tr": "以為中位數 $200$ 就是平均數附近，選 $210$。"}, {"id": "113A-24", "y": 113, "p": "A", "no": 24, "ch": "A09", "img": "img/tc/113A_24.webp", "a": 2, "t": "中位數固定的組合數", "c": "5 人的中位數是第 3 位，要等於 $175$，就要比它矮的 2 人、比它高的 2 人。", "st": [["175 一定要選", "$175$ 必須入選並排在第 $3$ 位。"], ["左右各選兩人", "比 $175$ 矮的 $3$ 人選 $2$：$C^3_2=3$；比 $175$ 高的 $3$ 人選 $2$：$C^3_2=3$。"], ["相乘", "$3\\times3=9$，選 (C)。"]], "tr": "把兩邊相加 $3+3$ 而不是相乘。"}, {"id": "113A-25", "y": 113, "p": "A", "no": 25, "ch": "A10", "img": "img/tc/113A_25.webp", "a": 0, "t": "和事件與餘事件", "c": "「完全中斷」＝兩條都不通 ＝ 1 −「至少一條能通」。", "st": [["至少一條能通", "$P(A\\cup B)=0.6+0.7-0.5=0.8$"], ["取餘事件", "$1-0.8=0.2$，選 (A)。"]], "tr": "當成獨立事件用 $0.4\\times0.3=0.12$；題目給了兩條皆通 $0.5$，不是獨立。"}, {"id": "113B-1", "y": 113, "p": "B", "no": 1, "ch": "B05", "img": "img/tc/113B_1.webp", "a": 0, "t": "內積的坐標算法", "c": "$\\overrightarrow{a}\\cdot\\overrightarrow{b}=x_1x_2+y_1y_2$，對應分量相乘再相加。", "st": [["套公式", "$(x,1)\\cdot(2,y)=2x+y$。"], ["列式", "$2x+y=10$，選 (A)。"]], "tr": "把內積當成分量交叉相乘得 $xy+2$。"}, {"id": "113B-2", "y": 113, "p": "B", "no": 2, "ch": "B01", "img": "img/tc/113B_2.webp", "a": 0, "t": "絕對值表示距離", "c": "數線上 $|p-q|$ 就是 $p$、$q$ 兩點的距離。", "st": [["我們與惡的距離", "$|x-2|$。"], ["善與惡的距離", "$|3-2|$。"], ["寫成不等式", "$|x-2|\\lt |3-2|$，選 (A)。"]], "tr": "把「善與惡」寫成 $|x-3|$（我們與善）。"}, {"id": "113B-3", "y": 113, "p": "B", "no": 3, "ch": "B04", "img": "img/tc/113B_3.webp", "a": 0, "t": "sin 在各象限的變化", "c": "$\\sin(2\\theta-360^{\\circ})=\\sin2\\theta$，再看 $2\\theta$ 走過哪些象限。", "st": [["化簡", "減掉一圈 $360^{\\circ}$ 不影響值：$\\sin(2\\theta-360^{\\circ})=\\sin2\\theta$。"], ["看角度範圍", "$\\theta$ 從 $50^{\\circ}$ 到 $100^{\\circ}$，$2\\theta$ 從 $100^{\\circ}$ 到 $200^{\\circ}$。"], ["判斷", "$100^{\\circ}\\to180^{\\circ}$ 時 $\\sin$ 為正且遞減，過了 $180^{\\circ}$ 變負且繼續減少，所以「從正遞減到負」，選 (A)。"]], "tr": "只看 $\\theta$ 本身的範圍，忘了角度是 $2\\theta$。"}, {"id": "113B-4", "y": 113, "p": "B", "no": 4, "ch": "B02", "img": "img/tc/113B_4.webp", "a": 1, "t": "平行與垂直的斜率", "c": "平行 ⇒ 斜率相同；垂直 ⇒ 斜率相乘 $=-1$。", "st": [["L1、L2 斜率", "$L_1$ 斜率 $=-1$，$L_2\\parallel L_1$ 斜率也是 $-1$。"], ["L3 斜率", "$L_3\\perp L_2$ ⇒ 斜率 $=1$；過 $(113,114)$：$y-114=x-113$，即 $y=x+1$。"], ["求 x 截距", "令 $y=0$：$x=-1$，選 (B)。"]], "tr": "$x$ 截距要令 $y=0$，別令 $x=0$ 算成 $y$ 截距 $1$。"}, {"id": "113B-5", "y": 113, "p": "B", "no": 5, "ch": "B03", "img": "img/tc/113B_5.webp", "a": 3, "t": "餘式定理：逐一代入檢查", "c": "除以 $(x-1)$ 餘 2 ⇒ $f(1)=2$；除以 $(x-2)$ 餘 1 ⇒ $f(2)=1$。", "st": [["前面那項都會消失", "$2024(x-1)(x-2)$ 在 $x=1$、$x=2$ 都是 $0$，只要看後面。"], ["逐一代入", "(A) $f(1)=3$ ✗；(B) $f(2)=-1$ ✗；(C) $f(2)=3$ ✗；(D) $f(1)=-(-1)+1=2$、$f(2)=0+1=1$ ✓。"], ["結論", "選 (D)。"]], "tr": "只檢查其中一個條件就下結論，(B) 也滿足 $f(1)=2$。"}, {"id": "113B-6", "y": 113, "p": "B", "no": 6, "ch": "B11", "img": "img/tc/113B_6.webp", "a": 2, "t": "正弦定理求外接圓", "c": "正弦定理：$\\frac{a}{\\sin A}=2R$，邊和對角就能求外接圓半徑。", "st": [["套正弦定理", "$\\overline{BC}$ 對角 $A=30^{\\circ}$：$2R=\\frac{5}{\\sin30^{\\circ}}=\\frac{5}{1/2}=10$，$R=5$。"], ["算面積", "噴水池就是外接圓，面積 $=\\pi\\cdot5^2=25\\pi$，選 (C)。"]], "tr": "忘了 $\\frac{a}{\\sin A}$ 是直徑 $2R$，直接當半徑算出 $100\\pi$。"}, {"id": "113B-7", "y": 113, "p": "B", "no": 7, "ch": "B10", "img": "img/tc/113B_7.webp", "a": 3, "t": "翻倍時間：取對數", "c": "$40000\\times1.02^n=80000$ ⇒ $1.02^n=2$，兩邊取 $\\log$ 把 $n$ 拉下來。", "st": [["列式", "$1.02^n=2 \\Rightarrow n\\log1.02=\\log2$。"], ["查值計算", "$\\log1.02\\approx0.0086$，$\\log2\\approx0.3010$，$n\\approx\\frac{0.3010}{0.0086}=35$。"], ["結論", "約 $35$ 年後月薪最接近 $8$ 萬元，選 (D)。"]], "tr": "用單利想成每年加 $800$ 元，算出 $50$ 年。"}, {"id": "113B-8", "y": 113, "p": "B", "no": 8, "ch": "B03", "img": "img/tc/113B_8.webp", "a": 2, "t": "文氏圖：集合人數", "c": "用文氏圖分成「只有汽車、兩者都有、只有機車」三塊，總和 $100$。", "st": [["設未知數", "僅有汽車 $x$ 人，僅有機車 $x+10$ 人，兩者都有 $20$ 人。"], ["列式", "$x+(x+10)+20=100 \\Rightarrow 2x=70 \\Rightarrow x=35$。"], ["結論", "僅有汽車 $35$ 位，選 (C)。"]], "tr": "忘了扣掉兩者都有的 $20$ 人，算出 $45$。"}, {"id": "113B-9", "y": 113, "p": "B", "no": 9, "ch": "B08", "img": "img/tc/113B_9.webp", "a": 3, "t": "根與係數關係", "c": "$x^2+bx+c=0$ 的兩根：$\\alpha+\\beta=-b$、$\\alpha\\beta=c$。", "st": [["寫出兩根和與積", "$\\alpha+\\beta=-3$，$\\alpha\\beta=c$。"], ["通分", "$\\frac1\\alpha+\\frac1\\beta=\\frac{\\alpha+\\beta}{\\alpha\\beta}=\\frac{-3}{c}=1 \\Rightarrow c=-3$。"], ["檢查相異實根", "判別式 $9-4(-3)=21\\gt 0$ ✓，選 (D)。"]], "tr": "兩根和忘了加負號，寫成 $\\alpha+\\beta=3$ 而得 $c=3$。"}, {"id": "113B-10", "y": 113, "p": "B", "no": 10, "ch": "B09", "img": "img/tc/113B_10.webp", "a": 1, "t": "代點判斷直線同側異側", "c": "把點代入 $2x-3y-6$：同側的點正負號相同，異側的點正負號相反。", "st": [["C 點的符號", "$2(1)-3(3)-6=-13\\lt 0$。"], ["A、B 的符號", "$A$ 與 $C$ 同側 ⇒ $2a_1-3a_2-6\\lt 0$；$B$ 與 $C$ 異側 ⇒ $2b_1-3b_2-6\\gt 0$。"], ["判斷象限", "點坐標是（負, 正），在第二象限，選 (B)。"]], "tr": "誤以為 $C$ 代入是正的，整題正負全反。"}, {"id": "113B-11", "y": 113, "p": "B", "no": 11, "ch": "B03", "img": "img/tc/113B_11.webp", "a": 3, "t": "第二件 7 折列式", "c": "貴的原價、便宜的打 7 折，先判斷哪一罐比較便宜。", "st": [["兩罐價格", "第一罐 $x$ 元，第二罐 $x-10$ 元，第二罐較便宜。"], ["列式", "結帳 $=x+0.7(x-10)$，選 (D)。"]], "tr": "(A) 是把 $10$ 元放在 7 折外面，只有便宜那罐的「全部價格」才打折。"}, {"id": "113B-12", "y": 113, "p": "B", "no": 12, "ch": "B09", "img": "img/tc/113B_12.webp", "a": 1, "t": "不等式的整數解個數", "c": "兩者都要買 ⇒ $x\\ge1$、$y\\ge1$；依序固定 $x$ 數 $y$ 的可能。", "st": [["列條件", "$20x+12y\\le70$，$x,y$ 為正整數。"], ["逐一數", "$x=1$：$12y\\le50$，$y=1\\sim4$ 共 $4$ 種；$x=2$：$12y\\le30$，$y=1,2$ 共 $2$ 種；$x=3$：$12y\\le10$，不行。"], ["加總", "$4+2=6$ 種，選 (B)。"]], "tr": "把 $x=0$ 或 $y=0$ 也算進去；題目說兩者都要買。"}, {"id": "113B-13", "y": 113, "p": "B", "no": 13, "ch": "B07", "img": "img/tc/113B_13.webp", "a": 3, "t": "等差數列：中間項×項數", "c": "奇數項的等差數列，總和 = 中間那項 × 項數。", "st": [["找中間項", "$11$ 項的中間是第 $6$ 項，$a_6=88$。"], ["求總和", "$S_{11}=11\\times a_6=11\\times88=968$，選 (D)。"]], "tr": "想求首項和公差卻發現條件不夠；其實不需要。"}, {"id": "113B-14", "y": 113, "p": "B", "no": 14, "ch": "B04", "img": "img/tc/113B_14.webp", "a": 2, "t": "弧長公式", "c": "弧長 $=r\\theta$（$\\theta$ 用弧度），一趟要走去再走回來 = 兩倍弧長。", "st": [["算弧長", "$240^{\\circ}=\\frac{4\\pi}{3}$，弧長 $=100\\times\\frac{4\\pi}{3}\\approx418.9$ 公尺。"], ["一趟的距離", "來回 $\\approx837.8$ 公尺。"], ["求最少趟數", "$8000\\div837.8\\approx9.55$，要超過 $8$ 公里至少 $10$ 趟，選 (C)。"]], "tr": "忘了「一趟」包含折返，只算單程得 $20$ 趟。"}, {"id": "113B-15", "y": 113, "p": "B", "no": 15, "ch": "B12", "img": "img/tc/113B_15.webp", "a": 1, "t": "乘法原理＋組合", "c": "先選湯底、再選配料，分步驟就相乘；配料不分順序用組合。", "st": [["選湯底", "$3$ 種。"], ["選配料", "$5$ 種選 $2$ 種：$C^5_2=10$。"], ["相乘", "$3\\times10=30$，選 (B)。"]], "tr": "配料用排列 $P^5_2=20$ 算，多算了順序。"}, {"id": "113B-16", "y": 113, "p": "B", "no": 16, "ch": "B06", "img": "img/tc/113B_16.webp", "a": 0, "t": "平行線距離＝正方形邊長", "c": "$AD$ 垂直兩條平行線，所以正方形邊長就是兩平行線的距離。", "st": [["平行線距離公式", "$d=\\frac{|c_1-c_2|}{\\sqrt{a^2+b^2}}=\\frac{|-6-(-11)|}{\\sqrt{3^2+4^2}}=\\frac55=1$"], ["結論", "邊長 $=1$，選 (A)。"]], "tr": "距離公式分母要開根號：$\\sqrt{9+16}=5$，不是 $25$。"}, {"id": "113B-17", "y": 113, "p": "B", "no": 17, "ch": "B01", "img": "img/tc/113B_17.webp", "a": 1, "t": "拋物線開口與 a 的關係", "c": "$y=ax^2$：$a\\gt 0$ 開口向上、$a\\lt 0$ 向下；$|a|$ 越大開口越窄。", "st": [["判斷 c", "頂點 $(0,-1)$ 那條開口向下 ⇒ $c\\lt 0$。"], ["比較 a、b", "頂點 $(0,1)$ 那條比過原點那條更窄，兩者都向上 ⇒ $a\\gt b\\gt 0$。"], ["結論", "$a\\gt b\\gt c$，選 (B)。"]], "tr": "以為開口越大 $a$ 越大，剛好相反。"}, {"id": "113B-18", "y": 113, "p": "B", "no": 18, "ch": "B11", "img": "img/tc/113B_18.webp", "a": 2, "t": "餘弦定理求第三邊", "c": "已知兩邊和夾角，用餘弦定理 $c^2=a^2+b^2-2ab\\cos C$。", "st": [["求 BC", "$\\overline{BC}^2=300^2+800^2-2\\cdot300\\cdot800\\cdot\\cos60^{\\circ}=90000+640000-240000=490000$，$\\overline{BC}=700$。"], ["比較路線", "繞路 $800+700=1500$，原規劃 $300$，多走 $1500-300=1200$ 公尺，選 (C)。"]], "tr": "算出 $BC=700$ 就直接選 (A)，題目問的是「多走多少」。"}, {"id": "113B-19", "y": 113, "p": "B", "no": 19, "ch": "B06", "img": "img/tc/113B_19.webp", "a": 0, "t": "圓在帶狀區域內", "c": "圓完全在區域內 ⇔ 圓心在區域內，且圓心到兩條邊界的距離都 $\\ge$ 半徑。", "st": [["先看圓心", "代 $5x+12y$：(A) $-10+12=2$；(B) $17\\gt 16$ 圓心就在外面 ✗；(C) $0$；(D) $15-24=-9$。"], ["算到邊界距離", "分母 $\\sqrt{5^2+12^2}=13$。(C) 到 $-12$ 的線 $\\frac{12}{13}\\lt 1$ ✗；(D) 到 $-12$ 的線 $\\frac{3}{13}\\lt 1$ ✗。"], ["檢查 (A)", "到上界 $\\frac{|2-16|}{13}=\\frac{14}{13}\\ge1$，到下界 $\\frac{|2+12|}{13}=\\frac{14}{13}\\ge1$ ✓，選 (A)。"]], "tr": "只確認圓心在區域內就選 (C)，忘了半徑會超出邊界。"}, {"id": "113B-20", "y": 113, "p": "B", "no": 20, "ch": "B05", "img": "img/tc/113B_20.webp", "a": 2, "t": "向量加法：首尾相接", "c": "$\\overrightarrow{AB}+\\overrightarrow{BC}=\\overrightarrow{AC}$，只看起點 $A$ 和終點 $C$。", "st": [["化簡", "$\\overrightarrow{AB}+\\overrightarrow{BC}=\\overrightarrow{AC}$：從文創園區指向博物館，方向「往左下」。"], ["比對選項", "(A) 往左偏上；(B) 往右上；(D) 幾乎向正下；(C) 購物中心 → 東夜市 也是往左下，長度也差不多。"], ["結論", "與 $\\overrightarrow{AC}$ 最接近的是購物中心 → 東夜市，選 (C)。"]], "tr": "被 $B$ 點誤導去找經過公園的路線；加起來只剩起點和終點。"}, {"id": "113B-21", "y": 113, "p": "B", "no": 21, "ch": "B13", "img": "img/tc/113B_21.webp", "a": 3, "t": "資料平移：平均變、標準差不變", "c": "每筆資料都加上同一個數，平均數跟著加，分散程度（標準差）不變。", "st": [["平均數", "$x=47500+5000=52500\\gt 47500$。"], ["標準差", "大家一起加 $5000$，彼此差距不變，$y=3000$，選 (D)。"]], "tr": "以為加薪後標準差也會變大。"}, {"id": "113B-22", "y": 113, "p": "B", "no": 22, "ch": "B13", "img": "img/tc/113B_22.webp", "a": 2, "t": "條件機率：縮小樣本空間", "c": "「在點數和為 9 或 10 的條件下」⇒ 只在這些情況裡數。", "st": [["列出條件內的情況", "和為 $9$：$(3,6),(4,5),(5,4),(6,3)$；和為 $10$：$(4,6),(5,5),(6,4)$，共 $7$ 種。"], ["小慈勝", "小慈點數較大（寫在前面）：$(5,4),(6,3),(6,4)$ 共 $3$ 種。"], ["機率", "$\\frac{3}{7}$，選 (C)。"]], "tr": "分母用 $36$ 去算，沒有縮小到條件內的 $7$ 種。"}, {"id": "113B-23", "y": 113, "p": "B", "no": 23, "ch": "B12", "img": "img/tc/113B_23.webp", "a": 1, "t": "不相鄰：全部減相鄰", "c": "不相鄰 = 全部排法 − 相鄰排法（相鄰用綑綁法）。", "st": [["全部排法", "$6!=720$。"], ["兩者相鄰", "綁成一包：$5!\\times2!=240$。"], ["相減", "$720-240=480$，選 (B)。"]], "tr": "綑綁後忘了乘 $2!$，算成 $720-120=600$。"}, {"id": "113B-24", "y": 113, "p": "B", "no": 24, "ch": "B09", "img": "img/tc/113B_24.webp", "a": 0, "t": "線性規劃求最大利潤", "c": "列出限制條件畫可行解區域，最大值會出現在頂點上。", "st": [["列條件", "$x+y\\le28$，$100x+120y\\le3000$（即 $5x+6y\\le150$），$x,y\\ge0$；利潤 $P=80x+90y$。"], ["找頂點", "兩線交點：$x+y=28$、$5x+6y=150$ ⇒ $y=10$、$x=18$。其他頂點 $(28,0)$、$(0,25)$、$(0,0)$。"], ["代入比較", "$(28,0)$：$2240$；$(0,25)$：$2250$；$(18,10)$：$1440+900=2340$。最大 $2340$，選 (A)。"]], "tr": "只比較只做單一口味的情形，漏掉交點。"}, {"id": "113B-25", "y": 113, "p": "B", "no": 25, "ch": "B10", "img": "img/tc/113B_25.webp", "a": 2, "t": "log 調分：逐項驗證", "c": "直接代入 $50\\log x$ 再取整數部分，用 $\\log2\\approx0.3010$ 計算。", "st": [["(A)(B)", "$50\\log100=100$ 不變 ✓；$50\\log10=50\\lt 60$ ✓。"], ["(C)", "最低 $2$ 分：$50\\log2\\approx15.05$，取整數部分是 $15$ 不是 $16$ ✗。"], ["(D) 與結論", "$50\\log16=200\\log2\\approx60.2$，取整數 $60$ ✓。錯誤的敘述是 (C)，選 (C)。"]], "tr": "把 $15.05$ 四捨五入或無條件進位成 $16$；題目是取整數部分。"}, {"id": "113C-1", "y": 113, "p": "C", "no": 1, "ch": "C04", "img": "img/tc/113C_1.webp", "a": 3, "t": "部分分式：代特殊值", "c": "兩邊通分後分子相等，代入讓某個括號變 $0$ 的 $x$ 值，就能一個個求出係數。", "st": [["通分比較分子", "$5=A(x-2)+B(2x+1)$。"], ["代特殊值", "$x=2$：$5=5B \\Rightarrow B=1$；$x=-\\frac12$：$5=-\\frac52A \\Rightarrow A=-2$。"], ["求值", "$3A+2B=-6+2=-4$，選 (D)。"]], "tr": "代 $x=-\\frac12$ 時 $x-2=-\\frac52$，負號漏掉會得 $A=2$。"}, {"id": "113C-2", "y": 113, "p": "C", "no": 2, "ch": "C01", "img": "img/tc/113C_2.webp", "a": 2, "t": "垂直線的斜角", "c": "兩直線垂直，斜角相差 $90^{\\circ}$。", "st": [["看圖", "$L_2$ 往右下傾斜，斜角是鈍角。"], ["計算", "$35^{\\circ}+90^{\\circ}=125^{\\circ}$，選 (C)。"]], "tr": "用 $90^{\\circ}-35^{\\circ}=55^{\\circ}$，那是 $L_2$ 與 $x$ 軸的銳夾角，不是斜角。"}, {"id": "113C-3", "y": 113, "p": "C", "no": 3, "ch": "C02", "img": "img/tc/113C_3.webp", "a": 2, "t": "同界角化簡", "c": "角度加減 $360^{\\circ}$ 的整數倍，三角函數值不變。", "st": [["減去整圈", "$2024^{\\circ}-5\\times360^{\\circ}=2024^{\\circ}-1800^{\\circ}=224^{\\circ}$。"], ["對照範圍", "$224^{\\circ}$ 恰在 $180^{\\circ}\\sim270^{\\circ}$ 內，$\\theta=224^{\\circ}$，選 (C)。"]], "tr": "減成 $2024-2160=-136^{\\circ}$ 後不知道怎麼轉回範圍內。"}, {"id": "113C-4", "y": 113, "p": "C", "no": 4, "ch": "C05", "img": "img/tc/113C_4.webp", "a": 0, "t": "圓與直線相切：點到線距離", "c": "相切 ⇔ 圓心到直線的距離 = 半徑。", "st": [["直線化成一般式", "$y=x-5 \\Rightarrow x-y-5=0$。"], ["點到直線距離", "$r=\\frac{|3-(-4)-5|}{\\sqrt{1^2+1^2}}=\\frac{2}{\\sqrt2}=\\sqrt2$，選 (A)。"]], "tr": "$-y$ 代入 $y=-4$ 要變 $+4$，符號錯會得 $|3-4-5|=6$。"}, {"id": "113C-5", "y": 113, "p": "C", "no": 5, "ch": "C11", "img": "img/tc/113C_5.webp", "a": 2, "t": "增廣矩陣的列運算", "c": "列運算有三種：兩列互換、某列乘非零常數、某列的倍數加到另一列；每次都要整列（含常數項）一起動。", "st": [["逐一檢查", "(A) 第一列乘 $2$ 應為 $[2\\ -2\\,|\\,8]$，常數沒乘 ✗。(B) $R_2-2R_1$ 應為 $[0\\ 5\\,|\\,-5]$ ✗。"], ["(C)", "$R_1$ 加到 $R_2$：$[2+1\\ \\ 3-1\\,|\\,3+4]=[3\\ 2\\,|\\,7]$ ✓。"], ["(D) 與結論", "兩列互換後第二列常數應是 $4$ 不是 $-4$ ✗。選 (C)。"]], "tr": "做列運算時忘了常數項那一欄也要一起算。"}, {"id": "113C-6", "y": 113, "p": "C", "no": 6, "ch": "C02", "img": "img/tc/113C_6.webp", "a": 1, "t": "由正負判斷象限", "c": "把式子化成平方形式：平方一定正，剩下的那個函數決定正負。", "st": [["第一個條件", "$\\sin\\theta\\tan\\theta=\\frac{\\sin^2\\theta}{\\cos\\theta}\\lt 0 \\Rightarrow \\cos\\theta\\lt 0$。"], ["第二個條件", "$\\cos\\theta\\cot\\theta=\\frac{\\cos^2\\theta}{\\sin\\theta}\\gt 0 \\Rightarrow \\sin\\theta\\gt 0$。"], ["判斷象限", "$\\sin$ 正、$\\cos$ 負 ⇒ 第二象限，選 (B)。"]], "tr": "直接猜每個函數的正負，組合太多容易搞混；化成平方最快。"}, {"id": "113C-7", "y": 113, "p": "C", "no": 7, "ch": "C07", "img": "img/tc/113C_7.webp", "a": 2, "t": "選取＋相鄰排列", "c": "先選出要放的水果，再把要相鄰的兩個綁在一起排。", "st": [["先選水果", "香瓜、木瓜一定選，其餘 $4$ 種再選 $3$ 種：$C^4_3=4$。"], ["綑綁排列", "香瓜木瓜綁成一包，和另外 $3$ 顆共 $4$ 個單位排：$4!=24$；包內可交換 $2!$。"], ["相乘", "$4\\times24\\times2=192$，選 (C)。"]], "tr": "綁在一起的兩個自己還能交換，別忘了乘 $2!$。"}, {"id": "113C-8", "y": 113, "p": "C", "no": 8, "ch": "C04", "img": "img/tc/113C_8.webp", "a": 3, "t": "配方法求最大值", "c": "令 $t=a^2$，把 $a^2b$ 變成 $t$ 的二次函數，再配方。", "st": [["換成單一變數", "$a^2b=a^2(10-a^2)$，令 $t=a^2$（$0\\lt t\\lt 10$）：$t(10-t)=-t^2+10t$。"], ["配方", "$-(t-5)^2+25$，當 $t=5$ 時最大值 $25$（此時 $a=\\sqrt5$、$b=5$ 在第一象限 ✓）。"], ["結論", "選 (D)。"]], "tr": "忘了檢查 $t=5$ 時點真的在第一象限。"}, {"id": "113C-9", "y": 113, "p": "C", "no": 9, "ch": "C11", "img": "img/tc/113C_9.webp", "a": 0, "t": "二階反方陣", "c": "$\\begin{bmatrix}p\\&q\\\\r\\&s\\end{bmatrix}^{-1}=\\frac{1}{ps-qr}\\begin{bmatrix}s\\&-q\\\\-r\\&p\\end{bmatrix}$：主對角互換、副對角變號、除以行列式。", "st": [["寫出 A", "$A=\\begin{bmatrix}2\\&5\\\\3\\&8\\end{bmatrix}$，$\\det A=16-15=1$。"], ["求反方陣", "$A^{-1}=\\begin{bmatrix}8\\&-5\\\\-3\\&2\\end{bmatrix}$。"], ["加總", "$8-5-3+2=2$，選 (A)。"]], "tr": "副對角只變號不互換，別把主對角也變號。"}, {"id": "113C-10", "y": 113, "p": "C", "no": 10, "ch": "C01", "img": "img/tc/113C_10.webp", "a": 2, "t": "線性函數對應區間端點", "c": "線性函數把區間端點對應到端點，用兩個端點就能定出 $f(x)=mx+k$。", "st": [["看點的分布", "圖 (a) 最左點 $2$ 對到圖 (b) 最左 $4$；最右點 $5$ 對到 $13$（遞增）。"], ["求斜率", "$m=\\frac{13-4}{5-2}=3$，$f(x)=3x+k$，$f(2)=6+k=4 \\Rightarrow k=-2$。"], ["結論", "$f(x)=3x-2$，選 (C)。"]], "tr": "只驗證一個端點；例如 (A) $f(2)=8$ 就不對了，兩端都要對上。"}, {"id": "113C-11", "y": 113, "p": "C", "no": 11, "ch": "C14", "img": "img/tc/113C_11.webp", "a": 3, "t": "多項式微分比較係數", "c": "$\\frac{d}{dx}x^n=nx^{n-1}$，微分後和題目給的 $f'(x)$ 逐項比較係數。", "st": [["微分", "$f'(x)=4ax^3+2bx-2$。"], ["比較係數", "$4a=8\\Rightarrow a=2$；$2b=-6\\Rightarrow b=-3$；$d=-2$。"], ["用 f(1)=5", "$f(1)=2-3-2+c=5 \\Rightarrow c=8$；$a+b+c+d=2-3+8-2=5$，選 (D)。"]], "tr": "常數 $c$ 微分後消失，必須靠 $f(1)=5$ 才求得到。"}, {"id": "113C-12", "y": 113, "p": "C", "no": 12, "ch": "C04", "img": "img/tc/113C_12.webp", "a": 3, "t": "立方差公式", "c": "$(t-1)(t^2+t+1)=t^3-1$，先認出公式再代值。", "st": [["有理化", "$t=\\frac{1}{\\sqrt2+1}=\\sqrt2-1$。"], ["套立方差", "原式 $=t^3-1$。"], ["計算", "$(\\sqrt2-1)^3=2\\sqrt2-6+3\\sqrt2-1=5\\sqrt2-7$，原式 $=5\\sqrt2-8=-8+5\\sqrt2$，選 (D)。"]], "tr": "直接硬展開括號，計算量大又容易錯。"}, {"id": "113C-13", "y": 113, "p": "C", "no": 13, "ch": "C13", "img": "img/tc/113C_13.webp", "a": 0, "t": "拋物線正焦弦", "c": "$x^2=4cy$ 的焦點 $(0,c)$，正焦弦長 $=|4c|$。", "st": [["求 c", "正焦弦長 $4c=8 \\Rightarrow c=2$，焦點 $(0,2)$。"], ["三角形的底與高", "$\\overline{F_1F_2}$ 長 $8$，過焦點、高度＝頂點到焦點距離 $2$。"], ["面積", "$\\frac{8\\times2}{2}=8$，選 (A)。"]], "tr": "把正焦弦長當成 $2c$ 或 $c$，焦距算錯。"}, {"id": "113C-14", "y": 113, "p": "C", "no": 14, "ch": "C15", "img": "img/tc/113C_14.webp", "a": 1, "t": "分段函數的定積分", "c": "分段函數要在分段點切開，兩段分別積分再相加。", "st": [["第一段", "$\\int_0^1(\\sqrt x+1)dx=\\left[\\frac23x^{3/2}+x\\right]_0^1=\\frac23+1=\\frac53$。"], ["第二段", "$\\int_1^2(x^2+x)dx=\\left[\\frac{x^3}{3}+\\frac{x^2}{2}\\right]_1^2=\\frac73+\\frac32=\\frac{23}{6}$。"], ["相加", "$\\frac{10}{6}+\\frac{23}{6}=\\frac{33}{6}=\\frac{11}{2}$，選 (B)。"]], "tr": "$\\sqrt x=x^{1/2}$ 積分是 $\\frac23x^{3/2}$，不是 $\\frac12x^{1/2}$。"}, {"id": "113C-15", "y": 113, "p": "C", "no": 15, "ch": "C06", "img": "img/tc/113C_15.webp", "a": 3, "t": "數列極限：先通分", "c": "$\\infty-\\infty$ 不能直接算，先通分合併，再看最高次項係數比。", "st": [["通分", "分子 $(n^2-n)(n+2)-(n^2+3n)(n+1)=(n^3+n^2-2n)-(n^3+4n^2+3n)=-3n^2-5n$。"], ["看最高次", "分母 $(n+1)(n+2)=n^2+3n+2$，分子分母都是 $2$ 次。"], ["取極限", "係數比 $\\frac{-3}{1}=-3$，選 (D)。"]], "tr": "兩個分式各自趨近無限大就說答案是 $0$。"}, {"id": "113C-16", "y": 113, "p": "C", "no": 16, "ch": "C09", "img": "img/tc/113C_16.webp", "a": 1, "t": "對數運算判斷大小", "c": "$\\log(x^2y)=2\\log x+\\log y$，算出來的整數部分決定落在哪兩個 $10$ 的次方之間。", "st": [["取對數", "$\\log(x^2y)=2(-2.24)+9.28=4.8$。"], ["判斷區間", "$4\\lt 4.8\\lt 5$ ⇒ $10^4\\lt x^2y\\lt 10^5$，選 (B)。"]], "tr": "忘了 $x$ 平方要乘 $2$，算成 $7.04$。"}, {"id": "113C-17", "y": 113, "p": "C", "no": 17, "ch": "C08", "img": "img/tc/113C_17.webp", "a": 3, "t": "滾動輪子的高度函數", "c": "不打滑滾動時，前進距離 = 轉過的弧長，半徑 $1$ ⇒ $x=\\theta$；高度 $y=1-\\cos\\theta$。", "st": [["建立關係", "半徑 $1$ 滾動不打滑，前進 $x$ 就轉了 $\\theta=x$ 弧度；$A$ 點高度 $=1-\\cos x$。"], ["檢查關鍵點", "$x=0$：$y=0$（起點貼地）；$x=\\pi$：$y=2$（轉到最高點）；$x=2\\pi$：$y=0$。"], ["結論", "從 $0$ 升到 $2$ 再回到 $0$，選 (D)。"]], "tr": "以為圖從 $y=1$（圓心高度）開始；$A$ 一開始是貼地的。"}, {"id": "113C-18", "y": 113, "p": "C", "no": 18, "ch": "C02", "img": "img/tc/113C_18.webp", "a": 1, "t": "共軛複數＋二倍角", "c": "$a+bi$ 的共軛是 $a-bi$：實部相同、虛部相反。", "st": [["比較實部虛部", "$\\cos\\theta=-\\frac12$，$-\\frac{\\sqrt3}{2}=-\\sin\\theta \\Rightarrow \\sin\\theta=\\frac{\\sqrt3}{2}$。"], ["二倍角", "$\\sin2\\theta=2\\sin\\theta\\cos\\theta=2\\cdot\\frac{\\sqrt3}{2}\\cdot\\left(-\\frac12\\right)=-\\frac{\\sqrt3}{2}$，選 (B)。"]], "tr": "把共軛想成虛部相同，得 $\\sin\\theta=-\\frac{\\sqrt3}{2}$，就會誤選 (A) $\\frac{\\sqrt3}{2}$。"}, {"id": "113C-19", "y": 113, "p": "C", "no": 19, "ch": "C10", "img": "img/tc/113C_19.webp", "a": 2, "t": "空間向量的正射影", "c": "$\\overrightarrow{u}$ 在 $\\overrightarrow{v}$ 上的正射影 $=\\frac{\\overrightarrow{u}\\cdot\\overrightarrow{v}}{|\\overrightarrow{v}|^2}\\overrightarrow{v}$。", "st": [["寫出向量", "$\\overrightarrow{AC}=(4,-5,2)$，$\\overrightarrow{BC}=(1,-2,2)$。"], ["內積與長度", "$\\overrightarrow{AC}\\cdot\\overrightarrow{BC}=4+10+4=18$，$|\\overrightarrow{BC}|^2=1+4+4=9$。"], ["正射影", "$\\frac{18}{9}(1,-2,2)=(2,-4,4)$，選 (C)。"]], "tr": "分母用 $|\\overrightarrow{BC}|=3$ 而不是平方 $9$，算成 $(6,-12,12)$。"}, {"id": "113C-20", "y": 113, "p": "C", "no": 20, "ch": "C06", "img": "img/tc/113C_20.webp", "a": 1, "t": "火柴棒金字塔：級數", "c": "往上指的小三角形第 $k$ 層有 $k$ 個，每個用 $3$ 根，所有火柴剛好都屬於某個向上三角形。", "st": [["找規律", "$n=1$：$3$ 根；$n=2$：$9$ 根；$n=3$：$18$ 根，即 $3(1+2+\\cdots+n)$。"], ["代入 n=50", "$3\\times\\frac{50\\times51}{2}=3\\times1275=3825$，選 (B)。"]], "tr": "把向下的小三角形也算進去重複數邊。"}, {"id": "113C-21", "y": 113, "p": "C", "no": 21, "ch": "C12", "img": "img/tc/113C_21.webp", "a": 0, "t": "三角形區域的不等式", "c": "先求三邊直線，再把「第三個頂點」代入，看要取 $\\ge$ 還是 $\\le$。", "st": [["三邊直線", "$AB$：$x+y-1=0$；$BC$：$x-y+3=0$；$AC$：$x-3y+15=0$。"], ["代對面頂點", "$C$ 代入 $x+y-1$：$8\\ge0$；$A$ 代入 $x-y+3$：$-4\\le0$；$B$ 代入 $x-3y+15$：$8\\ge0$。"], ["結論", "$x-y+3\\le0$、$x+y-1\\ge0$、$x-3y+15\\ge0$，選 (A)。"]], "tr": "代入的點用錯（要用不在那條線上的頂點），正負就判斷反了。"}, {"id": "113C-22", "y": 113, "p": "C", "no": 22, "ch": "C09", "img": "img/tc/113C_22.webp", "a": 2, "t": "指數方程：比值消係數", "c": "兩棟相除，常數 $0.085$ 會消掉，只剩高度比的 $\\frac34$ 次方。", "st": [["相除", "$\\frac{T_A}{T_B}=\\left(\\frac{h_A}{100}\\right)^{3/4}=2$。"], ["兩邊 4/3 次方", "$\\frac{h_A}{100}=2^{4/3}=2\\sqrt[3]{2}\\approx2\\times1.26=2.52$。"], ["結論", "$h_A\\approx252$ 公尺，選 (C)。"]], "tr": "以為週期 2 倍高度也 2 倍，選 $200$ 附近。"}, {"id": "113C-23", "y": 113, "p": "C", "no": 23, "ch": "C14", "img": "img/tc/113C_23.webp", "a": 0, "t": "極限存在但不連續", "c": "連續要三條件：$f(1)$ 有定義、極限存在、兩者相等。", "st": [["(A)", "$\\frac{x^2-1}{x-1}=x+1$（$x\\ne1$），極限為 $2$；但 $f(1)$ 無定義 ⇒ 不連續。"], ["其他選項", "(B) 極限不存在（趨近無限大）；(C) 左極限 $-1$、右極限 $1$ 不存在；(D) 多項式處處連續。"], ["結論", "選 (A)。"]], "tr": "以為「分母為 $0$」就一定沒有極限；可以先約分。"}, {"id": "113C-24", "y": 113, "p": "C", "no": 24, "ch": "C10", "img": "img/tc/113C_24.webp", "a": 0, "t": "空間最短路徑：鏡射", "c": "$A$、$B$ 在 $xy$ 平面同側，把 $A$ 對平面鏡射，連 $A'B$ 與平面的交點就是 $P$。", "st": [["鏡射", "$A(1,3,4)$ 對 $xy$ 平面鏡射為 $A'(1,3,-4)$。"], ["參數式", "$\\overrightarrow{A'B}=(2,-1,8)$，$A'B$ 上的點 $(1+2s,\\ 3-s,\\ -4+8s)$。"], ["求交點", "令 $z=0$：$s=\\frac12$，$P=\\left(2,\\frac52,0\\right)$，選 (A)。"]], "tr": "本題 $A$、$B$ 一樣高，$P$ 剛好在兩點投影的中點；兩點高度不同時就不是中點，一定要用鏡射法。"}, {"id": "113C-25", "y": 113, "p": "C", "no": 25, "ch": "C03", "img": "img/tc/113C_25.webp", "a": 1, "t": "向量參數式的線段長", "c": "$\\overrightarrow{OP}=\\overrightarrow{OB}+t\\overrightarrow{OA}$ 是以 $B$ 為起點、方向 $\\overrightarrow{OA}$ 的線段。", "st": [["兩端點", "$t=1$：$P=(-1,3)$；$t=-1$：$P=(-5,1)$。"], ["線段長", "兩端點差 $2\\overrightarrow{OA}=(4,2)$，長度 $=2\\sqrt{2^2+1^2}=2\\sqrt5$，選 (B)。"]], "tr": "只算 $|\\overrightarrow{OA}|=\\sqrt5$，忘了 $t$ 範圍長度是 $2$。"}, {"id": "114A-1", "y": 114, "p": "A", "no": 1, "ch": "A04", "img": "img/tc/114A_1.webp", "a": 2, "t": "特別角：sin 45°", "c": "$45^{\\circ}$ 的直角三角形是等腰直角三角形，三邊比 $1:1:\\sqrt{2}$。", "st": [["畫等腰直角三角形", "兩股都是 $1$，斜邊是 $\\sqrt{2}$。"], ["對邊比斜邊", "$\\sin 45^{\\circ}=\\dfrac{1}{\\sqrt{2}}$（也就是 $\\dfrac{\\sqrt{2}}{2}$），選 (C)。"]], "tr": "$\\frac{1}{2}$ 是 $\\sin 30^{\\circ}$，$\\frac{\\sqrt{3}}{2}$ 是 $\\sin 60^{\\circ}$，別記混。"}, {"id": "114A-2", "y": 114, "p": "A", "no": 2, "ch": "A07", "img": "img/tc/114A_2.webp", "a": 0, "t": "兩個一次不等式解相同", "c": "先把第一個不等式解出來，再讓第二個不等式的解長得一模一樣。", "st": [["解第一個不等式", "$4x-5\\lt 4+x \\Rightarrow 3x\\lt 9 \\Rightarrow x\\lt 3$。"], ["解第二個不等式", "$5-x\\gt a \\Rightarrow x\\lt 5-a$。"], ["讓兩個解相同", "$5-a=3$，得 $a=2$，選 (A)。"]], "tr": "移項時 $-x\\gt a-5$ 要變號成 $x\\lt 5-a$，不等號方向別忘了翻。"}, {"id": "114A-3", "y": 114, "p": "A", "no": 3, "ch": "A06", "img": "img/tc/114A_3.webp", "a": 1, "t": "等比中項", "c": "等比數列中，$a_5$ 夾在 $a_4$、$a_6$ 中間，所以 $a_5^2=a_4\\times a_6$。", "st": [["用等比中項", "$a_5^2=8\\times18=144$，$a_5=\\pm12$。"], ["看條件取正", "題目說 $a_5\\gt 0$，所以 $a_5=12$，選 (B)。"]], "tr": "$a_5^2=144$ 有正負兩解，要用 $a_5\\gt 0$ 篩掉 $-12$。"}, {"id": "114A-4", "y": 114, "p": "A", "no": 4, "ch": "A09", "img": "img/tc/114A_4.webp", "a": 3, "t": "組合數的比值", "c": "$C^{N}_{4}$ 和 $C^{N}_{3}$ 只差一個因式：$C^{N}_{4}=C^{N}_{3}\\times\\dfrac{N-3}{4}$。", "st": [["令 N=n+1", "$C^{N}_{4}=\\dfrac{N(N-1)(N-2)(N-3)}{4!}$，$C^{N}_{3}=\\dfrac{N(N-1)(N-2)}{3!}$，相除得 $\\dfrac{C^{N}_{4}}{C^{N}_{3}}=\\dfrac{N-3}{4}$。"], ["代入條件", "$4\\times C^{N}_{4}=11\\times C^{N}_{3} \\Rightarrow 4\\times\\dfrac{N-3}{4}=11 \\Rightarrow N-3=11$。"], ["換回 n", "$N=14$，所以 $n=13$，選 (D)。"]], "tr": "算出 $N=14$ 就直接選，忘了 $N=n+1$ 還要減 1。"}, {"id": "114A-5", "y": 114, "p": "A", "no": 5, "ch": "A01", "img": "img/tc/114A_5.webp", "a": 0, "t": "二次函數的最高點（頂點）", "c": "開口向下的拋物線，最高點就是頂點，$x=-\\dfrac{b}{2a}$。", "st": [["找頂點 x 坐標", "$f(x)=-x^2+8x+9$，$x=-\\dfrac{8}{2\\times(-1)}=4$，在 $-1\\le x\\le9$ 範圍內。"], ["代回求高度", "$f(4)=-16+32+9=25$，最高點 $(4,25)$，選 (A)。"]], "tr": "$(9,0)$、$(0,9)$ 只是端點或截距，不是最高點。"}, {"id": "114A-6", "y": 114, "p": "A", "no": 6, "ch": "A07", "img": "img/tc/114A_6.webp", "a": 2, "t": "列不等式：至少就是 ≥", "c": "小卡車載 $3x$ 噸、大卡車載 $6y$ 噸，「至少 7200」要用 $\\ge$。", "st": [["算總載量", "$x$ 台小卡車載 $3x$ 噸，$y$ 台大卡車載 $6y$ 噸，合計 $3x+6y$。"], ["翻譯「至少」", "至少 7200 噸 $\\Rightarrow 3x+6y\\ge7200$，選 (C)。"]], "tr": "係數別對調：$x$ 是小卡車，配的是 3 噸。"}, {"id": "114A-7", "y": 114, "p": "A", "no": 7, "ch": "A09", "img": "img/tc/114A_7.webp", "a": 2, "t": "兩骰點數和為 4 的倍數", "c": "點數和只能是 2～12，4 的倍數只有 4、8、12，分開數再相加。", "st": [["和為 4", "$(1,3),(2,2),(3,1)$：3 種。"], ["和為 8", "$(2,6),(3,5),(4,4),(5,3),(6,2)$：5 種。"], ["和為 12", "$(6,6)$：1 種。合計 $3+5+1=9$ 種，選 (C)。"]], "tr": "$(1,3)$ 和 $(3,1)$ 是第一次、第二次不同，要算兩種。"}, {"id": "114A-8", "y": 114, "p": "A", "no": 8, "ch": "A10", "img": "img/tc/114A_8.webp", "a": 1, "t": "古典機率：任取兩數皆質數", "c": "機率＝有利的取法 ÷ 全部取法，兩邊都用組合數 $C$。", "st": [["全部取法", "30 個數取 2 個：$C^{30}_{2}=435$。"], ["兩數都是質數", "10 個質數取 2 個：$C^{10}_{2}=45$。"], ["相除", "$\\dfrac{45}{435}=\\dfrac{3}{29}$，選 (B)。"]], "tr": "分子分母要一致：都用組合（不排順序），別一邊用排列。"}, {"id": "114A-9", "y": 114, "p": "A", "no": 9, "ch": "A02", "img": "img/tc/114A_9.webp", "a": 3, "t": "兩點斜率公式", "c": "斜率 $m=\\dfrac{y_2-y_1}{x_2-x_1}$，把 $m_1$、$m_2$ 都用 $a$ 表示再列方程式。", "st": [["寫出兩個斜率", "$m_1=\\dfrac{a-3}{4-2}=\\dfrac{a-3}{2}$，$m_2=\\dfrac{a-7}{4-5}=7-a$。"], ["代入 m₂=−m₁", "$7-a=-\\dfrac{a-3}{2} \\Rightarrow 14-2a=-a+3 \\Rightarrow a=11$，選 (D)。"]], "tr": "$m_2$ 的分母 $4-5=-1$，記得變號。"}, {"id": "114A-10", "y": 114, "p": "A", "no": 10, "ch": "A02", "img": "img/tc/114A_10.webp", "a": 3, "t": "點到直線的距離", "c": "最短路線是垂直走到直線，長度用點到直線距離公式。", "st": [["代公式", "$d=\\dfrac{|4(-3)-3(5)-13|}{\\sqrt{4^2+3^2}}=\\dfrac{|-40|}{5}$。"], ["算出答案", "$d=8$ 公尺，選 (D)。"]], "tr": "分子要加絕對值，分母是 $\\sqrt{a^2+b^2}=5$ 不是 $a+b$。"}, {"id": "114A-11", "y": 114, "p": "A", "no": 11, "ch": "A03", "img": "img/tc/114A_11.webp", "a": 0, "t": "多項式函數值求係數", "c": "$f(0)$ 就是常數項；再用 $f(1)=0$ 求 $b$。", "st": [["用 f(0)=0", "$f(0)=c=0$。"], ["用 f(1)=0", "$1+2+b+0=0 \\Rightarrow b=-3$。"], ["相減", "$b-c=-3-0=-3$，選 (A)。"]], "tr": ""}, {"id": "114A-12", "y": 114, "p": "A", "no": 12, "ch": "A01", "img": "img/tc/114A_12.webp", "a": 0, "t": "里程與通行費（一次函數）", "c": "行駛里程＝通行費 ÷ 每公里費率；往北走里程數變小。", "st": [["算行駛里程", "$84\\div0.9\\approx93.3$ 公里。"], ["往北要減", "里程由北往南遞增，往北開數字變小：$x\\approx192-93.3=98.7$。"], ["選最接近", "最接近 99，選 (A)。"]], "tr": "往北是減，不是加；加的話會誤選 285。"}, {"id": "114A-13", "y": 114, "p": "A", "no": 13, "ch": "A10", "img": "img/tc/114A_13.webp", "a": 1, "t": "期望值：保費減理賠", "c": "保險公司每張保單收 500 元，再扣掉「理賠金額 × 發生機率」。", "st": [["理賠的期望支出", "$0.03\\%=0.0003$，$1000000\\times0.0003=300$ 元。"], ["獲利期望值", "$500-300=200$ 元，選 (B)。"]], "tr": "$0.03\\%$ 是 $0.0003$，不是 $0.03$。"}, {"id": "114A-14", "y": 114, "p": "A", "no": 14, "ch": "A10", "img": "img/tc/114A_14.webp", "a": 3, "t": "資料線性變換的平均與標準差", "c": "$y=ax+b$ 時，平均數跟著 $a\\mu+b$，標準差只乘 $|a|$、加的常數不影響。", "st": [["新平均數", "$0.7\\times50+30=65$。"], ["新標準差", "$|0.7|\\times10=7$（加 30 只是整體平移，分散程度不變）。"], ["結論", "平均 65、標準差 7，選 (D)。"]], "tr": "以為標準差也要加 30，或以為完全不變。"}, {"id": "114A-15", "y": 114, "p": "A", "no": 15, "ch": "A09", "img": "img/tc/114A_15.webp", "a": 1, "t": "取捨原理：都不及格", "c": "至少一科及格 ＝ 數學 ＋ 英文 − 兩科都及格；剩下的就是都不及格。", "st": [["至少一科及格", "$70\\%+60\\%-45\\%=85\\%$。"], ["都不及格", "$1-85\\%=15\\%$，$60\\times15\\%=9$ 位，選 (B)。"]], "tr": "直接用 $100\\%-70\\%-60\\%$ 會得負數，重疊部分要先扣回來。"}, {"id": "114A-16", "y": 114, "p": "A", "no": 16, "ch": "A09", "img": "img/tc/114A_16.webp", "a": 2, "t": "排四位數：5 的倍數分個位討論", "c": "5 的倍數個位是 0 或 5；個位是 5 時千位不能放 0，要分開算。", "st": [["個位是 0", "剩 6 個數字排前三位：$P^{6}_{3}=120$ 個。"], ["個位是 5", "千位不能是 0 也不能是 5：5 種；中間兩位從剩下 5 個排：$P^{5}_{2}=20$。共 $5\\times20=100$ 個。"], ["相加", "$120+100=220$ 個，選 (C)。"]], "tr": "個位放 5 時忘了千位不能是 0，會多算。"}, {"id": "114A-17", "y": 114, "p": "A", "no": 17, "ch": "A06", "img": "img/tc/114A_17.webp", "a": 2, "t": "等差數列：首末項和", "c": "五項等差數列的中間項是平均數，首項＋末項＝ 2 × 中間項。", "st": [["求中間項", "$900\\div5=180$ 公分。"], ["首末相加", "最高＋最矮 $=2\\times180=360$ 公分，選 (C)。"]], "tr": "不用求公差，也求不出來；題目只問「和」。"}, {"id": "114A-18", "y": 114, "p": "A", "no": 18, "ch": "A04", "img": "img/tc/114A_18.webp", "a": 0, "t": "正弦函數圖形判讀", "c": "$y=2\\sin x+1$：振幅 2、週期 $2\\pi$、上下移 1，所以最大 3、最小 $-1$，過 $(0,1)$ 往上走。", "st": [["抓三個特徵", "週期 $2\\pi$（$-2\\pi$～$2\\pi$ 剛好兩個波）；最大值 $3$、最小值 $-1$；$x=0$ 時 $y=1$ 且往上升。"], ["刪去法", "(B) 週期太短；(C) 振幅太小、最低點在 $x$ 軸上方；(D) 最低點落在 0 附近、通過 $(0,1)$ 時位置不對。"], ["結論", "(A) 過 $(0,1)$、最低略低於 $x$ 軸（$-1$）、週期 $2\\pi$，選 (A)。"]], "tr": "把「$+1$」當成振幅，或把 $\\sin 2x$ 的圖（週期 $\\pi$）誤認。"}, {"id": "114A-19", "y": 114, "p": "A", "no": 19, "ch": "A05", "img": "img/tc/114A_19.webp", "a": 3, "t": "圓與 x 軸相切：r＝|圓心y坐標|", "c": "配方找圓心、半徑；和 $x$ 軸相切時，半徑等於圓心到 $x$ 軸的距離。", "st": [["配方", "$(x+2)^2+(y-3)^2=13-k$，圓心 $(-2,3)$，$r^2=13-k$。"], ["相切條件", "圓心到 $x$ 軸距離 $=3=r$，所以 $13-k=9$，$k=4$，選 (D)。"]], "tr": "和 $x$ 軸相切看的是 $y$ 坐標 3，不是 $x$ 坐標 2。"}, {"id": "114A-20", "y": 114, "p": "A", "no": 20, "ch": "A07", "img": "img/tc/114A_20.webp", "a": 1, "t": "線性規劃：頂點代入找最小", "c": "可行解區域是三角形，成本最小值一定出現在頂點。", "st": [["列目標函數", "成本 $=50x+36y$。"], ["代三個頂點", "$(6,12)$：$300+432=732$；$(6,20)$：$300+720=1020$；$(10,20)$：$500+720=1220$。"], ["取最小", "最低成本 732 元，選 (B)。"]], "tr": "葡萄是 $x$（50 元）、奶油是 $y$（36 元），別對調。"}, {"id": "114A-21", "y": 114, "p": "A", "no": 21, "ch": "A08", "img": "img/tc/114A_21.webp", "a": 2, "t": "同底對數比大小", "c": "底數 3 大於 1，真數越大對數越大；先把係數搬到真數。", "st": [["化成同樣形式", "$b=2\\log_3 5=\\log_3 25$。"], ["比真數", "$25\\gt 16\\gt 4$，所以 $b\\gt c\\gt a$，選 (C)。"]], "tr": "$2\\log_3 5$ 是 $\\log_3 25$，不是 $\\log_3 10$。"}, {"id": "114A-22", "y": 114, "p": "A", "no": 22, "ch": "A08", "img": "img/tc/114A_22.webp", "a": 3, "t": "單位換算與科學記號", "c": "先把兩個長度換成同一單位再相除。", "st": [["換成皮米", "1 nm $=10^{3}$ pm，所以 120 nm $=120000$ pm。"], ["相除", "$120000\\div280\\approx428.6$，最接近 400，選 (D)。"]], "tr": "nm 和 pm 差 $10^3$ 倍，別當成同單位直接 $120\\div280$。"}, {"id": "114A-23", "y": 114, "p": "A", "no": 23, "ch": "A08", "img": "img/tc/114A_23.webp", "a": 1, "t": "對數應用：地震規模", "c": "把能量取 $\\log$，$\\log 8.4=\\log(4\\times2.1)=2\\log2+\\log2.1$。", "st": [["算 log E", "$\\log(8.4\\times10^{13})=13+2(0.3010)+0.3222=13.9242$。"], ["代公式", "$M=\\dfrac{13.9242-4.8}{1.5}=\\dfrac{9.1242}{1.5}\\approx6.08$。"], ["選最接近", "約 6.1 級，選 (B)。"]], "tr": "$8.4$ 要拆成 $4\\times2.1$ 才能用給的參考數值。"}, {"id": "114A-24", "y": 114, "p": "A", "no": 24, "ch": "A03", "img": "img/tc/114A_24.webp", "a": 3, "t": "兩函數相等：解一元二次方程式", "c": "令 $f(x)=g(x)$，移項後因式分解。", "st": [["列方程式", "$10x+200=0.0025x^2+8x+200 \\Rightarrow 0.0025x^2-2x=0$。"], ["提公因式", "$x(0.0025x-2)=0$，$x=0$ 或 $x=800$。"], ["看範圍", "$0\\lt x\\lt 1000$，所以 $x=800$，選 (D)。"]], "tr": "兩邊直接除以 $x$ 前要確認 $x\\ne0$；$x=0$ 不在範圍內。"}, {"id": "114A-25", "y": 114, "p": "A", "no": 25, "ch": "A05", "img": "img/tc/114A_25.webp", "a": 0, "t": "圓心到三面牆的最短距離", "c": "圓心到三條直線的距離取最小的那個，再扣掉 2.5 公尺通道就是最大半徑。", "st": [["到三面牆的距離", "$L_1$：$\\dfrac{|12-12+24|}{5}=4.8$；$L_2$：$\\dfrac{|9+16-48|}{5}=4.6$；$L_3$（$y=0$）：$4$。"], ["取最小再扣通道", "最近的牆距離 4，$a=4-2.5=1.5$，選 (A)。"]], "tr": "要用「最近」的那面牆，不是最遠的。"}, {"id": "114B-1", "y": 114, "p": "B", "no": 1, "ch": "B03", "img": "img/tc/114B_1.webp", "a": 1, "t": "餘式定理", "c": "$f(x)$ 除以 $x-2$ 的餘式就是 $f(2)$。", "st": [["代 x=2", "$f(2)=2^n-4-3=2^n-7$。"], ["令餘式為 1", "$2^n-7=1 \\Rightarrow 2^n=8 \\Rightarrow n=3$，選 (B)。"]], "tr": ""}, {"id": "114B-2", "y": 114, "p": "B", "no": 2, "ch": "B04", "img": "img/tc/114B_2.webp", "a": 2, "t": "弧度角判斷象限", "c": "$\\theta=3.1$ 沒有度數符號，單位是弧度；和 $\\frac{\\pi}{2}\\approx1.57$、$\\pi\\approx3.14$ 比較。", "st": [["比大小", "$1.57\\lt 3.1\\lt 3.14$，即 $\\frac{\\pi}{2}\\lt \\theta\\lt \\pi$。"], ["結論", "落在第二象限，選 (C)。"]], "tr": "把 3.1 當成 $3.1^{\\circ}$ 會誤選第一象限。"}, {"id": "114B-3", "y": 114, "p": "B", "no": 3, "ch": "B05", "img": "img/tc/114B_3.webp", "a": 3, "t": "內積的最大值", "c": "內積 $=x_1x_2+y_1y_2$，寫成 $y$ 的一次式，看 $y$ 的範圍。", "st": [["算內積", "$\\overrightarrow{AB}\\cdot\\overrightarrow{AC}=2\\times3+3y=6+3y$。"], ["取最大", "$y$ 越大越大，$y=2$ 時為 $12$，選 (D)。"]], "tr": ""}, {"id": "114B-4", "y": 114, "p": "B", "no": 4, "ch": "B05", "img": "img/tc/114B_4.webp", "a": 0, "t": "向量加法的圖示", "c": "$\\overrightarrow{AB}+\\overrightarrow{BC}=\\overrightarrow{AC}$（頭尾相接）；平行四邊形的對邊向量相等，所以 $\\overrightarrow{PQ}$ 要和 $\\overrightarrow{AC}$ 平行同向等長。", "st": [["先看三角形", "$A\\to B\\to C$ 頭尾相接，和就是 $\\overrightarrow{AC}$，所以 $\\overrightarrow{AC}$ 必須是平行四邊形的一邊（三角形和平行四邊形共用的那條邊）。"], ["再看平行四邊形", "$\\overrightarrow{PQ}$ 要和 $\\overrightarrow{AC}$ 是對邊且方向相同：$P$ 在 $A$ 這一側、$Q$ 在 $C$ 這一側。"], ["對照選項", "(A) 中 $AC$ 是共用邊，$P\\to Q$ 和 $A\\to C$ 同向，選 (A)。"]], "tr": "(B) 的共用邊是 $AB$，$\\overrightarrow{PQ}=\\overrightarrow{AB}$，不是 $\\overrightarrow{AC}$。"}, {"id": "114B-5", "y": 114, "p": "B", "no": 5, "ch": "B01", "img": "img/tc/114B_5.webp", "a": 3, "t": "兩拋物線的交點", "c": "兩圖形交點：令 $f(x)=g(x)$，$x^2$ 會消掉。", "st": [["列方程式", "$x^2-2x-3=x^2-x-6 \\Rightarrow -x=-3 \\Rightarrow x=3$。"], ["代回求 y", "$f(3)=9-6-3=0$，交點 $(3,0)$，選 (D)。"]], "tr": "$(-1,0)$ 只在 $f$ 上，不在 $g$ 上，要兩個都代得進去。"}, {"id": "114B-6", "y": 114, "p": "B", "no": 6, "ch": "B01", "img": "img/tc/114B_6.webp", "a": 3, "t": "代值技巧：看出是 f(1/2)", "c": "$\\dfrac{a}{4}+\\dfrac{b}{2}+c$ 正是把 $x=\\dfrac12$ 代進 $ax^2+bx+c$。", "st": [["看出代值", "$a\\left(\\tfrac12\\right)^2+b\\left(\\tfrac12\\right)+c=\\dfrac{a}{4}+\\dfrac{b}{2}+c$。"], ["用配方式代 x=1/2", "$y=\\dfrac12\\left(\\dfrac12-\\dfrac12\\right)^2+\\dfrac18=\\dfrac18$，選 (D)。"]], "tr": "硬把 $a,b,c$ 展開算也行，但容易算錯；認出是 $f(\\tfrac12)$ 最快。"}, {"id": "114B-7", "y": 114, "p": "B", "no": 7, "ch": "B04", "img": "img/tc/114B_7.webp", "a": 3, "t": "餘角關係 sin²θ+cos²θ=1", "c": "$\\sin 80^{\\circ}=\\cos10^{\\circ}$、$\\sin70^{\\circ}=\\cos20^{\\circ}$，兩兩配對變成 1。", "st": [["配對", "$\\sin^2 10^{\\circ}+\\sin^2 80^{\\circ}=\\sin^2 10^{\\circ}+\\cos^2 10^{\\circ}=1$；$2(\\sin^2 20^{\\circ}+\\sin^2 70^{\\circ})=2$。"], ["中間項", "$4\\sin^2 30^{\\circ}=4\\times\\frac14=1$。"], ["相加", "$1+2+1=4$，選 (D)。"]], "tr": ""}, {"id": "114B-8", "y": 114, "p": "B", "no": 8, "ch": "B02", "img": "img/tc/114B_8.webp", "a": 0, "t": "平行線距離求直線", "c": "平行線係數相同只差常數，距離 $=\\dfrac{|c_1-c_2|}{\\sqrt{a^2+b^2}}$。", "st": [["化成一般式", "$\\dfrac{x}{5}-\\dfrac{y}{12}=1$ 乘 60：$12x-5y-60=0$。"], ["設平行線", "$L_1:12x-5y+c=0$，$\\dfrac{|c+60|}{13}=1 \\Rightarrow c=-47$ 或 $-73$。"], ["對照選項", "$12x-5y-47=0$ 即 $y=\\dfrac{12}{5}x-\\dfrac{47}{5}$，選 (A)。"]], "tr": "截距式 $\\frac{x}{5}-\\frac{y}{12}=1$ 化一般式後是 $12x-5y$，不是 $5x-12y$。"}, {"id": "114B-9", "y": 114, "p": "B", "no": 9, "ch": "B10", "img": "img/tc/114B_9.webp", "a": 2, "t": "單位換算與科學記號", "c": "先換成同一單位（公尺），再相除。", "st": [["換成公尺", "3 奈米 $=3\\times10^{-9}$ m；頭髮 $0.017$ mm $=1.7\\times10^{-5}$ m。"], ["相除", "$\\dfrac{3\\times10^{-9}}{1.7\\times10^{-5}}\\approx1.76\\times10^{-4}$，約 $1.8\\times10^{-4}$，選 (C)。"]], "tr": "問的是「3 奈米是頭髮的幾倍」，小的除以大的，答案小於 1。"}, {"id": "114B-10", "y": 114, "p": "B", "no": 10, "ch": "B09", "img": "img/tc/114B_10.webp", "a": 0, "t": "同一直線的兩個半平面", "c": "兩個不等式的邊界是同一條直線 $L$，所以方程式成比例；$x$ 係數為正時「$\\ge$」是右側。", "st": [["判斷方向", "$4x-3y+a\\ge0$ 的 $x$ 係數正，$\\ge$ 表示右側，符合。$8x+by+4\\le0$ 的 $x$ 係數正，$\\le$ 表示左側，也符合。"], ["比例", "兩式是同一條線：$8x+by+4=2(4x-3y+a)$，得 $b=-6$、$2a=4$，$a=2$。"], ["相加", "$a+b=2-6=-4$，選 (A)。"]], "tr": ""}, {"id": "114B-11", "y": 114, "p": "B", "no": 11, "ch": "B10", "img": "img/tc/114B_11.webp", "a": 1, "t": "對數換成指數", "c": "$\\log_{25}2=a$ 代表 $25^a=2$，也就是 $5^{2a}=2$，$5^a=\\sqrt2$。", "st": [["翻成指數", "$5^a=\\sqrt2$，同理 $5^b=\\sqrt3$。"], ["拆指數", "$5^{3a+2b+1}=(5^a)^3(5^b)^2\\cdot5=2\\sqrt2\\times3\\times5$。"], ["算出", "$=30\\sqrt2$，選 (B)。"]], "tr": "底數是 25 不是 5，$5^a$ 是 $\\sqrt2$ 而不是 2。"}, {"id": "114B-12", "y": 114, "p": "B", "no": 12, "ch": "B09", "img": "img/tc/114B_12.webp", "a": 1, "t": "不等式的整數解計數", "c": "對每個 $x$ 分別數 $y$ 的個數：$\\frac{x}{2}\\le y\\le x$。", "st": [["x=6", "$3\\le y\\le6$：4 種。"], ["x=7", "$3.5\\le y\\le7$，$y=4\\sim7$：4 種。"], ["x=8", "$4\\le y\\le8$：5 種。合計 $4+4+5=13$ 種，選 (B)。"]], "tr": "$x=7$ 時 $y$ 要大於等於 3.5，所以從 4 開始。"}, {"id": "114B-13", "y": 114, "p": "B", "no": 13, "ch": "B13", "img": "img/tc/114B_13.webp", "a": 1, "t": "中位數、全距、樣本標準差", "c": "5 筆排好的資料，中位數是第 3 個；樣本標準差分母是 $n-1$。", "st": [["求 α、β", "中位數 $\\alpha=6$；全距 $\\beta-3=9 \\Rightarrow \\beta=12$。檢查平均 $(3+4+6+10+12)/5=7$ 正確。"], ["求 γ", "離差 $-4,-3,-1,3,5$，平方和 $16+9+1+9+25=60$，$\\gamma=\\sqrt{\\dfrac{60}{4}}=\\sqrt{15}$。"], ["相加", "$6+12+\\sqrt{15}=18+\\sqrt{15}$，選 (B)。"]], "tr": "樣本標準差要除以 $n-1=4$，除以 5 會得 $\\sqrt{12}$。"}, {"id": "114B-14", "y": 114, "p": "B", "no": 14, "ch": "B13", "img": "img/tc/114B_14.webp", "a": 2, "t": "期望值：加權平均", "c": "期望值 ＝ 每種折扣 × 它的機率，全部相加。", "st": [["加權相加", "$\\dfrac{9\\times32+8\\times10+6\\times5+3\\times2+1\\times1}{50}=\\dfrac{405}{50}$。"], ["算出", "$=8.1$ 折，最接近 8 折，選 (C)。"]], "tr": "不能把五種折扣直接平均（$5.4$ 折），每種籤數不同。"}, {"id": "114B-15", "y": 114, "p": "B", "no": 15, "ch": "B07", "img": "img/tc/114B_15.webp", "a": 2, "t": "找規律：第 k 次按鍵的路徑", "c": "第 $k$ 次按 A：先在 $y=5-k$ 上往右走 3 格，再在 $x=1+3k$ 往下走 1 格。", "st": [["寫出路徑", "第 $k$ 次：橫線 $y=5-k$，$x$ 從 $3k-2$ 到 $3k+1$；直線 $x=3k+1$，$y$ 從 $5-k$ 到 $4-k$。"], ["逐一檢查", "$(5,3)$：$k=2$ 橫線 $y=3$、$x\\in[4,7]$ ✓；$(7,2)$：$k=2$ 直線 $x=7$、$y\\in[2,3]$ ✓；$(16,-1)$：$k=5$ 直線 $x=16$、$y\\in[-1,0]$ ✓。"], ["不會經過的點", "$y=0$ 的橫線是 $k=5$，$x$ 只在 $13\\sim16$，$(10,0)$ 不會經過，選 (C)。"]], "tr": "$x=10$ 時角色只在 $y=1\\sim2$ 之間往下走，不會到 $y=0$。"}, {"id": "114B-16", "y": 114, "p": "B", "no": 16, "ch": "B11", "img": "img/tc/114B_16.webp", "a": 1, "t": "餘弦定理求邊長", "c": "已知兩邊和夾角，用餘弦定理求第三邊 TN，而 TN 有 5 個間距。", "st": [["餘弦定理", "$TN^2=20^2+(20\\sqrt3)^2-2\\cdot20\\cdot20\\sqrt3\\cos30^{\\circ}=400+1200-1200=400$。"], ["求 x", "$TN=20$，T 到 N 有 5 段間距，$x=20\\div5=4$，選 (B)。"]], "tr": "6 個人只有 5 個間距，除以 6 就錯了。"}, {"id": "114B-17", "y": 114, "p": "B", "no": 17, "ch": "B12", "img": "img/tc/114B_17.webp", "a": 3, "t": "乘法原理＋組合", "c": "三個步驟依序選，彼此獨立，用乘法；海鮮選 3 種不排順序用 $C$。", "st": [["各步驟方法數", "肉盤 4 種；海鮮 $C^5_3=10$ 種；副餐 4 種。"], ["相乘", "$4\\times10\\times4=160$ 種，選 (D)。"]], "tr": "三步驟同時都要選，是「乘」不是「加」（加會得 18）。"}, {"id": "114B-18", "y": 114, "p": "B", "no": 18, "ch": "B08", "img": "img/tc/114B_18.webp", "a": 1, "t": "聯立方程式技巧＋根與係數", "c": "兩式係數交錯對稱，直接相加就能得到 $x+y$。", "st": [["兩式相加", "$100x+100y=2000 \\Rightarrow p+q=20$。"], ["兩根和", "$20x^2+20x-114=0$，兩根和 $=-\\dfrac{20}{20}=-1$，選 (B)。"]], "tr": "兩根和是 $-\\frac{b}{a}$，別忘了負號。"}, {"id": "114B-19", "y": 114, "p": "B", "no": 19, "ch": "B06", "img": "img/tc/114B_19.webp", "a": 2, "t": "圓與直線的位置關係", "c": "比較圓心到直線距離 $d$ 和半徑 $r$：$d\\gt r$ 相離、$d=r$ 相切、$d\\lt r$ 相割。", "st": [["先找和 C₂ 相切的", "$C_2$ 圓心 $(0,2)$、$r=2$。(C) $3x+4y+2=0$：$d=\\dfrac{|8+2|}{5}=2$，相切。"], ["檢查 C₁、C₃", "$C_1$ 圓心 $(0,1)$：$d=\\dfrac{6}{5}\\gt 1$ 相離；$C_3$ 圓心 $(0,3)$：$d=\\dfrac{14}{5}\\lt 3$ 相割。"], ["結論", "三個條件都符合，選 (C)。"]], "tr": ""}, {"id": "114B-20", "y": 114, "p": "B", "no": 20, "ch": "B02", "img": "img/tc/114B_20.webp", "a": 0, "t": "垂直斜率與截距正負", "c": "直角要由兩條垂直線構成（斜率乘積 $-1$）；$x$、$y$ 截距都負的直線斜率一定是負的。", "st": [["L₁、L₂ 不垂直", "$(-2)\\times\\frac13=-\\frac23\\ne-1$，所以直角在 $L_3$ 和其中一條之間。"], ["L₃ 的可能斜率", "垂直 $L_1$：$\\frac12$；垂直 $L_2$：$-3$。"], ["截距判斷", "過 $(-p,0)$、$(0,-q)$（$p,q\\gt 0$）的斜率 $=-\\frac{q}{p}\\lt 0$，所以取 $-3$，選 (A)。"]], "tr": ""}, {"id": "114B-21", "y": 114, "p": "B", "no": 21, "ch": "B12", "img": "img/tc/114B_21.webp", "a": 2, "t": "不相鄰：插空法", "c": "先排可以相鄰的，再把不能相鄰的插進空隙。", "st": [["先排其他 4 個", "鳳梨班、蘋果班共 4 個節目：$4!=24$。"], ["西瓜班插空", "4 個節目產生 5 個空隙，西瓜班 3 個節目排進去：$P^5_3=60$。"], ["相乘", "$24\\times60=1440$ 種，選 (C)。"]], "tr": "西瓜班 3 個節目不同，插空要用排列 $P$，用 $C$ 會少乘 $3!$。"}, {"id": "114B-22", "y": 114, "p": "B", "no": 22, "ch": "B09", "img": "img/tc/114B_22.webp", "a": 0, "t": "線性規劃：最少花費", "c": "列出布丁、奶酪兩個限制，最低花費出現在可行區域的頂點。", "st": [["列式", "A 買 $x$ 盒、B 買 $y$ 盒：$3x+2y\\ge48$、$3x+4y\\ge72$，花費 $200x+210y$。"], ["找頂點", "兩線交點：相減得 $2y=24$，$y=12$、$x=8$。其他頂點 $(0,24)$、$(24,0)$。"], ["代入比較", "$(8,12)$：$1600+2520=4120$；$(0,24)$：$5040$；$(24,0)$：$4800$。最低 4120 元，選 (A)。"]], "tr": ""}, {"id": "114B-23", "y": 114, "p": "B", "no": 23, "ch": "B04", "img": "img/tc/114B_23.webp", "a": 2, "t": "直角三角形與 tan 30°", "c": "長方形中 $\\triangle FDA$、$\\triangle TDA$ 都是直角三角形，先用 $\\tan30^{\\circ}$ 求 $DA$，再用畢氏定理。", "st": [["求 DA", "$AB=CD=40$，$AF=20$；$\\tan30^{\\circ}=\\dfrac{AF}{DA}$，$DA=20\\sqrt3$。"], ["求 AT", "$AT^2=TD^2-DA^2=4800-1200=3600$，$AT=60$。"], ["求 BT", "$BT=AT-AB=60-40=20$ 公尺，選 (C)。"]], "tr": "$\\tan30^{\\circ}=\\frac{1}{\\sqrt3}$ 是「對邊 AF ÷ 鄰邊 DA」，別倒過來。"}, {"id": "114B-24", "y": 114, "p": "B", "no": 24, "ch": "B13", "img": "img/tc/114B_24.webp", "a": 0, "t": "平均數：總分守恆", "c": "全體總分 ＝ 甲班總分 ＋ 其他班總分，設總平均為 $M$ 列方程式。", "st": [["列方程式", "$50\\times80+950(M-1)=1000M$。"], ["解", "$4000-950=50M \\Rightarrow M=61$，選 (A)。"]], "tr": ""}, {"id": "114B-25", "y": 114, "p": "B", "no": 25, "ch": "B07", "img": "img/tc/114B_25.webp", "a": 3, "t": "奇偶項分開的數列求和", "c": "奇數項是等比、偶數項是等差，先用 $a_{99}$、$a_{100}$ 反推首項，再分開加。", "st": [["奇數項首項", "$a_{99}$ 是奇數項第 50 項：$a_1(-3)^{49}=-a_1\\cdot3^{49}=5\\cdot3^{49}$，$a_1=-5$。"], ["偶數項首項", "$a_{100}$ 是偶數項第 50 項：$a_2+49\\times3=202$，$a_2=55$。"], ["分開加", "奇數 5 項：$-5,15,-45,135,-405$，和 $-305$；偶數 5 項：$55,58,61,64,67$，和 $305$。總和 $0$，選 (D)。"]], "tr": "$(-3)^{49}$ 是負的，$a_1$ 要是負數。"}, {"id": "114C-1", "y": 114, "p": "C", "no": 1, "ch": "C04", "img": "img/tc/114C_1.webp", "a": 3, "t": "複數乘法", "c": "像多項式一樣展開，再把 $i^2$ 換成 $-1$。", "st": [["展開", "$(1+2i)(2-i)=2-i+4i-2i^2=2+3i+2=4+3i$。"], ["相加", "$a=4$、$b=3$，$a+b=7$，選 (D)。"]], "tr": "$-2i^2=+2$，不是 $-2$。"}, {"id": "114C-2", "y": 114, "p": "C", "no": 2, "ch": "C03", "img": "img/tc/114C_2.webp", "a": 2, "t": "垂直向量內積為 0", "c": "兩向量垂直 ⟺ 內積為 0。", "st": [["看直角", "$\\angle A=90^{\\circ}$，從 $A$ 出發的 $\\overrightarrow{AB}\\perp\\overrightarrow{AC}$。"], ["結論", "$\\overrightarrow{AB}\\cdot\\overrightarrow{AC}=0$，選 (C)。"]], "tr": "(A) 應該是 $\\overrightarrow{AB}+\\overrightarrow{BC}=\\overrightarrow{AC}$；(B) 是兩邊和大於第三邊，不會相等。"}, {"id": "114C-3", "y": 114, "p": "C", "no": 3, "ch": "C15", "img": "img/tc/114C_3.webp", "a": 2, "t": "反導函數：逐項積分", "c": "$x^n$ 的反導函數是 $\\dfrac{x^{n+1}}{n+1}$，常數項可以隨便加。", "st": [["逐項積", "$x^3\\to\\dfrac{x^4}{4}$；$2x\\to x^2$；$-5\\to-5x$。"], ["加常數", "$\\dfrac{x^4}{4}+x^2-5x+C$，(C) 是 $C=-3$ 的情況，選 (C)。"]], "tr": "$-5$ 積分後是 $-5x$；(D) 的 $-5$ 只是常數，微分會不見。"}, {"id": "114C-4", "y": 114, "p": "C", "no": 4, "ch": "C02", "img": "img/tc/114C_4.webp", "a": 1, "t": "大角度化簡：同界角", "c": "先減 360° 的倍數變同界角，再看象限決定正負。", "st": [["化同界角", "$2025^{\\circ}=5\\times360^{\\circ}+225^{\\circ}$。"], ["225° 的值", "第三象限：$\\tan225^{\\circ}=1$，$\\cos225^{\\circ}=-\\frac{\\sqrt2}{2}$，$\\sec225^{\\circ}=-\\sqrt2$。"], ["相加", "$1-\\sqrt2$，選 (B)。"]], "tr": "第三象限 $\\tan$ 為正、$\\sec$ 為負。"}, {"id": "114C-5", "y": 114, "p": "C", "no": 5, "ch": "C04", "img": "img/tc/114C_5.webp", "a": 0, "t": "分母有理化＋比較係數", "c": "有理化後整理成「有理數＋有理數 $\\sqrt2$」，兩邊有理部分、$\\sqrt2$ 部分分別相等。", "st": [["有理化", "$\\dfrac{a}{\\sqrt2-1}=a(\\sqrt2+1)$。"], ["整理比較", "右邊 $=(a-b)+(a+b)\\sqrt2=3+2\\sqrt2$，所以 $a-b=3$、$a+b=2$。"], ["平方差", "$a^2-b^2=(a+b)(a-b)=6$，選 (A)。"]], "tr": "不用真的解出 $a,b$，用平方差公式最快。"}, {"id": "114C-6", "y": 114, "p": "C", "no": 6, "ch": "C09", "img": "img/tc/114C_6.webp", "a": 3, "t": "pH 值與濃度：差 1 就差 10 倍", "c": "$[H^+]=10^{-\\text{pH}}$，pH 越小濃度越大，pH 差 3 濃度就差 $10^3$ 倍。", "st": [["讀圖", "當天 pH 最低約 4、最高約 7。"], ["對應濃度", "pH $=7$ 時濃度最小 $a=10^{-7}$；pH $=4$ 時濃度最大 $10^{-4}$。"], ["比較", "$\\dfrac{10^{-4}}{10^{-7}}=1000$，最大值約 $1000a$，選 (D)。"]], "tr": "濃度最小對應的是 pH 最大（7），別反過來。"}, {"id": "114C-7", "y": 114, "p": "C", "no": 7, "ch": "C06", "img": "img/tc/114C_7.webp", "a": 2, "t": "等差、等比數列綜合", "c": "先用等差求出 $a,b$，再用 $a,b$ 得公比。", "st": [["等差", "$-2$ 到 $7$ 有 3 個公差：$d=3$，$a=1$、$b=4$。"], ["等比", "公比 $r=\\frac{4}{1}=4$，$p=16$、$q=64$。"], ["相加", "$p+q=80$，選 (C)。"]], "tr": ""}, {"id": "114C-8", "y": 114, "p": "C", "no": 8, "ch": "C02", "img": "img/tc/114C_8.webp", "a": 2, "t": "三角函數值比大小定象限", "c": "$0^{\\circ}\\sim90^{\\circ}$ 間 $\\sin$ 遞增、$\\cos$ 遞減；先化成銳角再比。", "st": [["x 坐標", "$\\sin155^{\\circ}=\\sin25^{\\circ}\\lt \\sin55^{\\circ}$，所以 $x\\lt 0$。"], ["y 坐標", "$\\cos222^{\\circ}=-\\cos42^{\\circ}$，$\\cos122^{\\circ}=-\\cos58^{\\circ}$，差為 $\\cos58^{\\circ}-\\cos42^{\\circ}\\lt 0$，所以 $y\\lt 0$。"], ["結論", "$x\\lt 0$、$y\\lt 0$，第三象限，選 (C)。"]], "tr": "$\\cos122^{\\circ}$ 是負的，減一個負數要小心變號。"}, {"id": "114C-9", "y": 114, "p": "C", "no": 9, "ch": "C04", "img": "img/tc/114C_9.webp", "a": 2, "t": "共軛虛根：判別式小於 0", "c": "實係數一元二次方程式有兩個共軛虛根 ⟺ 判別式 $\\lt 0$。", "st": [["整理", "$x^2+kx-k+3=0$，$D=k^2-4(3-k)=k^2+4k-12$。"], ["解不等式", "$(k+6)(k-2)\\lt 0 \\Rightarrow -6\\lt k\\lt 2$。"], ["求 b−a", "$2-(-6)=8$，選 (C)。"]], "tr": "移項後常數項是 $3-k$，別寫成 $k-3$。"}, {"id": "114C-10", "y": 114, "p": "C", "no": 10, "ch": "C12", "img": "img/tc/114C_10.webp", "a": 1, "t": "區域與不等式：代點檢查", "c": "在區域裡挑一個★的點代進去，看符號就知道不等號方向。", "st": [["取一個★", "例如 $(3,7)$。"], ["代入兩式", "$2x-y=-1\\le6$；$x+y=10\\ge8$。"], ["結論", "$\\begin{cases}2x-y\\le6\\\\x+y\\ge8\\end{cases}$，選 (B)。"]], "tr": "$L_1$ 的左上方是 $2x-y\\lt 6$（$y$ 係數為負，別用「上方就是大於」硬套）。"}, {"id": "114C-11", "y": 114, "p": "C", "no": 11, "ch": "C13", "img": "img/tc/114C_11.webp", "a": 0, "t": "拋物線正焦弦長", "c": "$y^2=4cx$ 的正焦弦長 $=4|c|$，焦點 $(c,0)$、準線 $x=-c$。", "st": [["求 c", "頂點仍在原點、開口向右，設 $\\Gamma':y^2=4cx$，$4c=4 \\Rightarrow c=1$。"], ["性質", "方程式 $y^2=4x$、焦點 $(1,0)$、焦距 1、準線 $x=-1$。"], ["對照選項", "只有 (A) 正確，選 (A)。"]], "tr": "正焦弦長 4 是 $4c$，不是 $c$。"}, {"id": "114C-12", "y": 114, "p": "C", "no": 12, "ch": "C14", "img": "img/tc/114C_12.webp", "a": 3, "t": "微分判斷遞增區間", "c": "$f'(x)\\gt 0$ 的區間函數遞增。", "st": [["微分", "$f'(x)=6x^2-6x-12=6(x-2)(x+1)$。"], ["看正負", "$x\\lt -1$ 或 $x\\gt 2$ 時 $f'(x)\\gt 0$，遞增。"], ["對照選項", "$(2,\\infty)$ 整段遞增，選 (D)。"]], "tr": "(C) $(-\\infty,1)$ 中 $-1\\lt x\\lt 1$ 是遞減，不能選。"}, {"id": "114C-13", "y": 114, "p": "C", "no": 13, "ch": "C11", "img": "img/tc/114C_13.webp", "a": 1, "t": "反矩陣解聯立方程式", "c": "$\\begin{bmatrix}x\\\\y\\end{bmatrix}=A^{-1}\\begin{bmatrix}114\\\\2025\\end{bmatrix}$，二階反矩陣：主對角互換、副對角變號、除以行列式。", "st": [["係數矩陣", "$A=\\begin{bmatrix}3\\&4\\\\4\\&5\\end{bmatrix}$，$\\det A=15-16=-1$。"], ["反矩陣", "$A^{-1}=\\dfrac{1}{-1}\\begin{bmatrix}5\\&-4\\\\-4\\&3\\end{bmatrix}=\\begin{bmatrix}-5\\&4\\\\4\\&-3\\end{bmatrix}$。"], ["結論", "選 (B)。"]], "tr": "行列式是 $-1$，忘了除就會選 (A)。"}, {"id": "114C-14", "y": 114, "p": "C", "no": 14, "ch": "C07", "img": "img/tc/114C_14.webp", "a": 1, "t": "奇偶交錯排列", "c": "兩奇不相鄰、兩偶不相鄰，四位數只能「奇偶奇偶」或「偶奇偶奇」。", "st": [["位置型態", "只有 2 種：奇偶奇偶、偶奇偶奇。"], ["填數字", "奇數 5 個排進 2 個位置：$P^5_2=20$；偶數 4 個排進 2 個位置：$P^4_2=12$。"], ["相乘", "$2\\times20\\times12=480$ 個，選 (B)。"]], "tr": "1～9 沒有 0，不用擔心首位為 0。"}, {"id": "114C-15", "y": 114, "p": "C", "no": 15, "ch": "C11", "img": "img/tc/114C_15.webp", "a": 0, "t": "矩陣乘法、加法的條件", "c": "$AB$ 有意義：$A$ 的行數＝$B$ 的列數；$A+B$ 有意義：兩個階數完全相同。", "st": [["乘法", "$A$ 是 $3\\times n$、$B$ 是 $k\\times4$，$AB$ 有意義 ⟺ $n=k$，(A) 正確。"], ["加法", "$A+B$ 要 $3=k$ 且 $n=4$，(B)(D) 都不對。"], ["結論", "選 (A)。"]], "tr": "加法要求的是 $k=3$、$n=4$，和 (D) 剛好相反。"}, {"id": "114C-16", "y": 114, "p": "C", "no": 16, "ch": "C09", "img": "img/tc/114C_16.webp", "a": 3, "t": "半衰期：每 T 年剩一半", "c": "$f(T)=\\frac12$，所以經過 $nT$ 年剩 $\\left(\\frac12\\right)^n$ 公克。", "st": [["逐項算", "$4T$：$\\frac1{16}\\lt \\frac1{10}$；$6T$：$\\frac1{64}\\lt \\frac1{50}$；$8T$：$\\frac1{256}\\gt \\frac1{500}$；$10T$：$\\frac1{1024}\\lt \\frac1{1000}$。"], ["結論", "只有 (D) 敘述正確，選 (D)。"]], "tr": ""}, {"id": "114C-17", "y": 114, "p": "C", "no": 17, "ch": "C05", "img": "img/tc/114C_17.webp", "a": 3, "t": "直角三角形外接圓", "c": "直角三角形的外接圓，斜邊就是直徑，圓心在斜邊中點。", "st": [["找直角", "$\\overrightarrow{AB}=(-4,-8)$、$\\overrightarrow{AC}=(4,-2)$，內積 $-16+16=0$，直角在 $A$，斜邊是 $BC$。"], ["圓心與半徑", "$BC$ 中點 $(1,-1)$；$BC=\\sqrt{8^2+6^2}=10$，半徑 5。"], ["寫方程式", "$(x-1)^2+(y+1)^2=25$，選 (D)。"]], "tr": "右邊是半徑平方 25，不是 $20$ 或直徑。"}, {"id": "114C-18", "y": 114, "p": "C", "no": 18, "ch": "C03", "img": "img/tc/114C_18.webp", "a": 0, "t": "面積比轉成分點", "c": "$\\triangle OAP$、$\\triangle OBP$ 同高（從 $O$ 到 $AB$），面積比＝底邊比 $AP:PB$。", "st": [["得到分點比", "$AP:PB=2:7$。"], ["分點公式", "$P=\\dfrac{7A+2B}{9}=\\left(\\dfrac{7-6}{9},\\dfrac{14+8}{9}\\right)=\\left(\\dfrac19,\\dfrac{22}{9}\\right)$，選 (A)。"]], "tr": "$P$ 靠近 $A$，所以 $A$ 的權重是 7（對面的比），別配反。"}, {"id": "114C-19", "y": 114, "p": "C", "no": 19, "ch": "C08", "img": "img/tc/114C_19.webp", "a": 1, "t": "餘弦定理＋三角形面積", "c": "設 $AC=t$、$BC=3t$，用餘弦定理求 $t^2$，再用 $\\frac12ab\\sin C$。", "st": [["餘弦定理", "$2^2=t^2+9t^2-2\\cdot t\\cdot3t\\cos60^{\\circ}=7t^2$，$t^2=\\frac47$。"], ["面積", "$\\frac12\\cdot t\\cdot3t\\cdot\\sin60^{\\circ}=\\frac32\\cdot\\frac47\\cdot\\frac{\\sqrt3}{2}=\\frac{3\\sqrt3}{7}$，選 (B)。"]], "tr": "面積公式用夾 $C$ 角的兩邊 $AC$、$BC$。"}, {"id": "114C-20", "y": 114, "p": "C", "no": 20, "ch": "C08", "img": "img/tc/114C_20.webp", "a": 2, "t": "正弦定理：外接圓半徑", "c": "$\\dfrac{AB}{\\sin C}=2R$。", "st": [["代正弦定理", "$AB=2R\\sin60^{\\circ}=20\\times\\frac{\\sqrt3}{2}$。"], ["算出", "$AB=10\\sqrt3$ 公尺，選 (C)。"]], "tr": "$2R=20$，半徑 10 要乘 2。"}, {"id": "114C-21", "y": 114, "p": "C", "no": 21, "ch": "C05", "img": "img/tc/114C_21.webp", "a": 0, "t": "直線截距與斜率的關係", "c": "過 $(1,-1)$ 與 $(a,0)$ 的直線，把斜率、$y$ 截距都用 $a$ 表示。", "st": [["寫出直線", "斜率 $m=\\dfrac{0-(-1)}{a-1}=\\dfrac{1}{a-1}$，$y$ 截距 $=-am=-\\dfrac{a}{a-1}$。"], ["檢查 (A)", "$-\\dfrac{a}{a-1}\\gt 0 \\Rightarrow \\dfrac{a}{a-1}\\lt 0 \\Rightarrow 0\\lt a\\lt 1$，(A) 正確。"], ["其他選項", "(B) $y$ 截距負時 $a\\lt 0$ 或 $a\\gt 1$；(C) 斜率正時 $a\\gt 1$；(D) 斜率負時 $a\\lt 1$。都不對，選 (A)。"]], "tr": ""}, {"id": "114C-22", "y": 114, "p": "C", "no": 22, "ch": "C10", "img": "img/tc/114C_22.webp", "a": 1, "t": "空間中兩點距離", "c": "把每段移動換成 $x$（東）、$y$（北）、$z$（上）的位移相加，再用距離公式。", "st": [["最後位置", "東 $+5$、南 $7$（$y=-7$）、高度 $10-4=6$，$E=(5,-7,6)$。"], ["距離", "$\\sqrt{5^2+7^2+6^2}=\\sqrt{110}$，選 (B)。"]], "tr": "高度是上升 10 再下降 4，最後是 6，不是 14。"}, {"id": "114C-23", "y": 114, "p": "C", "no": 23, "ch": "C15", "img": "img/tc/114C_23.webp", "a": 3, "t": "切線與拋物線圍成的面積", "c": "陰影 ＝ 曲線下 $0\\sim4$ 的面積 − 切線下的三角形 $APB$。", "st": [["求切線", "$f'(4)=8$，$L:y=8x-16$，交 $x$ 軸於 $A(2,0)$。"], ["曲線下面積", "$\\int_0^4x^2dx=\\dfrac{64}{3}$。"], ["扣三角形", "$\\triangle APB=\\frac12\\times2\\times16=16$；陰影 $=\\dfrac{64}{3}-16=\\dfrac{16}{3}$，選 (D)。"]], "tr": "三角形底是 $AB=4-2=2$，不是 4。"}, {"id": "114C-24", "y": 114, "p": "C", "no": 24, "ch": "C10", "img": "img/tc/114C_24.webp", "a": 0, "t": "空間向量的正射影", "c": "梯形中 $BC\\perp CD$，$A$ 投影到直線 $CD$ 的位置就決定 $AB$ 長：$AB=CD-(\\text{DA 在 DC 上的投影長})$。", "st": [["兩個向量", "$\\overrightarrow{DC}=(2,-1,2)$，$|DC|=3$；$\\overrightarrow{DA}=(3,-4,-2)$。"], ["投影長", "$\\dfrac{\\overrightarrow{DA}\\cdot\\overrightarrow{DC}}{|DC|}=\\dfrac{6+4-4}{3}=2$。"], ["求 AB", "$AB=3-2=1$，選 (A)。"]], "tr": "用投影長算，不需要求出 $B$ 點坐標也能得到答案。"}, {"id": "114C-25", "y": 114, "p": "C", "no": 25, "ch": "C14", "img": "img/tc/114C_25.webp", "a": 1, "t": "紙盒體積最大：微分求極值", "c": "寫出長、寬、高的式子，體積對 $a$ 微分令為 0。", "st": [["盒子的尺寸", "高 $a$（$A_iB_i=2a$ 對折成 $a$）；長 $3-2a$（左右各扣 $a$）；寬 $2-4a$（上下各扣 $2a$）。"], ["體積與微分", "$V=a(3-2a)(2-4a)=8a^3-16a^2+6a$，$V'=24a^2-32a+6=0 \\Rightarrow 12a^2-16a+3=0$。"], ["取合理解", "$a=\\dfrac{16\\pm\\sqrt{112}}{24}=\\dfrac{4\\pm\\sqrt7}{6}$；寬要正，$a\\lt \\frac12$，取 $\\dfrac{4-\\sqrt7}{6}\\approx0.23$，選 (B)。"]], "tr": "上下的折邊是 $2a$（對折前），寬要扣 $4a$，當成扣 $2a$ 會選錯。"}, {"id": "115A-1", "y": 115, "p": "A", "no": 1, "ch": "A10", "img": "img/tc/115A_1.webp", "a": 0, "t": "眾數：次數最多的那一項", "c": "「最受歡迎」就是被點最多杯的飲料，也就是資料的<b>眾數</b>。", "st": [["比較杯數", "四季春青茶 12 杯、茉莉綠茶 9 杯、黑糖珍珠鮮奶 6 杯、紅茶拿鐵 3 杯。"], ["找最大", "12 杯最多，所以最受歡迎的是四季春青茶，選 (A)。"]], "tr": ""}, {"id": "115A-2", "y": 115, "p": "A", "no": 2, "ch": "A04", "img": "img/tc/115A_2.webp", "a": 0, "t": "直角三角形的 sin 定義", "c": "$\\sin A=\\dfrac{\\text{對邊}}{\\text{斜邊}}$，斜邊一定是直角對面的那條邊。", "st": [["找對邊與斜邊", "$\\angle C=90^{\\circ}$，斜邊是 $\\overline{AB}=13$；$\\angle A$ 的對邊是 $\\overline{BC}=5$。"], ["代入定義", "$$\\sin A=\\frac{5}{13}$$選 (A)。"]], "tr": "把鄰邊 12 當成對邊，算成 $\\frac{12}{13}$（那是 $\\cos A$）。"}, {"id": "115A-3", "y": 115, "p": "A", "no": 3, "ch": "A07", "img": "img/tc/115A_3.webp", "a": 0, "t": "一元一次不等式", "c": "先展開、移項整理成 $ax\\lt b$，兩邊除以正數時不等號方向不變。", "st": [["展開", "$5(x+1)-3(x-1)=5x+5-3x+3=2x+8$"], ["解不等式", "$2x+8\\lt 0\\Rightarrow 2x\\lt -8\\Rightarrow x\\lt -4$，選 (A)。"]], "tr": "$-3(x-1)$ 展開成 $-3x-3$，負號沒有乘進去。"}, {"id": "115A-4", "y": 115, "p": "A", "no": 4, "ch": "A08", "img": "img/tc/115A_4.webp", "a": 1, "t": "指數律：同底相乘指數相加", "c": "$10^a\\cdot10^b=10^{a+b}$，再把 100 寫成 $10^2$ 比較指數。", "st": [["用指數律合併", "$10^a\\cdot10^b=10^{a+b}=100=10^2$"], ["比較指數", "$a+b=2$，選 (B)。"]], "tr": "誤以為指數相乘，寫成 $a\\cdot b=2$。"}, {"id": "115A-5", "y": 115, "p": "A", "no": 5, "ch": "A05", "img": "img/tc/115A_5.webp", "a": 1, "t": "圓的標準式", "c": "圓心 $(h,k)$、半徑 $r$ 的圓：$(x-h)^2+(y-k)^2=r^2$。", "st": [["代入圓心", "$h=-2$、$k=2$：$(x-(-2))^2+(y-2)^2=(x+2)^2+(y-2)^2$。"], ["右邊是半徑平方", "$r^2=2^2=4$，所以 $(x+2)^2+(y-2)^2=4$，選 (B)。"]], "tr": "右邊忘了平方寫成 2，或圓心正負號弄反。"}, {"id": "115A-6", "y": 115, "p": "A", "no": 6, "ch": "A01", "img": "img/tc/115A_6.webp", "a": 0, "t": "絕對值方程式與數線距離", "c": "$|x-a|=d$ 表示「$x$ 到 $a$ 的距離是 $d$」，解為 $a\\pm d$。", "st": [["看兩解的中點與距離", "$-2$ 和 $4$ 的中點是 $1$，各離 $1$ 的距離是 $3$。"], ["寫成絕對值", "所以方程式是 $|x-1|=3$；驗算：$x-1=\\pm3\\Rightarrow x=4$ 或 $-2$，選 (A)。"]], "tr": ""}, {"id": "115A-7", "y": 115, "p": "A", "no": 7, "ch": "A01", "img": "img/tc/115A_7.webp", "a": 3, "t": "二次函數圖形：頂點與開口", "c": "$f(x)=x^2+1$ 開口向上、頂點 $(0,1)$，最低點在 $y=1$。", "st": [["判斷開口", "$x^2$ 係數 $1\\gt 0$，開口向上，排除 (C)。"], ["找頂點並代點檢查", "頂點 $(0,1)$，排除頂點在 $(0,-1)$ 的 (B)。再代 $x=2$：$f(2)=5$，(D) 的圖通過 $(2,5)$，(A) 的圖在 $x=2$ 時只有 3，不對。選 (D)。"]], "tr": "只看頂點 $(0,1)$ 就選 (A)，沒有代點檢查開口大小。"}, {"id": "115A-8", "y": 115, "p": "A", "no": 8, "ch": "A02", "img": "img/tc/115A_8.webp", "a": 3, "t": "三點共線：斜率相同", "c": "三點共線時，任兩點連線的斜率都相同，所以 $BC$ 斜率＝$AB$ 斜率。", "st": [["算 AB 斜率", "$$m_{AB}=\\frac{7-4}{8-2}=\\frac{3}{6}=\\frac12$$"], ["共線推得", "$A、B、C$ 共線，$m_{BC}=m_{AB}=\\frac12$，選 (D)。"]], "tr": ""}, {"id": "115A-9", "y": 115, "p": "A", "no": 9, "ch": "A06", "img": "img/tc/115A_9.webp", "a": 2, "t": "等差中項", "c": "$a、b$ 的等差中項就是平均 $\\frac{a+b}{2}$。", "st": [["求等差中項", "$\\frac{7+13}{2}=10$"], ["解方程式", "$4x+2=10\\Rightarrow x=2$，選 (C)。"]], "tr": "把等差中項和等比中項 $\\sqrt{ab}$ 搞混。"}, {"id": "115A-10", "y": 115, "p": "A", "no": 10, "ch": "A07", "img": "img/tc/115A_10.webp", "a": 2, "t": "文字敘述列不等式", "c": "總車資＝單價×次數相加；「以上（含）」用 $\\ge$。", "st": [["列總車資", "高鐵 $x$ 次：$1490x$；自強號 $y$ 次：$975y$，總共 $1490x+975y$。"], ["10000 元以上（含）", "$1490x+975y\\ge10000$，選 (C)。"]], "tr": "單價配錯次數，寫成 $975x+1490y$。"}, {"id": "115A-11", "y": 115, "p": "A", "no": 11, "ch": "A09", "img": "img/tc/115A_11.webp", "a": 2, "t": "重複排列：每位都有 10 種選法", "c": "可以重複使用時，每一位都獨立有 10 種選擇，用乘法原理。", "st": [["每一位的選法", "6 個位置，每位都能填 0～9 共 10 種。"], ["乘法原理", "$10\\times10\\times\\cdots\\times10=10^6$，選 (C)。"]], "tr": "寫成 $6^{10}$（底數和指數顛倒），或誤用不可重複的 $P^{10}_6$。"}, {"id": "115A-12", "y": 115, "p": "A", "no": 12, "ch": "A09", "img": "img/tc/115A_12.webp", "a": 3, "t": "組合：選出不計順序", "c": "招待券只看「哪 3 攤」，不管順序，用組合 $C^n_r$。", "st": [["判斷用組合", "7 攤選 3 攤，順序不影響，是 $C^7_3$。"], ["計算", "$$C^7_3=\\frac{7\\times6\\times5}{3\\times2\\times1}=35$$選 (D)。"]], "tr": "用排列 $P^7_3=210$，多算了順序。"}, {"id": "115A-13", "y": 115, "p": "A", "no": 13, "ch": "A10", "img": "img/tc/115A_13.webp", "a": 1, "t": "期望值＝數值×機率相加", "c": "期望值就是每種結果乘上它的機率，再全部加起來。", "st": [["列出各情況", "1000 次×0.4、200 次×0.5、0 次×0.1。"], ["相加", "$1000\\times0.4+200\\times0.5+0\\times0.1=400+100=500$，選 (B)。"]], "tr": ""}, {"id": "115A-14", "y": 115, "p": "A", "no": 14, "ch": "A02", "img": "img/tc/115A_14.webp", "a": 2, "t": "直角三角形：找互相垂直的直線", "c": "兩直線垂直 ⇔ 斜率相乘 $=-1$。$L_1$、$L_2$ 本身不垂直，所以第三條線要和其中一條垂直。", "st": [["求兩線斜率", "$L_1:x+y-4=0$，斜率 $-1$；$L_2:x-2y+2=0$，斜率 $\\frac12$。$(-1)\\times\\frac12\\ne-1$，不垂直。"], ["要找的斜率", "與 $L_1$ 垂直要斜率 $1$；與 $L_2$ 垂直要斜率 $-2$。"], ["檢查選項", "(A) 斜率 $-1$ 與 $L_1$ 平行、(B) 斜率 $\\frac12$ 與 $L_2$ 平行，圍不成三角形；(D) 斜率 $-\\frac12$；(C) $2x+y-4=0$ 斜率 $-2$，與 $L_2$ 垂直。選 (C)。"]], "tr": "把 $ax+by+c=0$ 的斜率算成 $\\frac{a}{b}$，少了負號。"}, {"id": "115A-15", "y": 115, "p": "A", "no": 15, "ch": "A06", "img": "img/tc/115A_15.webp", "a": 0, "t": "等比數列：每年乘 0.88", "c": "每年價格變成前一年的 88%，是公比 $0.88$ 的等比數列，第 $n$ 年是 $a_1r^{n-1}$。", "st": [["首項與公比", "$a_1=100$（萬元），$r=0.88$。"], ["第 6 年", "$a_6=100\\times0.88^{5}$，選 (A)。"]], "tr": "指數寫成 6；或把折舊率 0.12 當公比。"}, {"id": "115A-16", "y": 115, "p": "A", "no": 16, "ch": "A04", "img": "img/tc/115A_16.webp", "a": 1, "t": "仰角求高度要加身高", "c": "風箏線是斜邊，高度差＝$30\\sin45^{\\circ}$，最後別忘了加上手的高度。", "st": [["算線上升的高度", "$30\\sin45^{\\circ}=30\\times\\frac{\\sqrt2}{2}=15\\sqrt2\\approx21.21$ 公尺。"], ["加上身高", "140 公分＝1.4 公尺，$21.21+1.4\\approx22.6$，最接近 22，選 (B)。"]], "tr": "忘了加身高只得 21，或把 140 公分當 140 公尺。"}, {"id": "115A-17", "y": 115, "p": "A", "no": 17, "ch": "A07", "img": "img/tc/115A_17.webp", "a": 2, "t": "線性規劃：列材料限制", "c": "每種材料「用掉的總量 ≤ 準備量」，單位要先統一成公升。", "st": [["統一單位", "360 毫升＝0.36 公升，其餘同理：A 杯用茶 0.36、奶 0.12；B 杯用茶 0.16、奶 0.32。"], ["列不等式", "濃茶：$0.36x+0.16y\\le54$；鮮奶：$0.12x+0.32y\\le30$；杯數 $x\\ge0、y\\ge0$。"], ["對照選項", "兩條都是 $\\le$，且 54 配濃茶、30 配鮮奶，選 (C)。"]], "tr": "把 54 和 30 配錯材料，或寫成 $\\ge$。"}, {"id": "115A-18", "y": 115, "p": "A", "no": 18, "ch": "A03", "img": "img/tc/115A_18.webp", "a": 3, "t": "餘式定理", "c": "$f(x)$ 除以 $x-a$ 的餘式就是 $f(a)$。", "st": [["找 a", "$x+1=x-(-1)$，所以 $a=-1$。"], ["代值", "餘式 $=f(-1)=-8$，選 (D)。"]], "tr": "看到 $x+1$ 就代 $f(1)$，選成 $-4$。"}, {"id": "115A-19", "y": 115, "p": "A", "no": 19, "ch": "A08", "img": "img/tc/115A_19.webp", "a": 1, "t": "對數相減＝真數相除", "c": "$\\log_2M-\\log_2N=\\log_2\\frac MN$，而 $2^{\\log_2k}=k$。", "st": [["合併對數", "$a=\\log_227-\\log_26=\\log_2\\frac{27}{6}=\\log_2\\frac92$"], ["還原指數", "$2^a=2^{\\log_2\\frac92}=\\frac92$，選 (B)。"]], "tr": ""}, {"id": "115A-20", "y": 115, "p": "A", "no": 20, "ch": "A03", "img": "img/tc/115A_20.webp", "a": 1, "t": "根與係數關係", "c": "$x^2+ax+b=0$ 兩根和 $=-a$、兩根積 $=b$。", "st": [["兩根積", "$\\alpha\\beta=b=0$，所以 $b=0$。"], ["兩根和檢查其他選項", "$\\alpha+\\beta=-a\\gt 0\\Rightarrow a\\lt 0$，所以 (A) 錯；$a+b=a\\lt 0$、$a-b=a\\lt 0$，(C)(D) 都錯。選 (B)。"]], "tr": "兩根和忘了負號，以為 $a\\gt 0$。"}, {"id": "115A-21", "y": 115, "p": "A", "no": 21, "ch": "A05", "img": "img/tc/115A_21.webp", "a": 3, "t": "圓與直線：比較距離與半徑", "c": "圓心到直線距離 $d$ 和半徑 $r$ 比：$d\\lt r$ 交兩點、$d=r$ 相切、$d\\gt r$ 不相交。", "st": [["圓心與半徑", "圓心 $(2,-2)$，半徑 $2$。"], ["點到直線距離", "$$d=\\frac{|3\\cdot2-4\\cdot(-2)+1|}{\\sqrt{3^2+4^2}}=\\frac{15}{5}=3$$"], ["比較", "$d=3\\gt 2=r$，圓與直線不相交，選 (D)。"]], "tr": "代入 $-2$ 時 $-4\\times(-2)$ 算成 $-8$。"}, {"id": "115A-22", "y": 115, "p": "A", "no": 22, "ch": "A10", "img": "img/tc/115A_22.webp", "a": 3, "t": "極端值只影響全距、標準差", "c": "四分位距只看 $Q_1$、$Q_3$，最大值變大不會影響中間位置的數。", "st": [["資料變化", "G 由 75 變 150，仍是最大值，其他 6 個數不變，排序也不變。"], ["逐一檢查", "最大值變了 ⇒ 全距變了；平均和離均差變了 ⇒ 標準差變了。"], ["四分位距", "7 筆資料的 $Q_1$ 是第 2 個數 24、$Q_3$ 是第 6 個數 58，都沒變，四分位距 $58-24=34$ 不變。選 (D)。"]], "tr": ""}, {"id": "115A-23", "y": 115, "p": "A", "no": 23, "ch": "A09", "img": "img/tc/115A_23.webp", "a": 2, "t": "分類計數：加法原理", "c": "有限制條件時，依上衣種類分開數，再相加。", "st": [["穿襯衫", "3 件襯衫，每件可配 3 件長褲：$3\\times3=9$ 種。"], ["穿運動 T 恤", "2 件 T 恤只能配運動褲：$2\\times1=2$ 種。"], ["相加", "$9+2=11$，選 (C)。"]], "tr": "直接 $5\\times3=15$，忽略 T 恤只配運動褲的限制。"}, {"id": "115A-24", "y": 115, "p": "A", "no": 24, "ch": "A10", "img": "img/tc/115A_24.webp", "a": 2, "t": "分組機率：固定一人看另一人", "c": "先讓阿聰坐定一組，阿明只要落在剩下 5 個位置中「同組的 2 個」即可。", "st": [["固定阿聰", "阿聰那組還剩 2 個空位，另一組 3 個空位，共 5 個位置給阿明。"], ["算機率", "阿明同組的機率 $=\\frac25$，選 (C)。"]], "tr": "以為只有兩組所以是 $\\frac12$。"}, {"id": "115A-25", "y": 115, "p": "A", "no": 25, "ch": "A08", "img": "img/tc/115A_25.webp", "a": 0, "t": "分貝與強度：對數應用", "c": "分貝相差 $\\Delta d$，強度比 $=10^{\\Delta d/10}$。", "st": [["兩式相減", "$69-60=10\\log\\frac{I_2}{I_0}-10\\log\\frac{I_1}{I_0}=10\\log\\frac{I_2}{I_1}$"], ["求倍數", "$\\log\\frac{I_2}{I_1}=0.9$，$\\frac{I_2}{I_1}=10^{0.9}=\\frac{10}{10^{0.1}}$。"], ["估算", "$\\log8=3\\times0.3010=0.903\\approx0.9$，所以約 8 倍，選 (A)。"]], "tr": "以為 69 是 60 的 1.15 倍，強度也只差一點點。"}, {"id": "115B-1", "y": 115, "p": "B", "no": 1, "ch": "B05", "img": "img/tc/115B_1.webp", "a": 1, "t": "向量減法與坐標", "c": "$\\overrightarrow{OS}-\\overrightarrow{OT}=\\overrightarrow{TS}$，用坐標相減最快。", "st": [["讀坐標", "由方格圖：$S(0,2)$、$T(3,0)$。"], ["相減", "$\\overrightarrow{OS}-\\overrightarrow{OT}=(0-3,\\,2-0)=(-3,2)$"], ["對照圖", "$B$ 點坐標正是 $(-3,2)$，所以等於 $\\overrightarrow{OB}$，選 (B)。"]], "tr": "減反了算成 $(3,-2)$，對到別的點。"}, {"id": "115B-2", "y": 115, "p": "B", "no": 2, "ch": "B08", "img": "img/tc/115B_2.webp", "a": 0, "t": "根與係數求兩根", "c": "兩根和 $=8$、兩根積 $=5(\\alpha-\\beta)$，先用和解出 $\\alpha$，再用積消去 $\\alpha-\\beta$。", "st": [["兩根和", "$(\\alpha+\\beta)+(\\alpha-\\beta)=2\\alpha=8\\Rightarrow\\alpha=4$"], ["兩根積", "$(\\alpha+\\beta)(\\alpha-\\beta)=5(\\alpha-\\beta)$，因為 $\\alpha\\ne\\beta$，兩邊可除以 $\\alpha-\\beta$：$\\alpha+\\beta=5$。"], ["求 αβ", "$\\beta=5-4=1$，$\\alpha\\beta=4$，選 (A)。"]], "tr": ""}, {"id": "115B-3", "y": 115, "p": "B", "no": 3, "ch": "B02", "img": "img/tc/115B_3.webp", "a": 0, "t": "截距與平行線斜率", "c": "$x$ 截距令 $y=0$；平行線斜率相同，$ax+by=c$ 的斜率是 $-\\frac ab$。", "st": [["x 截距", "$y=0$：$2x=4\\Rightarrow a=2$。"], ["斜率", "$L_1$ 斜率 $=-\\frac23$，平行所以 $m=-\\frac23$。$(a,m)=(2,-\\frac23)$，選 (A)。"]], "tr": "斜率少了負號選 (B)。"}, {"id": "115B-4", "y": 115, "p": "B", "no": 4, "ch": "B08", "img": "img/tc/115B_4.webp", "a": 2, "t": "一元二次不等式", "c": "先因式分解找兩根，$\\le0$ 取兩根之間。", "st": [["因式分解", "$2x^2+7x+3=(2x+1)(x+3)\\le0$"], ["解", "$-3\\le x\\le-\\frac12$，所以 $a=-3$、$b=-\\frac12$。"], ["檢查選項", "$a=-3$ 是整數，選 (C)。"]], "tr": ""}, {"id": "115B-5", "y": 115, "p": "B", "no": 5, "ch": "B01", "img": "img/tc/115B_5.webp", "a": 1, "t": "平行四邊形對角線互相平分", "c": "平行四邊形 $ABCD$ 中，$A+C=B+D$（坐標相加）。", "st": [["求 C", "$C=B+D-A=(0+2+1,\\,-5+3-0)=(3,-2)$"], ["BC 中點", "$$\\left(\\frac{0+3}{2},\\frac{-5-2}{2}\\right)=\\left(\\frac32,-\\frac72\\right)$$選 (B)。"]], "tr": "寫成 $A+B=C+D$，頂點對應錯。"}, {"id": "115B-6", "y": 115, "p": "B", "no": 6, "ch": "B03", "img": "img/tc/115B_6.webp", "a": 3, "t": "除以二次式：餘式定理", "c": "除以二次式的餘式是一次式 $ax+b$，用 $f(1)$、$f(2)$ 列兩式。", "st": [["設餘式", "$f(x)=(x-1)(x-2)Q(x)+ax+b$"], ["代值", "$f(1)=1-3+2-1+1=0=a+b$；$f(2)=16-24+8-2+1=-1=2a+b$。"], ["解聯立", "$a=-1$、$b=1$，餘式 $-x+1$，選 (D)。"]], "tr": ""}, {"id": "115B-7", "y": 115, "p": "B", "no": 7, "ch": "B04", "img": "img/tc/115B_7.webp", "a": 1, "t": "同界角與象限判斷", "c": "同界角差 $360^{\\circ}$ 的整數倍；再看 tan、sin 的正負決定象限。", "st": [["求 a、b", "$2026^{\\circ}-6\\times360^{\\circ}=-134^{\\circ}$，$a=-134^{\\circ}$；$-115^{\\circ}+360^{\\circ}=245^{\\circ}$，$b=245^{\\circ}$。"], ["判斷正負", "$a-b=-379^{\\circ}$，同界角 $-19^{\\circ}$，$\\tan\\lt 0$；$a+b=111^{\\circ}$（第二象限角），$\\sin\\gt 0$。"], ["定象限", "點 $(-,+)$ 在第二象限，選 (B)。"]], "tr": "最大負同界角算成 $-134^{\\circ}-360^{\\circ}$，越減越小。"}, {"id": "115B-8", "y": 115, "p": "B", "no": 8, "ch": "B05", "img": "img/tc/115B_8.webp", "a": 3, "t": "內積求夾角", "c": "$\\cos\\theta=\\dfrac{\\vec a\\cdot\\vec b}{|\\vec a||\\vec b|}$。", "st": [["寫出向量", "$\\overrightarrow{AB}=(4,0)$、$\\overrightarrow{AC}=(-2,2\\sqrt3)$"], ["代公式", "內積 $=-8$；長度 $4$ 與 $\\sqrt{4+12}=4$。$$\\cos\\theta=\\frac{-8}{4\\times4}=-\\frac12$$選 (D)。"]], "tr": ""}, {"id": "115B-9", "y": 115, "p": "B", "no": 9, "ch": "B02", "img": "img/tc/115B_9.webp", "a": 0, "t": "垂直斜率與點斜式", "c": "垂直 ⇒ 斜率相乘 $-1$；先把點代入 $L_1$ 求出 $a$。", "st": [["求 a", "$(a,1)$ 代入：$4a+(a+5)-10=0\\Rightarrow5a=5\\Rightarrow a=1$。"], ["L₃ 斜率", "$L_2$ 斜率 $-\\frac12$，垂直 ⇒ $L_3$ 斜率 $2$。"], ["點斜式", "$y-1=2(x-1)\\Rightarrow2x-y-1=0$，選 (A)。"]], "tr": ""}, {"id": "115B-10", "y": 115, "p": "B", "no": 10, "ch": "B13", "img": "img/tc/115B_10.webp", "a": 2, "t": "取後放回：獨立事件相乘", "c": "每次放回，三次互不影響，機率直接相乘。", "st": [["單次沒抽到甲", "$\\frac23$"], ["連三次", "$\\left(\\frac23\\right)^3=\\frac{8}{27}$，選 (C)。"]], "tr": "算成「至少一次抽到甲」$\\frac{19}{27}$。"}, {"id": "115B-11", "y": 115, "p": "B", "no": 11, "ch": "B03", "img": "img/tc/115B_11.webp", "a": 3, "t": "多項式恆等：以 x+2 展開", "c": "令 $t=x+2$（$x=t-2$）代入 $g$，展開比較係數。", "st": [["代換", "$g(t-2)=4(t-2)^3+3(t-2)^2+2(t-2)+1$"], ["展開整理", "$4(t^3-6t^2+12t-8)+3(t^2-4t+4)+2t-4+1=4t^3-21t^2+38t-23$"], ["比較係數", "$b=-21$、$c=38$，$b+c=17$，選 (D)。"]], "tr": ""}, {"id": "115B-12", "y": 115, "p": "B", "no": 12, "ch": "B08", "img": "img/tc/115B_12.webp", "a": 3, "t": "二元一次聯立的解的個數", "c": "無限多解 ⇒ 第二式是第一式的倍數。係數比例相同才可能無解或無限多解，比例不同就唯一解。", "st": [["設倍數", "$a=2k$、$b=3k$、$c=4k$（$k\\ne0$）。"], ["看 (D)", "$1000ax+by=2000k\\,x+3k\\,y$，$x、y$ 係數比 $2000:3\\ne2:3$，兩直線不平行，<b>唯一解</b>。"], ["排除其他", "(A)、(B) 兩式係數成比例但常數不成比例，都是無解；(C) 其實是唯一解。選 (D)。"]], "tr": ""}, {"id": "115B-13", "y": 115, "p": "B", "no": 13, "ch": "B09", "img": "img/tc/115B_13.webp", "a": 0, "t": "不等式圖解：截距與原點測試", "c": "先找兩直線截距，再用原點 $(0,0)$ 代入判斷要塗哪一側。", "st": [["兩直線截距", "$26x+15y=2026$：$x$ 截距約 78、$y$ 截距約 135（較陡）；$15x+26y=2026$：$x$ 截距約 135、$y$ 截距約 78。兩線斜率都是負的。"], ["原點測試", "$(0,0)$ 代入兩式都是 $0\\le2026$ 成立，區域含原點，在兩線的左下方。"], ["選圖", "(A) 兩線斜率為負、塗左下方，選 (A)。"]], "tr": ""}, {"id": "115B-14", "y": 115, "p": "B", "no": 14, "ch": "B07", "img": "img/tc/115B_14.webp", "a": 3, "t": "等比數列的項成等比", "c": "$a_n=a_1\\cdot3^{n-1}$，下標差 2 ⇒ 比值是 $3^2$。", "st": [["相鄰比值", "$y=x+2$：$\\frac{a_y}{a_x}=3^{y-x}=3^2=9$；同理 $\\frac{a_z}{a_y}=9$。"], ["結論", "$a_x、a_y、a_z$ 成公比 9 的等比數列，選 (D)。"]], "tr": ""}, {"id": "115B-15", "y": 115, "p": "B", "no": 15, "ch": "B10", "img": "img/tc/115B_15.webp", "a": 3, "t": "指數函數求倍數", "c": "兩溫度相除，係數 10650 消掉，只剩 $32$ 的指數差。", "st": [["相除", "$$\\frac{T(27)}{T(35)}=32^{-2.7-(-3.5)}=32^{0.8}$$"], ["化成 2 的次方", "$32^{0.8}=2^{5\\times0.8}=2^4=16$，選 (D)。"]], "tr": "指數相減方向弄反得 $\\frac1{16}$。"}, {"id": "115B-16", "y": 115, "p": "B", "no": 16, "ch": "B13", "img": "img/tc/115B_16.webp", "a": 2, "t": "讀圖表與中位數", "c": "判斷「錯誤」選項；中位數要先<b>排序</b>再取中間。", "st": [["檢查 (C)", "2008～2016 共 9 筆，由小排到大：166886、191310、196627、198733、<b>199113</b>、208440、210383、213598、229481，中位數是第 5 個 199113，不是 229481，(C) 錯。"], ["其他選項", "(A) 圖中龍年都比前後高；(B) 最大約 42 萬多、最小 107812，全距超過 30 萬；(D) 表中 2017～2025 一路遞減。都正確。"], ["答案", "錯誤的是 (C)，選 (C)。"]], "tr": "沒排序就直接拿中間那年（2012）的數字。"}, {"id": "115B-17", "y": 115, "p": "B", "no": 17, "ch": "B12", "img": "img/tc/115B_17.webp", "a": 2, "t": "組合：7 段選 2 段", "c": "7 段燈位置固定、不考慮旋轉翻面，每種選法都是不同圖案。", "st": [["列式", "從 7 段選 2 段亮，不計順序：$C^7_2$。"], ["計算", "$C^7_2=\\frac{7\\times6}{2}=21$，選 (C)。"]], "tr": "用排列算成 42。"}, {"id": "115B-18", "y": 115, "p": "B", "no": 18, "ch": "B13", "img": "img/tc/115B_18.webp", "a": 2, "t": "期望值：記得扣成本", "c": "獲利 = 獎金期望值 − 50 元票價。", "st": [["獎金期望值", "$10000\\times0.001+5000\\times0.002+1000\\times0.005+500\\times0.01=10+10+5+5=30$"], ["扣成本", "$30-50=-20$ 元，選 (C)。"]], "tr": "忘了扣 50 元選 (B)。"}, {"id": "115B-19", "y": 115, "p": "B", "no": 19, "ch": "B04", "img": "img/tc/115B_19.webp", "a": 1, "t": "tan 週期 180° 估值", "c": "$\\tan$ 週期是 $180^{\\circ}$，都化成 $0^{\\circ}\\sim180^{\\circ}$ 再比較。", "st": [["化簡角度", "$1847^{\\circ}\\to47^{\\circ}$、$2205^{\\circ}\\to45^{\\circ}$、$2126^{\\circ}\\to146^{\\circ}$、$2026^{\\circ}-11\\times180^{\\circ}=46^{\\circ}$。"], ["比大小", "$\\tan$ 在 $0^{\\circ}\\sim90^{\\circ}$ 遞增：$\\tan45^{\\circ}=1\\lt \\tan46^{\\circ}\\lt \\tan47^{\\circ}\\approx1.072$。"], ["選答", "介於 1 和 1.072 之間只有 1.036，選 (B)。"]], "tr": ""}, {"id": "115B-20", "y": 115, "p": "B", "no": 20, "ch": "B11", "img": "img/tc/115B_20.webp", "a": 0, "t": "正弦定理求邊長", "c": "已知兩角一邊，先求第三角，再用正弦定理。", "st": [["第三角", "$\\angle C=180^{\\circ}-60^{\\circ}-75^{\\circ}=45^{\\circ}$"], ["正弦定理", "$$\\frac{\\overline{AC}}{\\sin75^{\\circ}}=\\frac{100}{\\sin45^{\\circ}}\\Rightarrow\\overline{AC}=100\\cdot\\frac{\\sqrt6+\\sqrt2}{4}\\cdot\\frac{2}{\\sqrt2}=50(\\sqrt3+1)$$"], ["答案", "選 (A)。"]], "tr": "$AC$ 的對角是 $\\angle B=75^{\\circ}$，別配成 $60^{\\circ}$。"}, {"id": "115B-21", "y": 115, "p": "B", "no": 21, "ch": "B11", "img": "img/tc/115B_21.webp", "a": 0, "t": "餘弦定理解二次方程", "c": "已知 $\\angle C$ 的兩鄰邊之一和對邊，用餘弦定理設未知邊。", "st": [["列式", "設 $\\overline{BC}=x$：$7^2=8^2+x^2-2\\cdot8\\cdot x\\cos60^{\\circ}$"], ["解方程", "$49=64+x^2-8x\\Rightarrow x^2-8x+15=0\\Rightarrow x=3$ 或 $5$"], ["取符合條件", "$x\\gt 4$，所以 $x=5$，選 (A)。"]], "tr": ""}, {"id": "115B-22", "y": 115, "p": "B", "no": 22, "ch": "B12", "img": "img/tc/115B_22.webp", "a": 1, "t": "「至少一個」用全部扣掉", "c": "每張 2 種，共 $2^5$ 種；扣掉「全部都是無」的 1 種。", "st": [["全部情況", "$2^5=32$"], ["扣掉全無", "$32-1=31$，選 (B)。"]], "tr": ""}, {"id": "115B-23", "y": 115, "p": "B", "no": 23, "ch": "B08", "img": "img/tc/115B_23.webp", "a": 1, "t": "一元一次方程式應用", "c": "兩人總費用相等，各自列出總價再列等式。", "st": [["行程 I", "$2x-3000$"], ["行程 II", "一人原價、一人八折：$(x+2000)+0.8(x+2000)=1.8(x+2000)$"], ["解方程", "$2x-3000=1.8x+3600\\Rightarrow0.2x=6600\\Rightarrow x=33000$，選 (B)。"]], "tr": ""}, {"id": "115B-24", "y": 115, "p": "B", "no": 24, "ch": "B10", "img": "img/tc/115B_24.webp", "a": 2, "t": "對數估算與無條件進位", "c": "$\\log1.08=\\log\\frac{108}{100}=\\log(2^2\\cdot3^3)-2$，用給的 $\\log2$、$\\log3$ 算。", "st": [["算 C", "$A=\\frac{110}{8}=13.75$，進位得 $C=14$。"], ["算 B", "$\\log1.08=2(0.3010)+3(0.4771)-2=0.0333$，$B=\\frac{0.4771}{0.0333}\\approx14.3$，進位得 $D=15$。"], ["比較", "$D=C+1$，選 (C)。"]], "tr": ""}, {"id": "115B-25", "y": 115, "p": "B", "no": 25, "ch": "B06", "img": "img/tc/115B_25.webp", "a": 2, "t": "圓與切線：半徑＝距離", "c": "把圓方程式配方找圓心和半徑；相切時半徑＝圓心到切線距離。", "st": [["配方", "$x^2-8x+(y-7)^2=a\\Rightarrow(x-4)^2+(y-7)^2=a+16$，圓心 $(4,7)$，所以 $h=4$。"], ["半徑", "相切 ⇒ $r=\\sqrt2$，$r^2=2=a+16\\Rightarrow a=-14$。"], ["相加", "$h+a=4-14=-10$，選 (C)。"]], "tr": "配方忘了右邊也要加 16。"}, {"id": "115C-1", "y": 115, "p": "C", "no": 1, "ch": "C04", "img": "img/tc/115C_1.webp", "a": 0, "t": "根與係數：造新方程式", "c": "新方程式 $x^2-(\\text{兩根和})x+(\\text{兩根積})=0$。", "st": [["原方程式", "$\\alpha+\\beta=3$、$\\alpha\\beta=-3$"], ["新兩根和", "$$\\frac\\alpha\\beta+\\frac\\beta\\alpha=\\frac{(\\alpha+\\beta)^2-2\\alpha\\beta}{\\alpha\\beta}=\\frac{9+6}{-3}=-5$$"], ["新兩根積與方程式", "$\\frac\\alpha\\beta\\cdot\\frac\\beta\\alpha=1$，方程式 $x^2+5x+1=0$，選 (A)。"]], "tr": "一次項係數是「負的兩根和」，別寫成 $-5x$。"}, {"id": "115C-2", "y": 115, "p": "C", "no": 2, "ch": "C06", "img": "img/tc/115C_2.webp", "a": 1, "t": "等差數列：中間項代表平均", "c": "奇數項等差的和＝項數×中間項；成對的項和相等。", "st": [["前三項", "$3a_2=24\\Rightarrow a_2=8$"], ["後四項", "$a_2+a_5=a_3+a_4$，所以 $2(a_3+a_4)=50$，$a_3+a_4=25$：$(8+d)+(8+2d)=25\\Rightarrow d=3$。"], ["五項和", "$a_3=11$，總和 $5a_3=55$，選 (B)。"]], "tr": ""}, {"id": "115C-3", "y": 115, "p": "C", "no": 3, "ch": "C10", "img": "img/tc/115C_3.webp", "a": 2, "t": "空間兩點距離", "c": "$\\sqrt{(\\Delta x)^2+(\\Delta y)^2+(\\Delta z)^2}$。", "st": [["坐標差", "$(2-(-1),\\,4-2,\\,-1-(-3))=(3,2,2)$"], ["距離", "$\\sqrt{9+4+4}=\\sqrt{17}$，選 (C)。"]], "tr": ""}, {"id": "115C-4", "y": 115, "p": "C", "no": 4, "ch": "C01", "img": "img/tc/115C_4.webp", "a": 2, "t": "絕對值不等式：中點與半徑", "c": "$|x-c|\\le d$ 表示 $c-d\\le x\\le c+d$，$c$ 是中點、$d$ 是半寬。", "st": [["求 c、d", "$c=\\frac{54.6+55.9}{2}=55.25$，$d=\\frac{55.9-54.6}{2}=0.65$。"], ["代入", "$2c+4d=110.5+2.6=113.1$，選 (C)。"]], "tr": ""}, {"id": "115C-5", "y": 115, "p": "C", "no": 5, "ch": "C11", "img": "img/tc/115C_5.webp", "a": 3, "t": "矩陣乘法與行列式", "c": "$2\\times3$ 乘 $3\\times2$ 得 $2\\times2$；所求就是 $AB$ 的行列式。", "st": [["相乘", "$$AB=\\begin{bmatrix}1\\&-1\\&0\\\\1\\&1\\&0\\end{bmatrix}\\begin{bmatrix}0\\&1\\\\1\\&1\\\\-1\\&0\\end{bmatrix}=\\begin{bmatrix}-1\\&0\\\\1\\&2\\end{bmatrix}$$"], ["算行列式", "$c_{11}c_{22}-c_{12}c_{21}=(-1)(2)-(0)(1)=-2$，選 (D)。"]], "tr": ""}, {"id": "115C-6", "y": 115, "p": "C", "no": 6, "ch": "C14", "img": "img/tc/115C_6.webp", "a": 0, "t": "導數定義", "c": "$\\lim_{h\\to0}\\frac{f(1+h)-f(1)}{h}=f'(1)$，這裡 $f(x)=x^2+3$。", "st": [["認出函數", "分子是 $f(1+h)-f(1)$，$f(x)=x^2+3$。"], ["求導數", "$f'(x)=2x$，$f'(1)=2$，選 (A)。"]], "tr": ""}, {"id": "115C-7", "y": 115, "p": "C", "no": 7, "ch": "C15", "img": "img/tc/115C_7.webp", "a": 2, "t": "定積分的區間性質", "c": "$\\int_1^5=\\int_1^4+\\int_4^5$，且上下限交換要變號。", "st": [["翻轉", "$\\int_4^5f(x)dx=-\\int_5^4f(x)dx=-2$"], ["相加", "$\\int_1^5f(x)dx=3+(-2)=1$，選 (C)。"]], "tr": "直接 $3+2=5$，忘了上下限交換要變號。"}, {"id": "115C-8", "y": 115, "p": "C", "no": 8, "ch": "C05", "img": "img/tc/115C_8.webp", "a": 3, "t": "兩條角平分線互相垂直", "c": "兩相交直線的兩條角平分線互相垂直，且都通過交點。", "st": [["求交點", "$x+y=7$、$7x+y=25$ 相減：$6x=18$，交點 $(3,4)$。"], ["另一條斜率", "$L$ 斜率 $-2$，垂直 ⇒ 斜率 $\\frac12$。"], ["點斜式", "$y-4=\\frac12(x-3)\\Rightarrow x-2y+5=0$，選 (D)。"]], "tr": ""}, {"id": "115C-9", "y": 115, "p": "C", "no": 9, "ch": "C01", "img": "img/tc/115C_9.webp", "a": 0, "t": "二次函數圖形判斷係數", "c": "開口定 $a$、頂點位置定 $b$、$y$ 截距定 $c$、與 $x$ 軸交點數定判別式。", "st": [["判斷 a、c", "開口向下 $a\\lt 0$；與 $y$ 軸交在正半軸 $c\\gt 0$。"], ["判斷 b", "頂點在 $y$ 軸左邊：$-\\frac{b}{2a}\\lt 0$，又 $a\\lt 0$，所以 $b\\lt 0$。"], ["定象限", "$abc=(-)(-)(+)\\gt 0$；與 $x$ 軸交兩點 ⇒ $b^2-4ac\\gt 0$。點在第一象限，選 (A)。"]], "tr": "頂點在左邊就以為 $b\\gt 0$，忘了 $a$ 是負的。"}, {"id": "115C-10", "y": 115, "p": "C", "no": 10, "ch": "C09", "img": "img/tc/115C_10.webp", "a": 1, "t": "對數方程式：換元", "c": "令 $t=\\log_2x$，其他對數都化成數字。", "st": [["化簡", "$\\log_28=3$、$\\log_2\\sqrt2=\\frac12$，方程式變成 $t+3-\\frac t2=2$。"], ["解 t", "$\\frac t2=-1\\Rightarrow t=-2$"], ["求 x", "$x=2^{-2}=\\frac14$，選 (B)。"]], "tr": "$x$ 必須是正數，(A) $-2$ 是把 $t$ 當答案。"}, {"id": "115C-11", "y": 115, "p": "C", "no": 11, "ch": "C09", "img": "img/tc/115C_11.webp", "a": 3, "t": "指數成長：倍增時間", "c": "$2^{0.5t}$ 中 $t$ 每增加 2，指數增加 1，數量就乘 2。", "st": [["檢查倍增", "$N(t+2)=2026\\times2^{0.5t+1}=2N(t)$，每 2 天變兩倍，(D) 對。"], ["排除其他", "指數成長不是線性 (A)(B)；$N(0)=2026\\ne0$ (C)。選 (D)。"]], "tr": ""}, {"id": "115C-12", "y": 115, "p": "C", "no": 12, "ch": "C04", "img": "img/tc/115C_12.webp", "a": 2, "t": "部分分式：代值比較係數", "c": "兩邊通分後分子相等，代特殊值 $x=1$ 最快求 $A$。", "st": [["通分", "$x^2-2x-2=A(x^2+x+1)+(Bx+C)(x-1)$"], ["求 A", "$x=1$：$-3=3A\\Rightarrow A=-1$"], ["求 B、C", "$x^2$ 係數：$1=A+B\\Rightarrow B=2$；常數項：$-2=A-C\\Rightarrow C=1$。$A+B+C=2$，選 (C)。"]], "tr": ""}, {"id": "115C-13", "y": 115, "p": "C", "no": 13, "ch": "C07", "img": "img/tc/115C_13.webp", "a": 1, "t": "排列：指定位置先排", "c": "3 位好手排第一、三、五場；剩下兩場從其餘 9 人排。", "st": [["三位好手", "排在 3 個指定場次：$3!=6$ 種。"], ["其他兩場", "9 人選 2 人排第二、四場：$P^9_2=72$ 種。"], ["相乘", "$6\\times72=432$，選 (B)。"]], "tr": "其餘選手用組合 $C^9_2$，忘了第二、四場有順序。"}, {"id": "115C-14", "y": 115, "p": "C", "no": 14, "ch": "C08", "img": "img/tc/115C_14.webp", "a": 1, "t": "正弦定理＋面積公式", "c": "先用正弦定理求另一邊，再用 $\\frac12ab\\sin C$。", "st": [["求 BC", "$\\angle C=75^{\\circ}$。$\\frac{\\overline{BC}}{\\sin60^{\\circ}}=\\frac{4}{\\sin45^{\\circ}}\\Rightarrow\\overline{BC}=2\\sqrt6$"], ["面積", "$$\\frac12\\cdot2\\sqrt6\\cdot4\\cdot\\sin75^{\\circ}=4\\sqrt6\\cdot\\frac{\\sqrt6+\\sqrt2}{4}=6+2\\sqrt3$$選 (B)。"]], "tr": "夾角要用 $\\overline{BC}$ 與 $\\overline{AC}$ 的夾角 $\\angle C$。"}, {"id": "115C-15", "y": 115, "p": "C", "no": 15, "ch": "C02", "img": "img/tc/115C_15.webp", "a": 3, "t": "正弦圖形的週期與平移", "c": "$y=\\sin(bx-c)$ 週期 $\\frac{2\\pi}{b}$，從 $bx-c=0$ 處開始一個週期。", "st": [["看週期", "實線從 $\\frac\\pi6$ 到 $\\frac{7\\pi}6$ 是一個完整週期，長度 $\\pi$，所以 $b=2$。"], ["看起點", "起點 $x=\\frac\\pi6$：$2\\cdot\\frac\\pi6-c=0\\Rightarrow c=\\frac\\pi3$。"], ["答案", "$y=\\sin(2x-\\frac\\pi3)$，選 (D)。"]], "tr": "看到起點 $\\frac\\pi6$ 就選 $2x-\\frac\\pi6$，忘了要乘 2。"}, {"id": "115C-16", "y": 115, "p": "C", "no": 16, "ch": "C12", "img": "img/tc/115C_16.webp", "a": 1, "t": "線性規劃：頂點求範圍", "c": "可行區域是三角形，$x-y$ 的最大、最小值發生在頂點。", "st": [["找頂點", "$x+y\\le2、x\\ge0、y\\ge0$ 的頂點：$(0,0)、(2,0)、(0,2)$。"], ["代入 a=x−y", "分別得 $0、2、-2$。"], ["範圍", "$-2\\le a\\le2$，選 (B)。"]], "tr": ""}, {"id": "115C-17", "y": 115, "p": "C", "no": 17, "ch": "C05", "img": "img/tc/115C_17.webp", "a": 3, "t": "直線與圓的位置關係", "c": "圓心到直線距離小於半徑 ⇒ 直線穿過圓，有一段在圓內。", "st": [["算距離", "直線 $x-y-1=0$，圓心 $(5,2)$：$d=\\frac{|5-2-1|}{\\sqrt2}=\\sqrt2\\lt 5$。"], ["確認路徑經過", "圓心在直線上的垂足 $(4,3)$，弦長一半 $\\sqrt{25-2}\\approx4.8$，弦在 $x\\approx0.2$ 到 $8.8$ 之間，都在老鼠從 $x=-1$ 往右走的路上。"], ["結論", "會被偵測一段範圍；圓心不在直線上，碰不到攝影機。選 (D)。"]], "tr": ""}, {"id": "115C-18", "y": 115, "p": "C", "no": 18, "ch": "C15", "img": "img/tc/115C_18.webp", "a": 0, "t": "不定積分：代換法", "c": "令 $u=x^2-1$，$du=2x\\,dx$，$x\\,dx=\\frac12du$。", "st": [["代換", "$$\\int x(x^2-1)^{115}dx=\\frac12\\int u^{115}du$$"], ["積分", "$\\frac12\\cdot\\frac{u^{116}}{116}+C=\\frac{(x^2-1)^{116}}{232}+C$，選 (A)。"]], "tr": "忘了 $\\frac12$ 選 (B)。"}, {"id": "115C-19", "y": 115, "p": "C", "no": 19, "ch": "C13", "img": "img/tc/115C_19.webp", "a": 1, "t": "橢圓定義：到兩焦點距離和 2a", "c": "橢圓上任一點到兩焦點距離和 $=2a$。", "st": [["拆路徑", "總路程 $=(\\overline{FA}+\\overline{AF'})+(\\overline{F'B}+\\overline{BF})$，$A、B$ 都在橢圓上。"], ["代 2a", "$a=5$，每段和都是 $2a=10$，總共 $20$，選 (B)。"]], "tr": ""}, {"id": "115C-20", "y": 115, "p": "C", "no": 20, "ch": "C08", "img": "img/tc/115C_20.webp", "a": 3, "t": "平行四邊形面積×深度", "c": "平行四邊形面積 $=|\\overline{AB}||\\overline{AC}|\\sin\\theta$，乘深度得體積。", "st": [["面積", "$60\\times24\\sqrt3\\times\\sin120^{\\circ}=60\\times24\\sqrt3\\times\\frac{\\sqrt3}2=2160$ 平方公尺"], ["體積", "$2160\\times40=86400$，最接近 90000，選 (D)。"]], "tr": "用三角形面積公式多乘了 $\\frac12$，得 43200。"}, {"id": "115C-21", "y": 115, "p": "C", "no": 21, "ch": "C02", "img": "img/tc/115C_21.webp", "a": 0, "t": "極坐標化直角坐標", "c": "$x=r\\cos\\theta$、$y=r\\sin\\theta$、$r^2=x^2+y^2$，兩邊同乘 $r$ 再換。", "st": [["同乘 r", "$r^2=r\\sin\\theta+r\\cos\\theta\\Rightarrow x^2+y^2=x+y$"], ["配方", "$(x-\\frac12)^2+(y-\\frac12)^2=\\frac12$，是圓，選 (A)。"]], "tr": ""}, {"id": "115C-22", "y": 115, "p": "C", "no": 22, "ch": "C14", "img": "img/tc/115C_22.webp", "a": 2, "t": "湊出導數定義", "c": "分子加減 $2f(2)$，拆成「常數」與「導數定義」兩部分。", "st": [["拆分子", "$xf(2)-2f(x)=(x-2)f(2)-2[f(x)-f(2)]$"], ["取極限", "$$\\lim_{x\\to2}\\left[f(2)-2\\cdot\\frac{f(x)-f(2)}{x-2}\\right]=f(2)-2f'(2)$$"], ["代值", "$115-230=-115$，選 (C)。"]], "tr": ""}, {"id": "115C-23", "y": 115, "p": "C", "no": 23, "ch": "C03", "img": "img/tc/115C_23.webp", "a": 2, "t": "點到直線距離", "c": "軌道是過原點、方向 $(1,2)$ 的直線 $2x-y=0$。", "st": [["砲彈位置", "$t=2$：$(6,8)$"], ["軌道方程式", "方向 $(1,2)$ ⇒ 斜率 2，直線 $2x-y=0$。"], ["距離", "$\\frac{|12-8|}{\\sqrt{5}}=\\frac4{\\sqrt5}$，選 (C)。"]], "tr": ""}, {"id": "115C-24", "y": 115, "p": "C", "no": 24, "ch": "C11", "img": "img/tc/115C_24.webp", "a": 2, "t": "增廣矩陣與列運算", "c": "列運算不改變聯立方程式的解；化簡後的矩陣表示 $x=2、y=3$。", "st": [["讀出解", "$\\begin{bmatrix}1\\&0\\&2\\\\0\\&1\\&3\\end{bmatrix}$ 表示 $x=2$、$y=3$。"], ["代回原方程", "$ax+y=11$：$2a+3=11\\Rightarrow a=4$；$x+by=5$：$2+3b=5\\Rightarrow b=1$。"], ["相加", "$a+b=5$，選 (C)。"]], "tr": ""}, {"id": "115C-25", "y": 115, "p": "C", "no": 25, "ch": "C08", "img": "img/tc/115C_25.webp", "a": 0, "t": "和角公式＋疊合求最大值", "c": "展開成 $p\\cos\\theta+q\\sin\\theta$，最大值是 $\\sqrt{p^2+q^2}$。", "st": [["展開", "$\\sqrt3\\sin(\\frac\\pi3-\\theta)=\\sqrt3(\\frac{\\sqrt3}2\\cos\\theta-\\frac12\\sin\\theta)=\\frac32\\cos\\theta-\\frac{\\sqrt3}2\\sin\\theta$"], ["合併", "$f(\\theta)=\\frac52\\cos\\theta-\\frac{\\sqrt3}2\\sin\\theta$"], ["最大值", "$\\sqrt{\\frac{25}4+\\frac34}=\\sqrt7$，選 (A)。"]], "tr": "把兩項最大值相加得 $\\sqrt3+1$，但它們不會同時取到最大。"}];
